(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-047"]={"sura":47,"name_ar":"محمد","name_en":"Muhammad","verses":38,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":38,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=3\" class=\"link\">47:3</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:3 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=3\" class=\"link\">47:3</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:3 ஐ பார்க்கவும்"},"3":{"html":"<strong>இது மதீனாவில் அருளப்பட்டது</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<strong>நிராகரிப்பாளர்கள் மற்றும் இறைநம்பிக்கையாளர்களின் பிரதிபலன் பற்றி அல்லாஹ் கூறுகிறான்:</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ﴿</span><br />\r\n<br />\r\n(யார் நிராகரித்தார்களோ) அதாவது, அல்லாஹ்வின் வசனங்களை (ஆயத்களை) நிராகரித்தவர்கள்.<span class=\"quran-arabic-font text-success\">﴾وَصَدُّواْ﴿</span><br />\r\n<br />\r\n(மேலும் தடுத்தார்களோ) மற்றவர்களை.<span class=\"quran-arabic-font text-success\">﴾عَن</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">أَضَلَّ</span> <span class=\"quran-arabic-font text-success\">أَعْمَالَهُمْ﴿</span><br />\r\n<br />\r\n(அல்லாஹ்வின் பாதையிலிருந்து, அவர்களின் செயல்களை அவன் வீணாக்கிவிட்டான்.) அதாவது, அவர்களுடைய செயல்களை அவன் வீணானதாகவும் பயனற்றதாகவும் ஆக்குகிறான்; அச்செயல்களுக்கு எவ்வித நற்பலன்களையோ அல்லது அருட்கொடைகளையோ அவன் அவர்களுக்கு வழங்குவதில்லை. இது அவன் கூறுவதைப் போன்றதாகும்:<span class=\"quran-arabic-font text-success\">﴾وَقَدِمْنَآ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">عَمِلُواْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عَمَلٍ</span> <span class=\"quran-arabic-font text-success\">فَجَعَلْنَاهُ</span> <span class=\"quran-arabic-font text-success\">هَبَآءً</span> <span class=\"quran-arabic-font text-success\">مَّنثُوراً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவர்கள் செய்த செயல்களை நாம் கவனித்து, அவற்றைச் சிதறிய தூசியாக ஆக்கிவிடுவோம்.) (<a href=\"qurandisp.php?sura=25&ayah=23\" class=\"link\">25:23</a>) பின்னர் அல்லாஹ் கூறுகிறான்,<span class=\"quran-arabic-font text-success\">﴾وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">وَعَمِلُواْ</span> <span class=\"quran-arabic-font text-success\">الصَّـلِحَاتِ﴿</span><br />\r\n<br />\r\n(மேலும், யார் ஈமான் கொண்டு நற்செயல்கள் செய்தார்களோ,) இதன் பொருள், அவர்களுடைய உள்ளங்களும் ஆன்மாக்களும் ஈமான் கொண்டுள்ளன; மேலும் அவர்களுடைய உடல் உறுப்புகளும், அவர்களின் மறைவான மற்றும் வெளிப்படையான செயல்களும் அல்லாஹ்வின் சட்டத்திற்கு அடிபணிந்துள்ளன என்பதாகும்.<span class=\"quran-arabic-font text-success\">﴾وَءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">نُزِّلَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مُحَمَّدٍ﴿</span><br />\r\n<br />\r\n(மேலும் முஹம்மது (ஸல்) அவர்களுக்கு அருளப்பட்டதை அவர்கள் நம்பினார்களோ) முந்தைய வாக்கியத்துடன் இந்த வாசகத்தைச் சேர்த்திருப்பது, ஒரு பொதுவான விஷயத்திற்கு ஒரு குறிப்பிட்ட சிறப்பைச் சேர்க்கும் முறையாகும். முஹம்மது (ஸல்) அவர்களின் வருகைக்குப் பிறகு, அவர்களை ஈமான் கொள்வது (நம்புவது) உண்மையான இறைநம்பிக்கைக்கு அவசியமான நிபந்தனை என்பதற்கு இது ஆதாரமாக உள்ளது. பின்னர் அல்லாஹ் கூறுகிறான்,<span class=\"quran-arabic-font text-success\">﴾وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رَّبِّهِمْ﴿</span><br />\r\n<br />\r\n(ஏனெனில் அது அவர்களின் இறைவனிடமிருந்து வந்த உண்மையாகும்.) இது மிகவும் நேர்த்தியாக அமைந்த ஒரு இடைச்சொற்றொடர் ஆகும். ஆக, அல்லாஹ் கூறுகிறான்,<span class=\"quran-arabic-font text-success\">﴾كَفَّرَ</span> <span class=\"quran-arabic-font text-success\">عَنْهُمْ</span> <span class=\"quran-arabic-font text-success\">سَيِّئَاتِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَأَصْلَحَ</span> <span class=\"quran-arabic-font text-success\">بَالَهُمْ﴿</span><br />\r\n<br />\r\n(அவன் அவர்களின் தீமைகளை அவர்களை விட்டும் போக்கி, அவர்களின் நிலையை (பால்) சீராக்கினான்.) இப்னு அப்பாஸ் (ரழி) அவர்கள், \"இதன் பொருள் அவர்களுடைய விஷயம்\" என்று கூறினார்கள். முஜாஹித் அவர்கள், \"இதன் பொருள் அவர்களுடைய காரியம்\" என்று கூறினார்கள். கத்தாதா மற்றும் இப்னு ஸைத் ஆகிய இருவரும், \"அவர்களுடைய நிலை\" என்று கூறினார்கள். இவை அனைத்தும் ஒத்த கருத்துடையவை ஆகும். தும்முபவருக்குப் பதிலளிப்பது குறித்த ஹதீஸில் நபி (ஸல்) அவர்களிடமிருந்து இவ்வாறு கூறப்பட்டுள்ளது:<span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">يَهْدِيكُمُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">وَيُصْلِحُ</span> <span class=\"quran-arabic-font text-success\">بَالَكُم</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அல்லாஹ் உங்களுக்கு நேர்வழி காட்டி, உங்கள் நிலையை (பால்) சீராக்குவானாக.) பின்னர் அல்லாஹ் கூறுகிறான்,<span class=\"quran-arabic-font text-success\">﴾ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">بِأَنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">اتَّبَعُواْ</span> <span class=\"quran-arabic-font text-success\">الْبَاطِلَ﴿</span><br />\r\n<br />\r\n(அது ஏனென்றால், நிராகரிப்பாளர்கள் அசத்தியத்தைப் (பொய்யை) பின்பற்றுகிறார்கள்,) அதாவது, 'நிராகரிப்பவர்களின் செயல்களை நாம் வீணாக்குவதும், நல்லோரின் பாவங்களை மன்னித்து அவர்களின் விவகாரங்களைச் சீராக்குவதும் ஏன் என்றால், நிராகரிப்பாளர்கள் சத்தியத்திற்குப் பதிலாக அசத்தியத்தையே தேர்ந்தெடுக்கிறார்கள்.'<span class=\"quran-arabic-font text-success\">﴾وَأَنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">اتَّبَعُواْ</span> <span class=\"quran-arabic-font text-success\">الْحَقَّ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رَّبِّهِمْ</span> <span class=\"quran-arabic-font text-success\">كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">يَضْرِبُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لِلنَّاسِ</span> <span class=\"quran-arabic-font text-success\">أَمْثَالَهُمْ﴿</span><br />\r\n<br />\r\n(அதே சமயம், இறைநம்பிக்கையாளர்கள் தங்கள் இறைவனிடமிருந்து வந்த சத்தியத்தைப் பின்பற்றுகிறார்கள். இவ்வாறே அல்லாஹ் மக்களுக்கு அவர்களின் உவமைகளை எடுத்துரைக்கிறான்.) இவ்வாறு அல்லாஹ் அவர்களின் செயல்களின் விளைவுகளை அவர்களுக்குத் தெளிவுபடுத்துகிறான்; மேலும் மறுமை வாழ்வில் அவர்கள் சென்றடையும் இடத்தையும் அவர்களுக்குக் காட்டுகிறான். அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"இது மதீனாவில் அருளப்பட்டது\n\r\n\n\r\n﴾بِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ ﴿\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nநிராகரிப்பாளர்கள் மற்றும் இறைநம்பிக்கையாளர்களின் பிரதிபலன் பற்றி அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾الَّذِينَ كَفَرُواْ﴿\n\r\n\n\r\n(யார் நிராகரித்தார்களோ) அதாவது, அல்லாஹ்வின் வசனங்களை (ஆயத்களை) நிராகரித்தவர்கள்.﴾وَصَدُّواْ﴿\n\r\n\n\r\n(மேலும் தடுத்தார்களோ) மற்றவர்களை.﴾عَن سَبِيلِ اللَّهِ أَضَلَّ أَعْمَالَهُمْ﴿\n\r\n\n\r\n(அல்லாஹ்வின் பாதையிலிருந்து, அவர்களின் செயல்களை அவன் வீணாக்கிவிட்டான்.) அதாவது, அவர்களுடைய செயல்களை அவன் வீணானதாகவும் பயனற்றதாகவும் ஆக்குகிறான்; அச்செயல்களுக்கு எவ்வித நற்பலன்களையோ அல்லது அருட்கொடைகளையோ அவன் அவர்களுக்கு வழங்குவதில்லை. இது அவன் கூறுவதைப் போன்றதாகும்:﴾وَقَدِمْنَآ إِلَى مَا عَمِلُواْ مِنْ عَمَلٍ فَجَعَلْنَاهُ هَبَآءً مَّنثُوراً ﴿\n\r\n\n\r\n(அவர்கள் செய்த செயல்களை நாம் கவனித்து, அவற்றைச் சிதறிய தூசியாக ஆக்கிவிடுவோம்.) (25:23) பின்னர் அல்லாஹ் கூறுகிறான்,﴾وَالَّذِينَ ءَامَنُواْ وَعَمِلُواْ الصَّـلِحَاتِ﴿\n\r\n\n\r\n(மேலும், யார் ஈமான் கொண்டு நற்செயல்கள் செய்தார்களோ,) இதன் பொருள், அவர்களுடைய உள்ளங்களும் ஆன்மாக்களும் ஈமான் கொண்டுள்ளன; மேலும் அவர்களுடைய உடல் உறுப்புகளும், அவர்களின் மறைவான மற்றும் வெளிப்படையான செயல்களும் அல்லாஹ்வின் சட்டத்திற்கு அடிபணிந்துள்ளன என்பதாகும்.﴾وَءَامَنُواْ بِمَا نُزِّلَ عَلَى مُحَمَّدٍ﴿\n\r\n\n\r\n(மேலும் முஹம்மது (ஸல்) அவர்களுக்கு அருளப்பட்டதை அவர்கள் நம்பினார்களோ) முந்தைய வாக்கியத்துடன் இந்த வாசகத்தைச் சேர்த்திருப்பது, ஒரு பொதுவான விஷயத்திற்கு ஒரு குறிப்பிட்ட சிறப்பைச் சேர்க்கும் முறையாகும். முஹம்மது (ஸல்) அவர்களின் வருகைக்குப் பிறகு, அவர்களை ஈமான் கொள்வது (நம்புவது) உண்மையான இறைநம்பிக்கைக்கு அவசியமான நிபந்தனை என்பதற்கு இது ஆதாரமாக உள்ளது. பின்னர் அல்லாஹ் கூறுகிறான்,﴾وَهُوَ الْحَقُّ مِن رَّبِّهِمْ﴿\n\r\n\n\r\n(ஏனெனில் அது அவர்களின் இறைவனிடமிருந்து வந்த உண்மையாகும்.) இது மிகவும் நேர்த்தியாக அமைந்த ஒரு இடைச்சொற்றொடர் ஆகும். ஆக, அல்லாஹ் கூறுகிறான்,﴾كَفَّرَ عَنْهُمْ سَيِّئَاتِهِمْ وَأَصْلَحَ بَالَهُمْ﴿\n\r\n\n\r\n(அவன் அவர்களின் தீமைகளை அவர்களை விட்டும் போக்கி, அவர்களின் நிலையை (பால்) சீராக்கினான்.) இப்னு அப்பாஸ் (ரழி) அவர்கள், \"இதன் பொருள் அவர்களுடைய விஷயம்\" என்று கூறினார்கள். முஜாஹித் அவர்கள், \"இதன் பொருள் அவர்களுடைய காரியம்\" என்று கூறினார்கள். கத்தாதா மற்றும் இப்னு ஸைத் ஆகிய இருவரும், \"அவர்களுடைய நிலை\" என்று கூறினார்கள். இவை அனைத்தும் ஒத்த கருத்துடையவை ஆகும். தும்முபவருக்குப் பதிலளிப்பது குறித்த ஹதீஸில் நபி (ஸல்) அவர்களிடமிருந்து இவ்வாறு கூறப்பட்டுள்ளது:﴾«يَهْدِيكُمُ اللهُ وَيُصْلِحُ بَالَكُم»﴿\n\r\n\n\r\n(அல்லாஹ் உங்களுக்கு நேர்வழி காட்டி, உங்கள் நிலையை (பால்) சீராக்குவானாக.) பின்னர் அல்லாஹ் கூறுகிறான்,﴾ذَلِكَ بِأَنَّ الَّذِينَ كَفَرُواْ اتَّبَعُواْ الْبَاطِلَ﴿\n\r\n\n\r\n(அது ஏனென்றால், நிராகரிப்பாளர்கள் அசத்தியத்தைப் (பொய்யை) பின்பற்றுகிறார்கள்,) அதாவது, 'நிராகரிப்பவர்களின் செயல்களை நாம் வீணாக்குவதும், நல்லோரின் பாவங்களை மன்னித்து அவர்களின் விவகாரங்களைச் சீராக்குவதும் ஏன் என்றால், நிராகரிப்பாளர்கள் சத்தியத்திற்குப் பதிலாக அசத்தியத்தையே தேர்ந்தெடுக்கிறார்கள்.'﴾وَأَنَّ الَّذِينَ ءَامَنُواْ اتَّبَعُواْ الْحَقَّ مِن رَّبِّهِمْ كَذَلِكَ يَضْرِبُ اللَّهُ لِلنَّاسِ أَمْثَالَهُمْ﴿\n\r\n\n\r\n(அதே சமயம், இறைநம்பிக்கையாளர்கள் தங்கள் இறைவனிடமிருந்து வந்த சத்தியத்தைப் பின்பற்றுகிறார்கள். இவ்வாறே அல்லாஹ் மக்களுக்கு அவர்களின் உவமைகளை எடுத்துரைக்கிறான்.) இவ்வாறு அல்லாஹ் அவர்களின் செயல்களின் விளைவுகளை அவர்களுக்குத் தெளிவுபடுத்துகிறான்; மேலும் மறுமை வாழ்வில் அவர்கள் சென்றடையும் இடத்தையும் அவர்களுக்குக் காட்டுகிறான். அல்லாஹ்வே மிக அறிந்தவன்."},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=9\" class=\"link\">47:9</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:9 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=9\" class=\"link\">47:9</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:9 ஐ பார்க்கவும்"},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=9\" class=\"link\">47:9</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:9 ஐ பார்க்கவும்"},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=9\" class=\"link\">47:9</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:9 ஐ பார்க்கவும்"},"8":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=9\" class=\"link\">47:9</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:9 ஐ பார்க்கவும்"},"9":{"html":"<strong>எதிரிகளின் கழுத்துகளை வெட்டுவதற்கும், அவர்களைக் கட்டி வைப்பதற்கும், பின்னர் கருணை காட்டியோ அல்லது ஈட்டுத்தொகை பெற்றுக்கொண்டோ அவர்களை விடுதலை செய்வதற்கும் உள்ள கட்டளை</strong><br />\r\n<br />\r\nஇணைவைப்பவர்களுக்கு எதிரான போர்களில் நம்பிக்கையாளர்கள் எத்தகைய வழிமுறைகளைக் கையாள வேண்டும் என்று வழிகாட்டும் விதமாக அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">لَقِيتُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">فَضَرْبَ</span> <span class=\"quran-arabic-font text-success\">الرِّقَابِ</span><br />\r\n<br />\r\n(ஆகவே, (போர்க்களத்தில்) நிராகரிப்பவர்களை நீங்கள் சந்திக்கும்போது, அவர்களின் கழுத்துகளை வெட்டுங்கள்.) அதாவது, நீங்கள் அவர்களுடன் போரிடும்போது, உங்கள் வாள்களால் அவர்களை முழுமையாக வெட்டி வீழ்த்துங்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">إِذَآ</span> <span class=\"quran-arabic-font text-success\">أَثْخَنتُمُوهُمْ</span><br />\r\n<br />\r\n(நீங்கள் அவர்களை முழுமையாகத் தோற்கடிக்கும் வரை,) அதாவது, நீங்கள் அவர்களைக் கொன்று, முற்றிலுமாக நிலைகுலையச் செய்யும் வரை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَشُدُّواْ</span> <span class=\"quran-arabic-font text-success\">الْوَثَاقَ</span><br />\r\n<br />\r\n(அவர்களின் கட்டுகளை இறுக்குங்கள்.) <span class=\"quran-arabic-font text-success\">فَإِمَّا</span> <span class=\"quran-arabic-font text-success\">مَنًّا</span> <span class=\"quran-arabic-font text-success\">بَعْدُ</span> <span class=\"quran-arabic-font text-success\">وَإِمَّا</span> <span class=\"quran-arabic-font text-success\">فِدَآءً</span> (அதன் பின்னர், (அவர்கள் மீது) கருணை காட்டுங்கள்; அல்லது ஈட்டுத்தொகை பெற்றுக் கொள்ளுங்கள்.) இது நீங்கள் பிடித்துள்ள போர்க்கைதிகளைக் குறிக்கிறது. பின்னர், போர் முடிந்து மோதல்கள் நின்ற பிறகு, கைதிகள் விஷயத்தில் உங்களுக்கு இரு வாய்ப்புகள் உள்ளன: ஒன்று, அவர்கள் மீது கருணை காட்டி எவ்விதப் பிரதிபலனும் இன்றி விடுதலை செய்யலாம்; அல்லது அவர்களிடமிருந்து ஈட்டுத்தொகையைப் பெற்றுக்கொண்டு விடுதலை செய்யலாம். இந்த வசனம் பத்ருப் போருக்குப் பிறகு அருளப்பட்டதாகத் தெரிகிறது. அப்போது, எதிரிப் படையினரில் பலரை உயிருடன் விட்டதற்காகவும், ஈட்டுத்தொகை பெறும் நோக்கில் அதிக கைதிகளைப் பிடித்து வைத்திருந்ததற்காகவும் அல்லாஹ் நம்பிக்கையாளர்களைக் கண்டித்தான். அப்போது அவன் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">لِنَبِىٍّ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَكُونَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">أَسْرَى</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يُثْخِنَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">تُرِيدُونَ</span> <span class=\"quran-arabic-font text-success\">عَرَضَ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">يُرِيدُ</span> <span class=\"quran-arabic-font text-success\">الْآخِرَةَ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَزِيزٌ</span> <span class=\"quran-arabic-font text-success\">حَكِيمٌ</span> - <span class=\"quran-arabic-font text-success\">لَّوْلاَ</span> <span class=\"quran-arabic-font text-success\">كِتَـبٌ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">سَبَقَ</span> <span class=\"quran-arabic-font text-success\">لَمَسَّكُمْ</span> <span class=\"quran-arabic-font text-success\">فِيمَآ</span> <span class=\"quran-arabic-font text-success\">أَخَذْتُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابٌ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٌ</span><br />\r\n<br />\r\n(ஒரு நபி, பூமியில் (எதிரிகளை) முற்றிலும் வீழ்த்தும் வரை அவருக்குப் போர்க்கைதிகள் இருப்பது தகுதியல்ல. நீங்கள் இவ்வுலகின் ஆதாயங்களை விரும்புகிறீர்கள், ஆனால் அல்லாஹ்வோ (உங்களுக்கு) மறுமையை நாடுகிறான். அல்லாஹ் மிகைத்தவனும் ஞானமிக்கவனுமாவான். அல்லாஹ்விடமிருந்து முன்கூட்டியே எழுதப்பட்ட ஒரு விதி இல்லையெனில், நீங்கள் (கைதிகளுக்காக)ப் பெற்றுக்கொண்ட ஈட்டுத்தொகைக்காக உங்களைக் கடுமையான வேதனை தீண்டியிருக்கும்.) (<a href=\"qurandisp.php?sura=8&ayah=67\" class=\"link\">8:67</a>-68) அல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">تَضَعَ</span> <span class=\"quran-arabic-font text-success\">الْحَرْبُ</span> <span class=\"quran-arabic-font text-success\">أَوْزَارَهَا</span><br />\r\n<br />\r\n(...போர் அதன் சுமைகளை இறக்கி வைக்கும் வரை.) முஜாஹித் அவர்கள் கூறுகையில், \"ஈஸா இப்னு மர்யம் (அலை) அவர்கள் இறங்கும் வரை\" என்று குறிப்பிட்டார்கள். நபி (ஸல்) அவர்களின் பின்வரும் பொன்மொழியிலிருந்து அவர்கள் இந்தக் கருத்தைப் பெற்றிருக்கலாம் என்று தெரிகிறது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَزَالُ</span> <span class=\"quran-arabic-font text-success\">طَائِفَةٌ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أُمَّتِي</span> <span class=\"quran-arabic-font text-success\">ظَاهِرِينَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْحَقِّ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يُقَاتِلَ</span> <span class=\"quran-arabic-font text-success\">آخِرُهُمُ</span> <span class=\"quran-arabic-font text-success\">الدَّجَّال</span>»<br />\r\n<br />\r\n(என் உம்மத்தில் ஒரு கூட்டத்தினர் சத்தியத்தின் மீது வெற்றி பெற்றவர்களாகத் தொடர்ந்து இருந்து கொண்டே இருப்பார்கள், அவர்களில் கடைசிப் பிரிவினர் தஜ்ஜாலுடன் போர் புரியும் வரை.) இமாம் அஹ்மத் அவர்கள், ஜுபைர் இப்னு நுஃபைர் வழியாக ஸலமா இப்னு நுஃபைல் (ரழி) அவர்களிடமிருந்து பின்வருமாறு பதிவு செய்துள்ளார்கள்: அவர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் வந்து, \"நான் என் குதிரையை அவிழ்த்து விட்டுவிட்டேன், என் ஆயுதத்தையும் கீழே போட்டுவிட்டேன். ஏனெனில் போர் முடிந்துவிட்டது, இனி சண்டை எதுவும் இல்லை\" என்று கூறினார். அப்போது நபி (ஸல்) அவர்கள் அவரிடம் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الْآنَ</span> <span class=\"quran-arabic-font text-success\">جَاءَ</span> <span class=\"quran-arabic-font text-success\">الْقِتَالُ،</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَزَالُ</span> <span class=\"quran-arabic-font text-success\">طَائِفَةٌ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أُمَّتِي</span> <span class=\"quran-arabic-font text-success\">ظَاهِرِينَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">النَّاسِ،</span> <span class=\"quran-arabic-font text-success\">يُزِيغُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">قُلُوبَ</span> <span class=\"quran-arabic-font text-success\">أَقْوَام،</span> <span class=\"quran-arabic-font text-success\">فَيُقَاتِلُونَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَيَرْزُقُهُمُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يَأْتِيَ</span> <span class=\"quran-arabic-font text-success\">أَمْرُ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ،</span> <span class=\"quran-arabic-font text-success\">أَلَا</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">عُقْرَ</span> <span class=\"quran-arabic-font text-success\">دَارِ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">الشَّامُ،</span> <span class=\"quran-arabic-font text-success\">وَالْخَيْلُ</span> <span class=\"quran-arabic-font text-success\">مَعْقُودٌ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">نَوَاصِيهَا</span> <span class=\"quran-arabic-font text-success\">الْخَيْرُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">يَوْمِ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَة</span>»<br />\r\n<br />\r\n(இப்போதுதான் போருக்கான நேரம் வந்துள்ளது. என் உம்மத்தில் ஒரு கூட்டத்தினர் மக்கள் மீது மேலோங்கியவர்களாகத் தொடர்ந்து இருந்து கொண்டே இருப்பார்கள். அல்லாஹ் சில சமூகத்தாரின் இதயங்களை (உண்மையிலிருந்து) திசை திருப்புவான்; எனவே இவர்கள் அவர்களுக்கு எதிராகப் போரிடுவார்கள். அல்லாஹ் அவர்களுக்கு அவர்களிடமிருந்து (எதிரிகளிடமிருந்து) போர்ச் செல்வங்களை வழங்குவான் -- அல்லாஹ்வின் கட்டளை வரும் வரை அவர்கள் இதே நிலையிலேயே இருப்பார்கள். அறிந்து கொள்க! நம்பிக்கையாளர்களின் வசிப்பிடத்தின் மையம் அஷ்-ஷாம் ஆகும். மேலும், மறுமை நாள் வரை குதிரைகளின் நெற்றிகளில் நன்மைகள் பிணைக்கப்பட்டுள்ளன.) அன்-நஸாயீயும் இந்த அறிவிப்பைப் பதிவு செய்துள்ளார். பின்னர் அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لاَنْتَصَرَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span><br />\r\n<br />\r\n(நிலைமை இதுதான். அல்லாஹ் நாடியிருந்தால், அவன் அவர்களிடமிருந்து (நேரடியாகப்) பழிவாங்கியிருப்பான்;) அதாவது, அல்லாஹ் நாடியிருந்தால், நிராகரிப்பாளர்களைத் தன்பக்கமிருந்து நேரடியாக ஒரு வேதனை அல்லது தண்டனையின் மூலம் உடனடியாக அழித்திருப்பான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَـكِن</span> <span class=\"quran-arabic-font text-success\">لِّيَبْلُوَ</span> <span class=\"quran-arabic-font text-success\">بَعْضَكُمْ</span> <span class=\"quran-arabic-font text-success\">بِبَعْضٍ</span><br />\r\n<br />\r\n(ஆனால், உங்களில் ஒருவரை மற்றவர் மூலம் சோதிப்பதற்காகவே (போரை விதித்தான்).) அதாவது, உங்களைச் சோதிப்பதற்கும் உங்கள் நிலையை அறியச் செய்வதற்காகவுமே ஜிஹாத் மற்றும் எதிரிகளுக்கு எதிரான போரை அவன் கடமையாக்கியுள்ளான். அல்லாஹ் ஜிஹாத்தை விதித்ததன் ஞானத்தை ஆல இம்ரான் மற்றும் அத்தவ்பா ஆகிய அத்தியாயங்களிலும் விளக்குகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">حَسِبْتُمْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَدْخُلُواْ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةَ</span> <span class=\"quran-arabic-font text-success\">وَلَمَّا</span> <span class=\"quran-arabic-font text-success\">يَعْلَمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">جَـهَدُواْ</span> <span class=\"quran-arabic-font text-success\">مِنكُمْ</span> <span class=\"quran-arabic-font text-success\">وَيَعْلَمَ</span> <span class=\"quran-arabic-font text-success\">الصَّـبِرِينَ</span><br />\r\n<br />\r\n(அல்லது, உங்களில் போரிடுபவர்களையும், பொறுமையாளர்களையும் அல்லாஹ் அடையாளம் காட்டாத நிலையில், நீங்கள் சொர்க்கத்தில் நுழைந்து விடலாம் என்று எண்ணிக் கொண்டீர்களா?) (<a href=\"qurandisp.php?sura=3&ayah=142\" class=\"link\">3:142</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَـتِلُوهُمْ</span> <span class=\"quran-arabic-font text-success\">يُعَذِّبْهُمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">بِأَيْدِيكُمْ</span> <span class=\"quran-arabic-font text-success\">وَيُخْزِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَيَنْصُرْكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">وَيَشْفِ</span> <span class=\"quran-arabic-font text-success\">صُدُورَ</span> <span class=\"quran-arabic-font text-success\">قَوْمٍ</span> <span class=\"quran-arabic-font text-success\">مُّؤْمِنِينَ</span> - <span class=\"quran-arabic-font text-success\">وَيُذْهِبْ</span> <span class=\"quran-arabic-font text-success\">غَيْظَ</span> <span class=\"quran-arabic-font text-success\">قُلُوبِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَيَتُوبُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ</span> <span class=\"quran-arabic-font text-success\">حَكِيمٌ</span><br />\r\n<br />\r\n(அவர்களுடன் போரிடுங்கள்; அல்லாஹ் உங்கள் கைகளைக் கொண்டு அவர்களைத் தண்டிப்பான், அவர்களை இழிவுபடுத்துவான், அவர்களுக்கு எதிராக உங்களுக்கு வெற்றி அளிப்பான், நம்பிக்கையுள்ள மக்களின் இதயங்களை ஆற்றுப்படுத்துவான். மேலும் அவர்களின் (நம்பிக்கையாளர்களின்) உள்ளங்களில் உள்ள ஆத்திரத்தைப் போக்குவான். அல்லாஹ் தான் நாடியவர்களின் மன்னிப்பை ஏற்றுக் கொள்கிறான். அல்லாஹ் அறிந்தவனும் ஞானமிக்கவனுமாவான்.) (<a href=\"qurandisp.php?sura=9&ayah=14\" class=\"link\">9:14</a>-15)<br />\r\n<br />\r\n<strong>தியாகிகளின் மேன்மை</strong><br />\r\n<br />\r\nபோர்களின் போது பல நம்பிக்கையாளர்கள் உயிர் தியாகம் செய்வது வழக்கம் என்பதால், அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">قُتِلُواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">فَلَن</span> <span class=\"quran-arabic-font text-success\">يُضِلَّ</span> <span class=\"quran-arabic-font text-success\">أَعْمَـلَهُمْ</span><br />\r\n<br />\r\n(அல்லாஹ்வின் பாதையில் கொல்லப்பட்டவர்களின் செயல்களை அவன் ஒருபோதும் வீணாக்க மாட்டான்.) அதாவது, அவர்களின் நற்செயல்கள் அழிந்து போக அவன் விடமாட்டான்; மாறாக அவற்றை மென்மேலும் வளர்ப்பான். அவர்களில் சிலர் அல்-பர்ஸக் (திரைமறைவு வாழ்க்கை) காலத்தில் இருக்கும் வரை அவர்களின் நற்செயல்களுக்கான கூலி தொடர்ந்து வழங்கப்பட்டு வரும். இது குறித்து இமாம் அஹ்மத் அவர்கள் தனது முஸ்னதில் கதீர் இப்னு முர்ரா வழியாக கைஸ் அல்-ஜுதாமி (ரழி) அவர்கள் அறிவித்த ஹதீஸைப் பதிவு செய்துள்ளார்கள். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يُعْطَى</span> <span class=\"quran-arabic-font text-success\">الشَّهِيدُ</span> <span class=\"quran-arabic-font text-success\">سِتَّ</span> <span class=\"quran-arabic-font text-success\">خِصَالٍ</span> <span class=\"quran-arabic-font text-success\">عِنْدَ</span> <span class=\"quran-arabic-font text-success\">أَوَّلِ</span> <span class=\"quran-arabic-font text-success\">قَطْرَةٍ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">دَمِهِ</span>: <span class=\"quran-arabic-font text-success\">تُكَفَّرُ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">خَطِيئَةٍ،</span> <span class=\"quran-arabic-font text-success\">وَيَرَى</span> <span class=\"quran-arabic-font text-success\">مَقْعَدَهُ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ،</span> <span class=\"quran-arabic-font text-success\">وَيُزَوَّجُ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْحُورِ</span> <span class=\"quran-arabic-font text-success\">الْعِين،</span> <span class=\"quran-arabic-font text-success\">وَيَأْمَنُ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْفَزَعِ</span> <span class=\"quran-arabic-font text-success\">الْأَكْبَرِ،</span> <span class=\"quran-arabic-font text-success\">وَمِنْ</span> <span class=\"quran-arabic-font text-success\">عَذَابِ</span> <span class=\"quran-arabic-font text-success\">الْقَبْرِ،</span> <span class=\"quran-arabic-font text-success\">وَيُحَلَّى</span> <span class=\"quran-arabic-font text-success\">حُلَّةَ</span> <span class=\"quran-arabic-font text-success\">الْإِيمَان</span>»<br />\r\n<br />\r\n(இரத்தத்தின் முதல் துளி வெளிப்படும் போதே, ஒரு ஷஹீதுக்கு ஆறு சிறப்புகள் வழங்கப்படுகின்றன: அவருடைய பாவங்கள் அனைத்தும் மன்னிக்கப்படுகின்றன; சொர்க்கத்தில் அவருக்குரிய இடம் அவருக்குக் காட்டப்படுகிறது; அகன்ற விழிகளையுடைய ஹூருல் ஈன்களுடன் அவருக்குத் திருமணம் செய்து வைக்கப்படுகிறது; (மறுமையின்) பெரும் திடுக்கத்திலிருந்தும் கப்ரின் வேதனையிலிருந்தும் அவருக்குப் பாதுகாப்பு அளிக்கப்படுகிறது; மேலும் அவருக்கு ஈமானின் ஆபரணங்கள் அணிவிக்கப்படுகின்றன.) அஹ்மத் இந்த ஹதீஸைத் தனியாகப் பதிவு செய்துள்ளார். அபுத்தர்தா (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يُشَفَّعُ</span> <span class=\"quran-arabic-font text-success\">الشَّهِيدُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">سَبْعِينَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">بَيْتِه</span>»<br />\r\n<br />\r\n(ஒரு தியாகி தனது குடும்பத்தாரில் எழுபது பேருக்காகப் பரிந்துரை செய்ய அனுமதிக்கப்படுவார்.) இதனை அபூ தாவூத் பதிவு செய்துள்ளார். மேலும் தியாகிகளின் சிறப்புகளைக் கூறும் இன்னும் பல ஹதீஸ்கள் உள்ளன. அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سَيَهْدِيهِمْ</span><br />\r\n<br />\r\n(அவன் அவர்களுக்கு நல்வழி காட்டுவான்.) அதாவது, அவர்களை ஜன்னாவிற்கு (சொர்க்கத்திற்கு) அழைத்துச் செல்வான். இது அல்லாஹ்வின் பின்வரும் கூற்றைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">وَعَمِلُواْ</span> <span class=\"quran-arabic-font text-success\">الصَّـلِحَاتِ</span> <span class=\"quran-arabic-font text-success\">يَهْدِيهِمْ</span> <span class=\"quran-arabic-font text-success\">رَبُّهُمْ</span> <span class=\"quran-arabic-font text-success\">بِإِيمَانِهِمْ</span> <span class=\"quran-arabic-font text-success\">تَجْرِى</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">تَحْتِهِمُ</span> <span class=\"quran-arabic-font text-success\">الاٌّنْهَـرُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">جَنَّـتِ</span> <span class=\"quran-arabic-font text-success\">النَّعِيمِ</span><br />\r\n<br />\r\n(நிச்சயமாக நம்பிக்கை கொண்டு நற்செயல்கள் புரிந்தவர்களுக்கு, அவர்களின் ஈமானின் காரணமாக அவர்களது இறைவன் நேர்வழி காட்டுவான்; இன்பம் நிறைந்த சொர்க்கச் சோலைகளில் அவர்களுக்குக் கீழ் ஆறுகள் ஓடும்.) (<a href=\"qurandisp.php?sura=10&ayah=9\" class=\"link\">10:9</a>) அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيُصْلِحُ</span> <span class=\"quran-arabic-font text-success\">بَالَهُمْ</span><br />\r\n<br />\r\n(மேலும் அவர்களின் நிலையைச் சீராக்குவான்.) அதாவது அவர்களின் சூழ்நிலைகளையும் விவகாரங்களையும் சீரமைப்பான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيُدْخِلُهُمُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةَ</span> <span class=\"quran-arabic-font text-success\">عَرَّفَهَا</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span><br />\r\n<br />\r\n(அவன் அவர்களுக்கு ஏற்கனவே அறிமுகப்படுத்திய சொர்க்கத்தில் அவர்களை நுழைய வைப்பான்.) அதாவது, சொர்க்கத்தை அவர்களுக்கு அடையாளம் காட்டி, அங்கு அவர்களை அழைத்துச் செல்வான். முஜாஹித் அவர்கள் கூறினார்கள்: \"சொர்க்கவாசிகள் அங்குள்ள தங்கள் வீடுகளுக்கும், தங்குமிடங்களுக்கும், அல்லாஹ் அவர்களுக்கு வழங்கியிருக்கும் பகுதிகளுக்கும் மிகச் சரியாக வழிகாட்டப்படுவார்கள். அவர்கள் அங்கு எவ்விதத் தவறும் செய்ய மாட்டார்கள், யாரிடமும் வழி கேட்கவும் மாட்டார்கள் -- தாங்கள் படைக்கப்பட்ட காலம் முதலே அங்கேயே வசிப்பவர்களைப் போல (தங்கள் இருப்பிடங்களை அறிந்திருப்பார்கள்).\" இமாம் புகாரி அவர்கள் அபூ ஸயீத் அல்-குத்ரி (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">خَلَصَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">حُبِسُوا</span> <span class=\"quran-arabic-font text-success\">بِقَنْطَرَةٍ</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">وَالنَّارِ،</span> <span class=\"quran-arabic-font text-success\">يَتَقَاصُّونَ</span> <span class=\"quran-arabic-font text-success\">مَظَالِمَ</span> <span class=\"quran-arabic-font text-success\">كَانَتْ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا،</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">إذَا</span> <span class=\"quran-arabic-font text-success\">هُذِّبُوا</span> <span class=\"quran-arabic-font text-success\">وَنُقُّوا</span> <span class=\"quran-arabic-font text-success\">أُذِنَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">دُخُولِ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ،</span> <span class=\"quran-arabic-font text-success\">وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">نَفْسِي</span> <span class=\"quran-arabic-font text-success\">بِيَدِهِ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">أَحَدَهُمْ</span> <span class=\"quran-arabic-font text-success\">بِمَنْزِلِهِ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">أَهْدَى</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">بِمَنْزِلِهِ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span>»<br />\r\n<br />\r\n((மறுமை நாளில்) நம்பிக்கையாளர்கள் நரகத்திலிருந்து தப்பியதும், சொர்க்கத்திற்கும் நரகத்திற்கும் இடையிலுள்ள ஒரு மேம்பாலத்தில் தடுத்து நிறுத்தப்படுவார்கள். அங்கு அவர்கள் இம்மையில் ஒருவருக்கொருவர் இழைத்த அநீதிகளுக்குப் பழிதீர்த்துக் கொள்வார்கள். அவர்கள் முற்றிலும் தூய்மைப்படுத்தப்பட்ட பிறகு, சொர்க்கத்தில் நுழைய அனுமதிக்கப்படுவார்கள். என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக! அவர்கள் ஒவ்வொருவரும் இவ்வுலகில் தங்களது இருப்பிடத்தை அறிந்திருந்ததை விடவும் மிகச் சிறந்த முறையில் சொர்க்கத்திலுள்ள தங்களது இருப்பிடத்தை அறிந்துகொள்வார்கள்.)<br />\r\n<br />\r\n<strong>அல்லாஹ்வின் மார்க்கத்திற்கு உதவுங்கள், அவன் உங்களுக்கு உதவுவான்</strong><br />\r\n<br />\r\nபின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">تَنصُرُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">يَنصُرْكُمْ</span> <span class=\"quran-arabic-font text-success\">وَيُثَبِّتْ</span> <span class=\"quran-arabic-font text-success\">أَقْدَامَكُمْ</span><br />\r\n<br />\r\n(நம்பிக்கையாளர்களே! நீங்கள் அல்லாஹ்வுக்கு (அவனது மார்க்கத்திற்கு) உதவி செய்தால், அவன் உங்களுக்கு உதவி செய்வான்; உங்கள் பாதங்களை உறுதியாக்குவான்.) இது அவனது பின்வரும் கூற்றைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَيَنصُرَنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَنصُرُهُ</span><br />\r\n<br />\r\n(நிச்சயமாக, தனக்கு (தனது மார்க்கத்திற்கு) உதவி செய்பவருக்கு அல்லாஹ்வும் உதவி செய்வான்.) (<a href=\"qurandisp.php?sura=22&ayah=40\" class=\"link\">22:40</a>) ஏனெனில், பிரதிபலன் என்பது செயலின் தன்மைக்கு ஏற்பவே அமையும். அதனால் தான் அல்லாஹ் இங்கு,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيُثَبِّتْ</span> <span class=\"quran-arabic-font text-success\">أَقْدَامَكُمْ</span><br />\r\n<br />\r\n(உங்கள் பாதங்களை உறுதியாக்குவான்.) என்று கூறுகிறான். பின்னர் அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">فَتَعْساً</span> <span class=\"quran-arabic-font text-success\">لَّهُمْ</span><br />\r\n<br />\r\n(ஆனால் நிராகரிப்பவர்களுக்கோ அழிவுதான்.) இந்த அழிவானது, அல்லாஹ்விற்கும் அவனது தூதருக்கும் உதவி செய்யும் நம்பிக்கையாளர்களின் பாதங்களை அல்லாஹ் உறுதியாக்குவதற்கு நேர்மாறானதாகும். நபி (ஸல்) அவர்கள் கூறியதாக ஒரு ஹதீஸில் உறுதிப்படுத்தப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">تَعِسَ</span> <span class=\"quran-arabic-font text-success\">عَبْدُالدِّينَارِ،</span> <span class=\"quran-arabic-font text-success\">تَعِسَ</span> <span class=\"quran-arabic-font text-success\">عَبْدُالدِّرْهَمِ،</span> <span class=\"quran-arabic-font text-success\">تَعِسَ</span> <span class=\"quran-arabic-font text-success\">عَبْدُالْقَطِيفَةِ،</span> <span class=\"quran-arabic-font text-success\">تَعِسَ</span> <span class=\"quran-arabic-font text-success\">وَانْتَكَسَ</span> <span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">شِيكَ</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">انْتَقَش</span>»<br />\r\n<br />\r\n(தீனாருக்கு அடிமையானவன் அழிந்துவிட்டான்; திர்ஹத்திற்கு அடிமையானவன் அழிந்துவிட்டான்; உயர்ந்த ஆடைகளுக்கு அடிமையானவன் அழிந்துவிட்டான். அவன் அழிந்தான், நிலைகுலைந்தான். அவனுக்கு ஒரு முள் குத்தினால் கூட, அதை எடுப்பவர் எவரும் அவனுக்குக் கிடைக்காமல் போகட்டும்.) அதாவது அல்லாஹ் அவனைக் குணப்படுத்தாமல் இருக்கட்டும் என்பது இதன் பொருள். பின்னர் அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَضَلَّ</span> <span class=\"quran-arabic-font text-success\">أَعْمَـلَهُمْ</span><br />\r\n<br />\r\n(மேலும் (அல்லாஹ்) அவர்களின் செயல்களை வீணாக்குவான்.) அதாவது அவற்றை அழித்து பயனற்றதாக்கி விடுவான். அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">بِأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">كَرِهُواْ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَنزَلَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span><br />\r\n<br />\r\n(ஏனெனில் அல்லாஹ் இறக்கியருளியதை அவர்கள் வெறுத்தார்கள்;) அதாவது அல்லாஹ் அருளிய வஹீயை (இறைச்செய்தியை) அவர்கள் விரும்பவில்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَحْبَطَ</span> <span class=\"quran-arabic-font text-success\">أَعْمَـلَهُمْ</span><br />\r\n<br />\r\n(எனவே அவன் அவர்களின் செயல்களைப் பயனற்றதாக்கினான்.)<br />\r\n<br />","text":"எதிரிகளின் கழுத்துகளை வெட்டுவதற்கும், அவர்களைக் கட்டி வைப்பதற்கும், பின்னர் கருணை காட்டியோ அல்லது ஈட்டுத்தொகை பெற்றுக்கொண்டோ அவர்களை விடுதலை செய்வதற்கும் உள்ள கட்டளை\n\r\n\n\r\nஇணைவைப்பவர்களுக்கு எதிரான போர்களில் நம்பிக்கையாளர்கள் எத்தகைய வழிமுறைகளைக் கையாள வேண்டும் என்று வழிகாட்டும் விதமாக அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَإِذَا لَقِيتُمُ الَّذِينَ كَفَرُواْ فَضَرْبَ الرِّقَابِ\n\r\n\n\r\n(ஆகவே, (போர்க்களத்தில்) நிராகரிப்பவர்களை நீங்கள் சந்திக்கும்போது, அவர்களின் கழுத்துகளை வெட்டுங்கள்.) அதாவது, நீங்கள் அவர்களுடன் போரிடும்போது, உங்கள் வாள்களால் அவர்களை முழுமையாக வெட்டி வீழ்த்துங்கள்.\n\r\n\n\r\nحَتَّى إِذَآ أَثْخَنتُمُوهُمْ\n\r\n\n\r\n(நீங்கள் அவர்களை முழுமையாகத் தோற்கடிக்கும் வரை,) அதாவது, நீங்கள் அவர்களைக் கொன்று, முற்றிலுமாக நிலைகுலையச் செய்யும் வரை.\n\r\n\n\r\nفَشُدُّواْ الْوَثَاقَ\n\r\n\n\r\n(அவர்களின் கட்டுகளை இறுக்குங்கள்.) فَإِمَّا مَنًّا بَعْدُ وَإِمَّا فِدَآءً (அதன் பின்னர், (அவர்கள் மீது) கருணை காட்டுங்கள்; அல்லது ஈட்டுத்தொகை பெற்றுக் கொள்ளுங்கள்.) இது நீங்கள் பிடித்துள்ள போர்க்கைதிகளைக் குறிக்கிறது. பின்னர், போர் முடிந்து மோதல்கள் நின்ற பிறகு, கைதிகள் விஷயத்தில் உங்களுக்கு இரு வாய்ப்புகள் உள்ளன: ஒன்று, அவர்கள் மீது கருணை காட்டி எவ்விதப் பிரதிபலனும் இன்றி விடுதலை செய்யலாம்; அல்லது அவர்களிடமிருந்து ஈட்டுத்தொகையைப் பெற்றுக்கொண்டு விடுதலை செய்யலாம். இந்த வசனம் பத்ருப் போருக்குப் பிறகு அருளப்பட்டதாகத் தெரிகிறது. அப்போது, எதிரிப் படையினரில் பலரை உயிருடன் விட்டதற்காகவும், ஈட்டுத்தொகை பெறும் நோக்கில் அதிக கைதிகளைப் பிடித்து வைத்திருந்ததற்காகவும் அல்லாஹ் நம்பிக்கையாளர்களைக் கண்டித்தான். அப்போது அவன் கூறினான்:\n\r\n\n\r\nمَا كَانَ لِنَبِىٍّ أَن يَكُونَ لَهُ أَسْرَى حَتَّى يُثْخِنَ فِي الْأَرْضِ تُرِيدُونَ عَرَضَ الدُّنْيَا وَاللَّهُ يُرِيدُ الْآخِرَةَ وَاللَّهُ عَزِيزٌ حَكِيمٌ - لَّوْلاَ كِتَـبٌ مِّنَ اللَّهِ سَبَقَ لَمَسَّكُمْ فِيمَآ أَخَذْتُمْ عَذَابٌ عَظِيمٌ\n\r\n\n\r\n(ஒரு நபி, பூமியில் (எதிரிகளை) முற்றிலும் வீழ்த்தும் வரை அவருக்குப் போர்க்கைதிகள் இருப்பது தகுதியல்ல. நீங்கள் இவ்வுலகின் ஆதாயங்களை விரும்புகிறீர்கள், ஆனால் அல்லாஹ்வோ (உங்களுக்கு) மறுமையை நாடுகிறான். அல்லாஹ் மிகைத்தவனும் ஞானமிக்கவனுமாவான். அல்லாஹ்விடமிருந்து முன்கூட்டியே எழுதப்பட்ட ஒரு விதி இல்லையெனில், நீங்கள் (கைதிகளுக்காக)ப் பெற்றுக்கொண்ட ஈட்டுத்தொகைக்காக உங்களைக் கடுமையான வேதனை தீண்டியிருக்கும்.) (8:67-68) அல்லாஹ்வின் கூற்று,\n\r\n\n\r\nحَتَّى تَضَعَ الْحَرْبُ أَوْزَارَهَا\n\r\n\n\r\n(...போர் அதன் சுமைகளை இறக்கி வைக்கும் வரை.) முஜாஹித் அவர்கள் கூறுகையில், \"ஈஸா இப்னு மர்யம் (அலை) அவர்கள் இறங்கும் வரை\" என்று குறிப்பிட்டார்கள். நபி (ஸல்) அவர்களின் பின்வரும் பொன்மொழியிலிருந்து அவர்கள் இந்தக் கருத்தைப் பெற்றிருக்கலாம் என்று தெரிகிறது:\n\r\n\n\r\n«لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي ظَاهِرِينَ عَلَى الْحَقِّ حَتَّى يُقَاتِلَ آخِرُهُمُ الدَّجَّال»\n\r\n\n\r\n(என் உம்மத்தில் ஒரு கூட்டத்தினர் சத்தியத்தின் மீது வெற்றி பெற்றவர்களாகத் தொடர்ந்து இருந்து கொண்டே இருப்பார்கள், அவர்களில் கடைசிப் பிரிவினர் தஜ்ஜாலுடன் போர் புரியும் வரை.) இமாம் அஹ்மத் அவர்கள், ஜுபைர் இப்னு நுஃபைர் வழியாக ஸலமா இப்னு நுஃபைல் (ரழி) அவர்களிடமிருந்து பின்வருமாறு பதிவு செய்துள்ளார்கள்: அவர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் வந்து, \"நான் என் குதிரையை அவிழ்த்து விட்டுவிட்டேன், என் ஆயுதத்தையும் கீழே போட்டுவிட்டேன். ஏனெனில் போர் முடிந்துவிட்டது, இனி சண்டை எதுவும் இல்லை\" என்று கூறினார். அப்போது நபி (ஸல்) அவர்கள் அவரிடம் கூறினார்கள்:\n\r\n\n\r\n«الْآنَ جَاءَ الْقِتَالُ، لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي ظَاهِرِينَ عَلَى النَّاسِ، يُزِيغُ اللهُ تَعَالَى قُلُوبَ أَقْوَام، فَيُقَاتِلُونَهُمْ وَيَرْزُقُهُمُ اللهُ مِنْهُمْ حَتَّى يَأْتِيَ أَمْرُ اللهِ وَهُمْ عَلَى ذَلِكَ، أَلَا إِنَّ عُقْرَ دَارِ الْمُؤْمِنِينَ الشَّامُ، وَالْخَيْلُ مَعْقُودٌ فِي نَوَاصِيهَا الْخَيْرُ إِلَى يَوْمِ الْقِيَامَة»\n\r\n\n\r\n(இப்போதுதான் போருக்கான நேரம் வந்துள்ளது. என் உம்மத்தில் ஒரு கூட்டத்தினர் மக்கள் மீது மேலோங்கியவர்களாகத் தொடர்ந்து இருந்து கொண்டே இருப்பார்கள். அல்லாஹ் சில சமூகத்தாரின் இதயங்களை (உண்மையிலிருந்து) திசை திருப்புவான்; எனவே இவர்கள் அவர்களுக்கு எதிராகப் போரிடுவார்கள். அல்லாஹ் அவர்களுக்கு அவர்களிடமிருந்து (எதிரிகளிடமிருந்து) போர்ச் செல்வங்களை வழங்குவான் -- அல்லாஹ்வின் கட்டளை வரும் வரை அவர்கள் இதே நிலையிலேயே இருப்பார்கள். அறிந்து கொள்க! நம்பிக்கையாளர்களின் வசிப்பிடத்தின் மையம் அஷ்-ஷாம் ஆகும். மேலும், மறுமை நாள் வரை குதிரைகளின் நெற்றிகளில் நன்மைகள் பிணைக்கப்பட்டுள்ளன.) அன்-நஸாயீயும் இந்த அறிவிப்பைப் பதிவு செய்துள்ளார். பின்னர் அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nذَلِكَ وَلَوْ يَشَآءُ اللَّهُ لاَنْتَصَرَ مِنْهُمْ\n\r\n\n\r\n(நிலைமை இதுதான். அல்லாஹ் நாடியிருந்தால், அவன் அவர்களிடமிருந்து (நேரடியாகப்) பழிவாங்கியிருப்பான்;) அதாவது, அல்லாஹ் நாடியிருந்தால், நிராகரிப்பாளர்களைத் தன்பக்கமிருந்து நேரடியாக ஒரு வேதனை அல்லது தண்டனையின் மூலம் உடனடியாக அழித்திருப்பான்.\n\r\n\n\r\nوَلَـكِن لِّيَبْلُوَ بَعْضَكُمْ بِبَعْضٍ\n\r\n\n\r\n(ஆனால், உங்களில் ஒருவரை மற்றவர் மூலம் சோதிப்பதற்காகவே (போரை விதித்தான்).) அதாவது, உங்களைச் சோதிப்பதற்கும் உங்கள் நிலையை அறியச் செய்வதற்காகவுமே ஜிஹாத் மற்றும் எதிரிகளுக்கு எதிரான போரை அவன் கடமையாக்கியுள்ளான். அல்லாஹ் ஜிஹாத்தை விதித்ததன் ஞானத்தை ஆல இம்ரான் மற்றும் அத்தவ்பா ஆகிய அத்தியாயங்களிலும் விளக்குகிறான்:\n\r\n\n\r\nأَمْ حَسِبْتُمْ أَن تَدْخُلُواْ الْجَنَّةَ وَلَمَّا يَعْلَمِ اللَّهُ الَّذِينَ جَـهَدُواْ مِنكُمْ وَيَعْلَمَ الصَّـبِرِينَ\n\r\n\n\r\n(அல்லது, உங்களில் போரிடுபவர்களையும், பொறுமையாளர்களையும் அல்லாஹ் அடையாளம் காட்டாத நிலையில், நீங்கள் சொர்க்கத்தில் நுழைந்து விடலாம் என்று எண்ணிக் கொண்டீர்களா?) (3:142)\n\r\n\n\r\nقَـتِلُوهُمْ يُعَذِّبْهُمُ اللَّهُ بِأَيْدِيكُمْ وَيُخْزِهِمْ وَيَنْصُرْكُمْ عَلَيْهِمْ وَيَشْفِ صُدُورَ قَوْمٍ مُّؤْمِنِينَ - وَيُذْهِبْ غَيْظَ قُلُوبِهِمْ وَيَتُوبُ اللَّهُ عَلَى مَن يَشَآءُ وَاللَّهُ عَلِيمٌ حَكِيمٌ\n\r\n\n\r\n(அவர்களுடன் போரிடுங்கள்; அல்லாஹ் உங்கள் கைகளைக் கொண்டு அவர்களைத் தண்டிப்பான், அவர்களை இழிவுபடுத்துவான், அவர்களுக்கு எதிராக உங்களுக்கு வெற்றி அளிப்பான், நம்பிக்கையுள்ள மக்களின் இதயங்களை ஆற்றுப்படுத்துவான். மேலும் அவர்களின் (நம்பிக்கையாளர்களின்) உள்ளங்களில் உள்ள ஆத்திரத்தைப் போக்குவான். அல்லாஹ் தான் நாடியவர்களின் மன்னிப்பை ஏற்றுக் கொள்கிறான். அல்லாஹ் அறிந்தவனும் ஞானமிக்கவனுமாவான்.) (9:14-15)\n\r\n\n\r\nதியாகிகளின் மேன்மை\n\r\n\n\r\nபோர்களின் போது பல நம்பிக்கையாளர்கள் உயிர் தியாகம் செய்வது வழக்கம் என்பதால், அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَالَّذِينَ قُتِلُواْ فِى سَبِيلِ اللَّهِ فَلَن يُضِلَّ أَعْمَـلَهُمْ\n\r\n\n\r\n(அல்லாஹ்வின் பாதையில் கொல்லப்பட்டவர்களின் செயல்களை அவன் ஒருபோதும் வீணாக்க மாட்டான்.) அதாவது, அவர்களின் நற்செயல்கள் அழிந்து போக அவன் விடமாட்டான்; மாறாக அவற்றை மென்மேலும் வளர்ப்பான். அவர்களில் சிலர் அல்-பர்ஸக் (திரைமறைவு வாழ்க்கை) காலத்தில் இருக்கும் வரை அவர்களின் நற்செயல்களுக்கான கூலி தொடர்ந்து வழங்கப்பட்டு வரும். இது குறித்து இமாம் அஹ்மத் அவர்கள் தனது முஸ்னதில் கதீர் இப்னு முர்ரா வழியாக கைஸ் அல்-ஜுதாமி (ரழி) அவர்கள் அறிவித்த ஹதீஸைப் பதிவு செய்துள்ளார்கள். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«يُعْطَى الشَّهِيدُ سِتَّ خِصَالٍ عِنْدَ أَوَّلِ قَطْرَةٍ مِنْ دَمِهِ: تُكَفَّرُ عَنْهُ كُلُّ خَطِيئَةٍ، وَيَرَى مَقْعَدَهُ مِنَ الْجَنَّةِ، وَيُزَوَّجُ مِنَ الْحُورِ الْعِين، وَيَأْمَنُ مِنَ الْفَزَعِ الْأَكْبَرِ، وَمِنْ عَذَابِ الْقَبْرِ، وَيُحَلَّى حُلَّةَ الْإِيمَان»\n\r\n\n\r\n(இரத்தத்தின் முதல் துளி வெளிப்படும் போதே, ஒரு ஷஹீதுக்கு ஆறு சிறப்புகள் வழங்கப்படுகின்றன: அவருடைய பாவங்கள் அனைத்தும் மன்னிக்கப்படுகின்றன; சொர்க்கத்தில் அவருக்குரிய இடம் அவருக்குக் காட்டப்படுகிறது; அகன்ற விழிகளையுடைய ஹூருல் ஈன்களுடன் அவருக்குத் திருமணம் செய்து வைக்கப்படுகிறது; (மறுமையின்) பெரும் திடுக்கத்திலிருந்தும் கப்ரின் வேதனையிலிருந்தும் அவருக்குப் பாதுகாப்பு அளிக்கப்படுகிறது; மேலும் அவருக்கு ஈமானின் ஆபரணங்கள் அணிவிக்கப்படுகின்றன.) அஹ்மத் இந்த ஹதீஸைத் தனியாகப் பதிவு செய்துள்ளார். அபுத்தர்தா (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«يُشَفَّعُ الشَّهِيدُ فِي سَبْعِينَ مِنْ أَهْلِ بَيْتِه»\n\r\n\n\r\n(ஒரு தியாகி தனது குடும்பத்தாரில் எழுபது பேருக்காகப் பரிந்துரை செய்ய அனுமதிக்கப்படுவார்.) இதனை அபூ தாவூத் பதிவு செய்துள்ளார். மேலும் தியாகிகளின் சிறப்புகளைக் கூறும் இன்னும் பல ஹதீஸ்கள் உள்ளன. அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:\n\r\n\n\r\nسَيَهْدِيهِمْ\n\r\n\n\r\n(அவன் அவர்களுக்கு நல்வழி காட்டுவான்.) அதாவது, அவர்களை ஜன்னாவிற்கு (சொர்க்கத்திற்கு) அழைத்துச் செல்வான். இது அல்லாஹ்வின் பின்வரும் கூற்றைப் போன்றது:\n\r\n\n\r\nإِنَّ الَّذِينَ ءَامَنُواْ وَعَمِلُواْ الصَّـلِحَاتِ يَهْدِيهِمْ رَبُّهُمْ بِإِيمَانِهِمْ تَجْرِى مِن تَحْتِهِمُ الاٌّنْهَـرُ فِي جَنَّـتِ النَّعِيمِ\n\r\n\n\r\n(நிச்சயமாக நம்பிக்கை கொண்டு நற்செயல்கள் புரிந்தவர்களுக்கு, அவர்களின் ஈமானின் காரணமாக அவர்களது இறைவன் நேர்வழி காட்டுவான்; இன்பம் நிறைந்த சொர்க்கச் சோலைகளில் அவர்களுக்குக் கீழ் ஆறுகள் ஓடும்.) (10:9) அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nوَيُصْلِحُ بَالَهُمْ\n\r\n\n\r\n(மேலும் அவர்களின் நிலையைச் சீராக்குவான்.) அதாவது அவர்களின் சூழ்நிலைகளையும் விவகாரங்களையும் சீரமைப்பான்.\n\r\n\n\r\nوَيُدْخِلُهُمُ الْجَنَّةَ عَرَّفَهَا لَهُمْ\n\r\n\n\r\n(அவன் அவர்களுக்கு ஏற்கனவே அறிமுகப்படுத்திய சொர்க்கத்தில் அவர்களை நுழைய வைப்பான்.) அதாவது, சொர்க்கத்தை அவர்களுக்கு அடையாளம் காட்டி, அங்கு அவர்களை அழைத்துச் செல்வான். முஜாஹித் அவர்கள் கூறினார்கள்: \"சொர்க்கவாசிகள் அங்குள்ள தங்கள் வீடுகளுக்கும், தங்குமிடங்களுக்கும், அல்லாஹ் அவர்களுக்கு வழங்கியிருக்கும் பகுதிகளுக்கும் மிகச் சரியாக வழிகாட்டப்படுவார்கள். அவர்கள் அங்கு எவ்விதத் தவறும் செய்ய மாட்டார்கள், யாரிடமும் வழி கேட்கவும் மாட்டார்கள் -- தாங்கள் படைக்கப்பட்ட காலம் முதலே அங்கேயே வசிப்பவர்களைப் போல (தங்கள் இருப்பிடங்களை அறிந்திருப்பார்கள்).\" இமாம் புகாரி அவர்கள் அபூ ஸயீத் அல்-குத்ரி (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِذَا خَلَصَ الْمُؤْمِنُونَ مِنَ النَّارِ حُبِسُوا بِقَنْطَرَةٍ بَيْنَ الْجَنَّةِ وَالنَّارِ، يَتَقَاصُّونَ مَظَالِمَ كَانَتْ بَيْنَهُمْ فِي الدُّنْيَا، حَتَّى إذَا هُذِّبُوا وَنُقُّوا أُذِنَ لَهُمْ فِي دُخُولِ الْجَنَّةِ، وَالَّذِي نَفْسِي بِيَدِهِ إِنَّ أَحَدَهُمْ بِمَنْزِلِهِ فِي الْجَنَّةِ أَهْدَى مِنْهُ بِمَنْزِلِهِ الَّذِي كَانَ فِي الدُّنْيَا»\n\r\n\n\r\n((மறுமை நாளில்) நம்பிக்கையாளர்கள் நரகத்திலிருந்து தப்பியதும், சொர்க்கத்திற்கும் நரகத்திற்கும் இடையிலுள்ள ஒரு மேம்பாலத்தில் தடுத்து நிறுத்தப்படுவார்கள். அங்கு அவர்கள் இம்மையில் ஒருவருக்கொருவர் இழைத்த அநீதிகளுக்குப் பழிதீர்த்துக் கொள்வார்கள். அவர்கள் முற்றிலும் தூய்மைப்படுத்தப்பட்ட பிறகு, சொர்க்கத்தில் நுழைய அனுமதிக்கப்படுவார்கள். என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக! அவர்கள் ஒவ்வொருவரும் இவ்வுலகில் தங்களது இருப்பிடத்தை அறிந்திருந்ததை விடவும் மிகச் சிறந்த முறையில் சொர்க்கத்திலுள்ள தங்களது இருப்பிடத்தை அறிந்துகொள்வார்கள்.)\n\r\n\n\r\nஅல்லாஹ்வின் மார்க்கத்திற்கு உதவுங்கள், அவன் உங்களுக்கு உதவுவான்\n\r\n\n\r\nபின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nيأَيُّهَا الَّذِينَ ءَامَنُواْ إِن تَنصُرُواْ اللَّهَ يَنصُرْكُمْ وَيُثَبِّتْ أَقْدَامَكُمْ\n\r\n\n\r\n(நம்பிக்கையாளர்களே! நீங்கள் அல்லாஹ்வுக்கு (அவனது மார்க்கத்திற்கு) உதவி செய்தால், அவன் உங்களுக்கு உதவி செய்வான்; உங்கள் பாதங்களை உறுதியாக்குவான்.) இது அவனது பின்வரும் கூற்றைப் போன்றது:\n\r\n\n\r\nوَلَيَنصُرَنَّ اللَّهُ مَن يَنصُرُهُ\n\r\n\n\r\n(நிச்சயமாக, தனக்கு (தனது மார்க்கத்திற்கு) உதவி செய்பவருக்கு அல்லாஹ்வும் உதவி செய்வான்.) (22:40) ஏனெனில், பிரதிபலன் என்பது செயலின் தன்மைக்கு ஏற்பவே அமையும். அதனால் தான் அல்லாஹ் இங்கு,\n\r\n\n\r\nوَيُثَبِّتْ أَقْدَامَكُمْ\n\r\n\n\r\n(உங்கள் பாதங்களை உறுதியாக்குவான்.) என்று கூறுகிறான். பின்னர் அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nوَالَّذِينَ كَفَرُواْ فَتَعْساً لَّهُمْ\n\r\n\n\r\n(ஆனால் நிராகரிப்பவர்களுக்கோ அழிவுதான்.) இந்த அழிவானது, அல்லாஹ்விற்கும் அவனது தூதருக்கும் உதவி செய்யும் நம்பிக்கையாளர்களின் பாதங்களை அல்லாஹ் உறுதியாக்குவதற்கு நேர்மாறானதாகும். நபி (ஸல்) அவர்கள் கூறியதாக ஒரு ஹதீஸில் உறுதிப்படுத்தப்பட்டுள்ளது:\n\r\n\n\r\n«تَعِسَ عَبْدُالدِّينَارِ، تَعِسَ عَبْدُالدِّرْهَمِ، تَعِسَ عَبْدُالْقَطِيفَةِ، تَعِسَ وَانْتَكَسَ وَإِذَا شِيكَ فَلَا انْتَقَش»\n\r\n\n\r\n(தீனாருக்கு அடிமையானவன் அழிந்துவிட்டான்; திர்ஹத்திற்கு அடிமையானவன் அழிந்துவிட்டான்; உயர்ந்த ஆடைகளுக்கு அடிமையானவன் அழிந்துவிட்டான். அவன் அழிந்தான், நிலைகுலைந்தான். அவனுக்கு ஒரு முள் குத்தினால் கூட, அதை எடுப்பவர் எவரும் அவனுக்குக் கிடைக்காமல் போகட்டும்.) அதாவது அல்லாஹ் அவனைக் குணப்படுத்தாமல் இருக்கட்டும் என்பது இதன் பொருள். பின்னர் அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nوَأَضَلَّ أَعْمَـلَهُمْ\n\r\n\n\r\n(மேலும் (அல்லாஹ்) அவர்களின் செயல்களை வீணாக்குவான்.) அதாவது அவற்றை அழித்து பயனற்றதாக்கி விடுவான். அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nذَلِكَ بِأَنَّهُمْ كَرِهُواْ مَآ أَنزَلَ اللَّهُ\n\r\n\n\r\n(ஏனெனில் அல்லாஹ் இறக்கியருளியதை அவர்கள் வெறுத்தார்கள்;) அதாவது அல்லாஹ் அருளிய வஹீயை (இறைச்செய்தியை) அவர்கள் விரும்பவில்லை.\n\r\n\n\r\nفَأَحْبَطَ أَعْمَـلَهُمْ\n\r\n\n\r\n(எனவே அவன் அவர்களின் செயல்களைப் பயனற்றதாக்கினான்.)"},"10":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=13\" class=\"link\">47:13</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:13 ஐ பார்க்கவும்"},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=13\" class=\"link\">47:13</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:13 ஐ பார்க்கவும்"},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=13\" class=\"link\">47:13</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:13 ஐ பார்க்கவும்"},"13":{"html":"<strong>நிராகரிப்பாளர்களுக்கு எச்சரிக்கையும் நரகமும்; தக்வா உடையவர்களுக்குச் சொர்க்கமும்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَسِيرُواْ</span><br />\r\n<br />\r\n(அவர்கள் பயணம் செய்யவில்லையா?) அதாவது, அல்லாஹ்வுக்கு இணை கற்பிப்பவர்களும் அவனது தூதரை மறுப்பவர்களும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">فَيَنظُرُواْ</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَاقِبَةُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِمْ</span> <span class=\"quran-arabic-font text-success\">دَمَّرَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span><br />\r\n<br />\r\n(பூமியில் அவர்கள் பயணம் செய்து, தங்களுக்கு முன்னிருந்தவர்களின் முடிவு என்னவானது என்பதை அவர்கள் பார்க்கவில்லையா? அல்லாஹ் அவர்களை அடியோடு அழித்துவிட்டான்.) அதாவது, அவர்களது மறுப்பு மற்றும் நிராகரிப்பின் காரணமாக அல்லாஹ் அவர்களைத் தண்டித்தான்; மேலும் அவர்களில் ஈமான் கொண்டவர்களைக் காப்பாற்றினான். இதனால்தான் அவன் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلِلْكَافِرِينَ</span> <span class=\"quran-arabic-font text-success\">أَمْثَالُهَا</span><br />\r\n<br />\r\n(இத்தகைய முடிவே இந்த நிராகரிப்பாளர்களுக்கும் காத்திருக்கிறது.) பிறகு அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">بِأَنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">مَوْلَى</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">وَأَنَّ</span> <span class=\"quran-arabic-font text-success\">الْكَافِرِينَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">مَوْلَى</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span><br />\r\n<br />\r\n(ஏனெனில், ஈமான் கொண்டவர்களுக்கு நிச்சயமாக அல்லாஹ்வே பாதுகாவலன்; ஆனால் நிராகரிப்பாளர்களுக்கோ பாதுகாவலர் எவருமில்லை.) உஹதுப் போருக்குப் பிறகு, அந்த நேரத்தில் இணைவைப்பாளர்களின் தளபதியாக இருந்த அபூ சுஃப்யான் சக்ர் பின் ஹர்ப், நபி (ஸல்) அவர்களையும், அபூபக்கர் (ரழி) அவர்களையும், உமர் (ரழி) அவர்களையும் பற்றி வினவினார். அவற்றுக்குப் பதில் கிடைக்காதபோது, \"நிச்சயமாக அந்த மூவரும் இறந்துவிட்டனர்!\" என்று அவர் அறிவித்தார். அப்போது உமர் (ரழி) அவர்கள் அவருக்குப் பதிலளித்தார்கள்: \"அல்லாஹ்வின் எதிரியே! நீ பொய் சொல்கிறாய். உனக்கு அதிருப்தியை ஏற்படுத்துபவர்களை நிச்சயமாக அல்லாஹ் உயிரோடு வைத்துள்ளான். நீ குறிப்பிட்ட அவர்கள் அனைவரும் உயிருடனேயே உள்ளனர்!\" பின்னர் அபூ சுஃப்யான் கூறினார்: \"சரி, இன்றைய நாள் பத்ரு நாளின் (தோல்விக்கு) ஈடாகிவிட்டது. போரில் வெற்றிகளும் தோல்விகளும் மாறி மாறி வரக்கூடியது. உங்கள் மரணித்தவர்களின் உடல்களில் அங்கச் சிதைவுகளை நீங்கள் காண்பீர்கள்; அதற்கு நான் கட்டளையிடவும் இல்லை, அதை நான் தடுக்கவும் இல்லை.\" பிறகு அவர், \"ஹுபல் (அவர்களது பெரிய சிலை) மேலோங்கட்டும், ஹுபல் மேலோங்கட்டும்\" என்று முழக்கமிட்டுக்கொண்டு திரும்பினார். அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَلَا</span> <span class=\"quran-arabic-font text-success\">تُجِيبُوهُ؟</span>»<br />\r\n<br />\r\n(அவருக்கு நீங்கள் பதிலளிக்க மாட்டீர்களா?) என்று கேட்டார்கள். ஸஹாபாக்கள் (ரழி) \"அல்லாஹ்வின் தூதரே! நாங்கள் என்ன கூற வேண்டும்?\" என்று கேட்டனர். அதற்கு அவர்கள்,<br />\r\n<br />\r\n« <span class=\"quran-arabic-font text-success\">قُولُوا</span>: <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">أَعْلَى</span> <span class=\"quran-arabic-font text-success\">وَأَجَل</span>»<br />\r\n<br />\r\n(\"அல்லாஹ்வே மிகவும் உயர்ந்தவன், மகத்துவமானவன் என்று கூறுங்கள்\") என்று கூறினார்கள். பிறகு அபூ சுஃப்யான், \"எங்களுக்கு 'அல்-உஸ்ஸா' (அவர்களது இரண்டாவது சிலை) உண்டு; உங்களுக்கு 'உஸ்ஸா' (கண்ணியம்) இல்லை\" என்று கூறினான். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَلَا</span> <span class=\"quran-arabic-font text-success\">تُجِيبُوهُ؟</span>»<br />\r\n<br />\r\n(நீங்கள் அனைவரும் அவருக்குப் பதிலளிக்க மாட்டீர்களா?) என்று கேட்டார்கள். அதற்கு அவர்கள், \"அல்லாஹ்வின் தூதரே! நாங்கள் என்ன கூற வேண்டும்?\" என்று கேட்டனர். அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">قُولُوا</span>: <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">مَوْلَانَا</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">مَوْلَى</span> <span class=\"quran-arabic-font text-success\">لَكُم</span>»<br />\r\n<br />\r\n(\"அல்லாஹ்வே எங்கள் பாதுகாவலன்; உங்களுக்குப் பாதுகாவலர் எவருமில்லை என்று கூறுங்கள்.\") பிறகு அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">يُدْخِلُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">وَعَمِلُواْ</span> <span class=\"quran-arabic-font text-success\">الصَّالِحَاتِ</span> <span class=\"quran-arabic-font text-success\">جَنَّاتٍ</span> <span class=\"quran-arabic-font text-success\">تَجْرِي</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">تَحْتِهَا</span> <span class=\"quran-arabic-font text-success\">الْأَنْهَارُ</span><br />\r\n<br />\r\n(நிச்சயமாக, ஈமான் கொண்டு நற்செயல்கள் செய்தவர்களை அல்லாஹ், ஆறுகள் ஓடிக்கொண்டிருக்கும் சுவனச் சோலைகளில் புகுத்துவான்.) அதாவது, மறுமை நாளில்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">يَتَمَتَّعُونَ</span> <span class=\"quran-arabic-font text-success\">وَيَأْكُلُونَ</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">تَأْكُلُ</span> <span class=\"quran-arabic-font text-success\">الْأَنْعَامُ</span><br />\r\n<br />\r\n(நிராகரிப்பவர்களோ சுகங்களை அனுபவிக்கின்றனர்; கால்நடைகள் உண்பது போன்று அவர்கள் உண்கின்றனர்.) இதன் பொருள், நிராகரிப்பாளர்கள் தங்களது உலக வாழ்க்கையை அனுபவிக்கிறார்கள்; மேலும் விலங்குகளைப் போன்று (பேராசையுடன்) வயிறு வளர்க்கிறார்கள். அதைத் தவிர அவர்களுக்கு வேறு எந்தக் கவலையும் இல்லை. எனவேதான், ஸஹீஹான ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியுள்ளது உறுதிப்படுத்தப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الْمُؤْمِنُ</span> <span class=\"quran-arabic-font text-success\">يَأْكُلُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">مِعىً</span> <span class=\"quran-arabic-font text-success\">وَاحِدٍ،</span> <span class=\"quran-arabic-font text-success\">وَالْكَافِرُ</span> <span class=\"quran-arabic-font text-success\">يَأْكُلُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">سَبْعَةِ</span> <span class=\"quran-arabic-font text-success\">أَمْعَاء</span>»<br />\r\n<br />\r\n(ஒரு முஃமின் ஒரு குடலில் உண்கிறார்; ஆனால் ஒரு காஃபிர் ஏழு குடல்களில் உண்கிறார்.) பிறகு அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالنَّارُ</span> <span class=\"quran-arabic-font text-success\">مَثْوًى</span> <span class=\"quran-arabic-font text-success\">لَّهُمْ</span><br />\r\n<br />\r\n(நரகமே அவர்களது தங்குமிடமாகும்.) அதாவது, அவர்களது விசாரணை நாளில். பிறகு அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَأَيِّن</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَرْيَةٍ</span> <span class=\"quran-arabic-font text-success\">هِيَ</span> <span class=\"quran-arabic-font text-success\">أَشَدُّ</span> <span class=\"quran-arabic-font text-success\">قُوَّةً</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَرْيَتِكَ</span> <span class=\"quran-arabic-font text-success\">الَّتِي</span> <span class=\"quran-arabic-font text-success\">أَخْرَجَتْكَ</span><br />\r\n<br />\r\n(உங்களை வெளியேற்றிய உங்களது ஊரைவிட வலிமைமிக்க எத்தனையோ ஊர்களை) அதாவது, மக்காவை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَهْلَكْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">نَاصِرَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span><br />\r\n<br />\r\n(நாம் அழித்திருக்கிறோம்; அவர்களுக்கு உதவி செய்வார் எவருமில்லை!) இது மக்கா மக்களுக்கு விடுக்கப்பட்ட பெரும் அச்சுறுத்தலும் கடுமையான எச்சரிக்கையுமாகும். ஏனெனில் அவர்கள், தூதர்களின் தலைவரும் நபிமார்களின் இறுதியானவருமான அல்லாஹ்வின் தூதர் (ஸல்) அவர்களை நிராகரித்தார்கள். முந்தைய சமுதாயங்கள் தங்களது தூதர்களைப் பொய்ப்பித்த காரணத்தினால் அல்லாஹ் அவர்களை அழித்திருக்கிறான் என்றால், இந்த (மக்கா) மக்கள் இவ்வுலகிலும் மறுமையிலும் அல்லாஹ் தங்களுக்கு என்ன செய்வான் என்று எதிர்பார்க்கிறார்கள்? கருணையின் நபியான தூதர் அவர்களிடையே இருக்கும் சிறப்பினால் அவர்களில் சிலருக்கு இவ்வுலகில் வேதனை நீக்கப்பட்டிருந்தாலும், அந்த வேதனை அவர்களுக்காக மறுமையில் சேமித்து வைக்கப்படும். அல்லாஹ் கூறுவது போல,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يُضَاعَفُ</span> <span class=\"quran-arabic-font text-success\">لَهُمُ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَسْتَطِيعُونَ</span> <span class=\"quran-arabic-font text-success\">السَّمْعَ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يُبْصِرُونَ</span><br />\r\n<br />\r\n(அவர்களுக்கு வேதனை இரட்டிப்பாக்கப்படும்! அவர்களால் (சத்தியத்தைச்) செவியேற்க இயலவில்லை; அவர்கள் (உண்மையைப்) பார்ப்பவர்களாகவும் இருக்கவில்லை.) (<a href=\"qurandisp.php?sura=11&ayah=20\" class=\"link\">11:20</a>) அல்லாஹ்வின் கூற்றான,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَرْيَتِكَ</span> <span class=\"quran-arabic-font text-success\">الَّتِي</span> <span class=\"quran-arabic-font text-success\">أَخْرَجَتْكَ</span><br />\r\n<br />\r\n(உங்களை வெளியேற்றிய உங்களது ஊரை விட) இதன் பொருள், 'உங்களை (முஹம்மது (ஸல்) அவர்களை) தங்களுக்கு இடையிலிருந்து வெளியேற்றிய அந்த ஊர் மக்கள்' என்பதாகும். இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவித்ததாக இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மக்காவை விட்டு (ஹிஜ்ரத் - புலம்பெயர்ந்த போது) புறப்பட்டு, குகையை அடைந்து அதனுள் மறைந்திருந்தபோது, அவர்கள் மக்காவைத் திரும்பிப் பார்த்து இவ்வாறு கூறினார்கள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَنْتِ</span> <span class=\"quran-arabic-font text-success\">أَحَبُّ</span> <span class=\"quran-arabic-font text-success\">بِلَادِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللهِ،</span> <span class=\"quran-arabic-font text-success\">وَأَنْتِ</span> <span class=\"quran-arabic-font text-success\">أَحَبُّ</span> <span class=\"quran-arabic-font text-success\">بِلَادِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">إِلَيَّ،</span> <span class=\"quran-arabic-font text-success\">وَلَوْلَا</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">الْمُشْرِكِينَ</span> <span class=\"quran-arabic-font text-success\">أَخْرَجُونِي</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">أَخْرُجْ</span> <span class=\"quran-arabic-font text-success\">مِنْك</span>»<br />\r\n<br />\r\n(அல்லாஹ்வின் பூமிகளிலேயே அல்லாஹ்வுக்கு மிகவும் பிரியமான ஊர் நீதான். அல்லாஹ்வின் பூமிகளிலேயே எனக்கு மிகவும் பிரியமான ஊரும் நீயே. இணைவைப்பாளர்கள் உன்னிலிருந்து என்னை வெளியேற்றாமல் இருந்திருந்தால், நான் உன்னை விட்டுப் புறப்பட்டிருக்க மாட்டேன்.)<br />\r\n<br />\r\nபிறகு இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"மனிதர்களிலேயே அல்லாஹ்வுக்கு மிகவும் வெறுப்புக்குரியவர்கள் மூவர் ஆவர்; அவர்கள் யாரெனில்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَبْغَضُ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">ثَلَاثَةٌ</span>: <span class=\"quran-arabic-font text-success\">مُلْحِدٌ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْحَرَمِ،</span> <span class=\"quran-arabic-font text-success\">وَمُبْتَغٍ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْإِسْلَامِ</span> <span class=\"quran-arabic-font text-success\">سُنَّةَ</span> <span class=\"quran-arabic-font text-success\">الْجَاهِلِيَّةِ،</span> <span class=\"quran-arabic-font text-success\">وَمُطَّلِبُ</span> <span class=\"quran-arabic-font text-success\">دَمِ</span> <span class=\"quran-arabic-font text-success\">امْرِئٍ</span> <span class=\"quran-arabic-font text-success\">بِغَيْرِ</span> <span class=\"quran-arabic-font text-success\">حَقٍّ</span> <span class=\"quran-arabic-font text-success\">لِيُهْرِيقَ</span> <span class=\"quran-arabic-font text-success\">دَمَه</span>»<br />\r\n<br />\r\n\"அல்லாஹ்வின் புனிதமான எல்லையில் அவனுக்கு எதிராக வரம்பு மீறுபவர், தன்னைக் கொல்ல முற்படாத ஒருவரைக் கொல்பவர் அல்லது அறியாமைக் காலத்துப் (ஜாஹிலிய்யா) பழிவாங்கலுக்காகக் கொல்பவர் ஆவார்.\" பிறகு அல்லாஹ் தனது நபிக்கு வஹீ (இறைச்செய்தி) அருளினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَأَيِّن</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَرْيَةٍ</span> <span class=\"quran-arabic-font text-success\">هِيَ</span> <span class=\"quran-arabic-font text-success\">أَشَدُّ</span> <span class=\"quran-arabic-font text-success\">قُوَّةً</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَرْيَتِكَ</span> <span class=\"quran-arabic-font text-success\">الَّتِي</span> <span class=\"quran-arabic-font text-success\">أَخْرَجَتْكَ</span> <span class=\"quran-arabic-font text-success\">أَهْلَكْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">نَاصِرَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span><br />\r\n<br />\r\n(உங்களை வெளியேற்றிய உங்களது ஊரைவிட வலிமைமிக்க எத்தனையோ ஊர்களை நாம் அழித்திருக்கிறோம்; அவர்களுக்கு உதவி செய்வார் எவருமில்லை!)\"<br />\r\n<br />","text":"நிராகரிப்பாளர்களுக்கு எச்சரிக்கையும் நரகமும்; தக்வா உடையவர்களுக்குச் சொர்க்கமும்\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nأَفَلَمْ يَسِيرُواْ\n\r\n\n\r\n(அவர்கள் பயணம் செய்யவில்லையா?) அதாவது, அல்லாஹ்வுக்கு இணை கற்பிப்பவர்களும் அவனது தூதரை மறுப்பவர்களும்.\n\r\n\n\r\nفِي الْأَرْضِ فَيَنظُرُواْ كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِن قَبْلِهِمْ دَمَّرَ اللَّهُ عَلَيْهِمْ\n\r\n\n\r\n(பூமியில் அவர்கள் பயணம் செய்து, தங்களுக்கு முன்னிருந்தவர்களின் முடிவு என்னவானது என்பதை அவர்கள் பார்க்கவில்லையா? அல்லாஹ் அவர்களை அடியோடு அழித்துவிட்டான்.) அதாவது, அவர்களது மறுப்பு மற்றும் நிராகரிப்பின் காரணமாக அல்லாஹ் அவர்களைத் தண்டித்தான்; மேலும் அவர்களில் ஈமான் கொண்டவர்களைக் காப்பாற்றினான். இதனால்தான் அவன் கூறுகிறான்,\n\r\n\n\r\nوَلِلْكَافِرِينَ أَمْثَالُهَا\n\r\n\n\r\n(இத்தகைய முடிவே இந்த நிராகரிப்பாளர்களுக்கும் காத்திருக்கிறது.) பிறகு அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nذَلِكَ بِأَنَّ اللَّهَ مَوْلَى الَّذِينَ ءَامَنُواْ وَأَنَّ الْكَافِرِينَ لاَ مَوْلَى لَهُمْ\n\r\n\n\r\n(ஏனெனில், ஈமான் கொண்டவர்களுக்கு நிச்சயமாக அல்லாஹ்வே பாதுகாவலன்; ஆனால் நிராகரிப்பாளர்களுக்கோ பாதுகாவலர் எவருமில்லை.) உஹதுப் போருக்குப் பிறகு, அந்த நேரத்தில் இணைவைப்பாளர்களின் தளபதியாக இருந்த அபூ சுஃப்யான் சக்ர் பின் ஹர்ப், நபி (ஸல்) அவர்களையும், அபூபக்கர் (ரழி) அவர்களையும், உமர் (ரழி) அவர்களையும் பற்றி வினவினார். அவற்றுக்குப் பதில் கிடைக்காதபோது, \"நிச்சயமாக அந்த மூவரும் இறந்துவிட்டனர்!\" என்று அவர் அறிவித்தார். அப்போது உமர் (ரழி) அவர்கள் அவருக்குப் பதிலளித்தார்கள்: \"அல்லாஹ்வின் எதிரியே! நீ பொய் சொல்கிறாய். உனக்கு அதிருப்தியை ஏற்படுத்துபவர்களை நிச்சயமாக அல்லாஹ் உயிரோடு வைத்துள்ளான். நீ குறிப்பிட்ட அவர்கள் அனைவரும் உயிருடனேயே உள்ளனர்!\" பின்னர் அபூ சுஃப்யான் கூறினார்: \"சரி, இன்றைய நாள் பத்ரு நாளின் (தோல்விக்கு) ஈடாகிவிட்டது. போரில் வெற்றிகளும் தோல்விகளும் மாறி மாறி வரக்கூடியது. உங்கள் மரணித்தவர்களின் உடல்களில் அங்கச் சிதைவுகளை நீங்கள் காண்பீர்கள்; அதற்கு நான் கட்டளையிடவும் இல்லை, அதை நான் தடுக்கவும் இல்லை.\" பிறகு அவர், \"ஹுபல் (அவர்களது பெரிய சிலை) மேலோங்கட்டும், ஹுபல் மேலோங்கட்டும்\" என்று முழக்கமிட்டுக்கொண்டு திரும்பினார். அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்,\n\r\n\n\r\n«أَلَا تُجِيبُوهُ؟»\n\r\n\n\r\n(அவருக்கு நீங்கள் பதிலளிக்க மாட்டீர்களா?) என்று கேட்டார்கள். ஸஹாபாக்கள் (ரழி) \"அல்லாஹ்வின் தூதரே! நாங்கள் என்ன கூற வேண்டும்?\" என்று கேட்டனர். அதற்கு அவர்கள்,\n\r\n\n\r\n« قُولُوا: اللهُ أَعْلَى وَأَجَل»\n\r\n\n\r\n(\"அல்லாஹ்வே மிகவும் உயர்ந்தவன், மகத்துவமானவன் என்று கூறுங்கள்\") என்று கூறினார்கள். பிறகு அபூ சுஃப்யான், \"எங்களுக்கு 'அல்-உஸ்ஸா' (அவர்களது இரண்டாவது சிலை) உண்டு; உங்களுக்கு 'உஸ்ஸா' (கண்ணியம்) இல்லை\" என்று கூறினான். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்,\n\r\n\n\r\n«أَلَا تُجِيبُوهُ؟»\n\r\n\n\r\n(நீங்கள் அனைவரும் அவருக்குப் பதிலளிக்க மாட்டீர்களா?) என்று கேட்டார்கள். அதற்கு அவர்கள், \"அல்லாஹ்வின் தூதரே! நாங்கள் என்ன கூற வேண்டும்?\" என்று கேட்டனர். அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«قُولُوا: اللهُ مَوْلَانَا وَلَا مَوْلَى لَكُم»\n\r\n\n\r\n(\"அல்லாஹ்வே எங்கள் பாதுகாவலன்; உங்களுக்குப் பாதுகாவலர் எவருமில்லை என்று கூறுங்கள்.\") பிறகு அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nإِنَّ اللَّهَ يُدْخِلُ الَّذِينَ ءَامَنُواْ وَعَمِلُواْ الصَّالِحَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ\n\r\n\n\r\n(நிச்சயமாக, ஈமான் கொண்டு நற்செயல்கள் செய்தவர்களை அல்லாஹ், ஆறுகள் ஓடிக்கொண்டிருக்கும் சுவனச் சோலைகளில் புகுத்துவான்.) அதாவது, மறுமை நாளில்.\n\r\n\n\r\nوَالَّذِينَ كَفَرُواْ يَتَمَتَّعُونَ وَيَأْكُلُونَ كَمَا تَأْكُلُ الْأَنْعَامُ\n\r\n\n\r\n(நிராகரிப்பவர்களோ சுகங்களை அனுபவிக்கின்றனர்; கால்நடைகள் உண்பது போன்று அவர்கள் உண்கின்றனர்.) இதன் பொருள், நிராகரிப்பாளர்கள் தங்களது உலக வாழ்க்கையை அனுபவிக்கிறார்கள்; மேலும் விலங்குகளைப் போன்று (பேராசையுடன்) வயிறு வளர்க்கிறார்கள். அதைத் தவிர அவர்களுக்கு வேறு எந்தக் கவலையும் இல்லை. எனவேதான், ஸஹீஹான ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியுள்ளது உறுதிப்படுத்தப்பட்டுள்ளது:\n\r\n\n\r\n«الْمُؤْمِنُ يَأْكُلُ فِي مِعىً وَاحِدٍ، وَالْكَافِرُ يَأْكُلُ فِي سَبْعَةِ أَمْعَاء»\n\r\n\n\r\n(ஒரு முஃமின் ஒரு குடலில் உண்கிறார்; ஆனால் ஒரு காஃபிர் ஏழு குடல்களில் உண்கிறார்.) பிறகு அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nوَالنَّارُ مَثْوًى لَّهُمْ\n\r\n\n\r\n(நரகமே அவர்களது தங்குமிடமாகும்.) அதாவது, அவர்களது விசாரணை நாளில். பிறகு அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nوَكَأَيِّن مِّن قَرْيَةٍ هِيَ أَشَدُّ قُوَّةً مِّن قَرْيَتِكَ الَّتِي أَخْرَجَتْكَ\n\r\n\n\r\n(உங்களை வெளியேற்றிய உங்களது ஊரைவிட வலிமைமிக்க எத்தனையோ ஊர்களை) அதாவது, மக்காவை.\n\r\n\n\r\nأَهْلَكْنَاهُمْ فَلَا نَاصِرَ لَهُمْ\n\r\n\n\r\n(நாம் அழித்திருக்கிறோம்; அவர்களுக்கு உதவி செய்வார் எவருமில்லை!) இது மக்கா மக்களுக்கு விடுக்கப்பட்ட பெரும் அச்சுறுத்தலும் கடுமையான எச்சரிக்கையுமாகும். ஏனெனில் அவர்கள், தூதர்களின் தலைவரும் நபிமார்களின் இறுதியானவருமான அல்லாஹ்வின் தூதர் (ஸல்) அவர்களை நிராகரித்தார்கள். முந்தைய சமுதாயங்கள் தங்களது தூதர்களைப் பொய்ப்பித்த காரணத்தினால் அல்லாஹ் அவர்களை அழித்திருக்கிறான் என்றால், இந்த (மக்கா) மக்கள் இவ்வுலகிலும் மறுமையிலும் அல்லாஹ் தங்களுக்கு என்ன செய்வான் என்று எதிர்பார்க்கிறார்கள்? கருணையின் நபியான தூதர் அவர்களிடையே இருக்கும் சிறப்பினால் அவர்களில் சிலருக்கு இவ்வுலகில் வேதனை நீக்கப்பட்டிருந்தாலும், அந்த வேதனை அவர்களுக்காக மறுமையில் சேமித்து வைக்கப்படும். அல்லாஹ் கூறுவது போல,\n\r\n\n\r\nيُضَاعَفُ لَهُمُ الْعَذَابُ مَا كَانُواْ يَسْتَطِيعُونَ السَّمْعَ وَمَا كَانُواْ يُبْصِرُونَ\n\r\n\n\r\n(அவர்களுக்கு வேதனை இரட்டிப்பாக்கப்படும்! அவர்களால் (சத்தியத்தைச்) செவியேற்க இயலவில்லை; அவர்கள் (உண்மையைப்) பார்ப்பவர்களாகவும் இருக்கவில்லை.) (11:20) அல்லாஹ்வின் கூற்றான,\n\r\n\n\r\nمِّن قَرْيَتِكَ الَّتِي أَخْرَجَتْكَ\n\r\n\n\r\n(உங்களை வெளியேற்றிய உங்களது ஊரை விட) இதன் பொருள், 'உங்களை (முஹம்மது (ஸல்) அவர்களை) தங்களுக்கு இடையிலிருந்து வெளியேற்றிய அந்த ஊர் மக்கள்' என்பதாகும். இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவித்ததாக இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மக்காவை விட்டு (ஹிஜ்ரத் - புலம்பெயர்ந்த போது) புறப்பட்டு, குகையை அடைந்து அதனுள் மறைந்திருந்தபோது, அவர்கள் மக்காவைத் திரும்பிப் பார்த்து இவ்வாறு கூறினார்கள்,\n\r\n\n\r\n«أَنْتِ أَحَبُّ بِلَادِ اللهِ إِلَى اللهِ، وَأَنْتِ أَحَبُّ بِلَادِ اللهِ إِلَيَّ، وَلَوْلَا أَنَّ الْمُشْرِكِينَ أَخْرَجُونِي لَمْ أَخْرُجْ مِنْك»\n\r\n\n\r\n(அல்லாஹ்வின் பூமிகளிலேயே அல்லாஹ்வுக்கு மிகவும் பிரியமான ஊர் நீதான். அல்லாஹ்வின் பூமிகளிலேயே எனக்கு மிகவும் பிரியமான ஊரும் நீயே. இணைவைப்பாளர்கள் உன்னிலிருந்து என்னை வெளியேற்றாமல் இருந்திருந்தால், நான் உன்னை விட்டுப் புறப்பட்டிருக்க மாட்டேன்.)\n\r\n\n\r\nபிறகு இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"மனிதர்களிலேயே அல்லாஹ்வுக்கு மிகவும் வெறுப்புக்குரியவர்கள் மூவர் ஆவர்; அவர்கள் யாரெனில்:\n\r\n\n\r\n«أَبْغَضُ النَّاسِ إِلَى اللهِ ثَلَاثَةٌ: مُلْحِدٌ فِي الْحَرَمِ، وَمُبْتَغٍ فِي الْإِسْلَامِ سُنَّةَ الْجَاهِلِيَّةِ، وَمُطَّلِبُ دَمِ امْرِئٍ بِغَيْرِ حَقٍّ لِيُهْرِيقَ دَمَه»\n\r\n\n\r\n\"அல்லாஹ்வின் புனிதமான எல்லையில் அவனுக்கு எதிராக வரம்பு மீறுபவர், தன்னைக் கொல்ல முற்படாத ஒருவரைக் கொல்பவர் அல்லது அறியாமைக் காலத்துப் (ஜாஹிலிய்யா) பழிவாங்கலுக்காகக் கொல்பவர் ஆவார்.\" பிறகு அல்லாஹ் தனது நபிக்கு வஹீ (இறைச்செய்தி) அருளினான்,\n\r\n\n\r\nوَكَأَيِّن مِّن قَرْيَةٍ هِيَ أَشَدُّ قُوَّةً مِّن قَرْيَتِكَ الَّتِي أَخْرَجَتْكَ أَهْلَكْنَاهُمْ فَلَا نَاصِرَ لَهُمْ\n\r\n\n\r\n(உங்களை வெளியேற்றிய உங்களது ஊரைவிட வலிமைமிக்க எத்தனையோ ஊர்களை நாம் அழித்திருக்கிறோம்; அவர்களுக்கு உதவி செய்வார் எவருமில்லை!)\""},"14":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=15\" class=\"link\">47:15</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:15 ஐ பார்க்கவும்"},"15":{"html":"<strong>சத்தியத்தை வணங்குபவரும் மன இச்சையை வணங்குபவரும் சமமானவர்கள் அல்லர்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَمَن</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">بَيِّنَةٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّبِّهِ</span><br />\r\n<br />\r\n(தமது இறைவனிடமிருந்து தெளிவான சான்றின் மீது இருப்பவர்...) இதன் பொருள், அல்லாஹ் தனது வேதத்தில் அருளிய நேர்வழி மற்றும் ஞானத்தின் காரணமாகவும், அல்லாஹ் அவரைப் படைத்த தூய்மையான இயற்கை இயல்பின் காரணமாகவும், அல்லாஹ்வின் கட்டளைகள் மற்றும் அவனது மார்க்கம் குறித்து தெளிவான அறிவிலும் உறுதியிலும் இருப்பவர் என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَمَن</span> <span class=\"quran-arabic-font text-success\">زُيِّنَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">سُوءُ</span> <span class=\"quran-arabic-font text-success\">عَمَلِهِ</span> <span class=\"quran-arabic-font text-success\">وَاتَّبَعُواْ</span> <span class=\"quran-arabic-font text-success\">أَهْوَاءَهُمْ</span><br />\r\n<br />\r\n((எவனுடைய தீய செயல்கள் அவனுக்கு அழகாக்கப்பட்டு, அவன் தனது மன இச்சைகளைப் பின்பற்றுகிறானோ அவனுக்கு அவர் ஒப்பாக முடியுமா?) அதாவது அவர்கள் இருவரும் ஒருபோதும் சமமாக முடியாது. இது அல்லாஹ்வின் பின்வரும் கூற்றைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَمَن</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">أَنَّمَآ</span> <span class=\"quran-arabic-font text-success\">أُنزِلَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span> <span class=\"quran-arabic-font text-success\">كَمَنْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">أَعْمَى</span><br />\r\n<br />\r\n(உமது இறைவனிடமிருந்து உமக்கு அருளப்பட்டது சத்தியம் என்பதை அறிந்தவர், குருடராக இருப்பவரைப் போல் ஆவாரா?) (<a href=\"qurandisp.php?sura=13&ayah=19\" class=\"link\">13:19</a>). மேலும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَسْتَوِى</span> <span class=\"quran-arabic-font text-success\">أَصْحَابُ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">وَأَصْحَابُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">أَصْحَابُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْفَآئِزُونَ</span><br />\r\n<br />\r\n(நரகவாசிகளும் சொர்க்கவாசிகளும் சமமாக மாட்டார்கள். சொர்க்கவாசிகளே வெற்றியாளர்கள்.) (<a href=\"qurandisp.php?sura=59&ayah=20\" class=\"link\">59:20</a>).<br />\r\n<br />\r\n<strong>சொர்க்கத்தின் வர்ணனை மற்றும் அதன் ஆறுகள்</strong><br />\r\n<br />\r\nபின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَّثَلُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">وُعِدَ</span> <span class=\"quran-arabic-font text-success\">الْمُتَّقُونَ</span><br />\r\n<br />\r\n(இறை அச்சம் (தக்வா) உடையவர்களுக்கு வாக்களிக்கப்பட்ட சொர்க்கத்தின் வர்ணனை...) இக்ரிமா அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَّثَلُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span><br />\r\n<br />\r\n(சொர்க்கத்தின் வர்ணனை) \"இதன் பொருள் அதன் விவரிப்பு என்பதாகும்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فِيهَآ</span> <span class=\"quran-arabic-font text-success\">أَنْهَارٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">مَّآءٍ</span> <span class=\"quran-arabic-font text-success\">غَيْرِ</span> <span class=\"quran-arabic-font text-success\">ءَاسِنٍ</span><br />\r\n<br />\r\n(அதில் 'ஆசின்' ஆகாத (மணம் மாறாத) நீராறுகள் உண்டு,) இப்னு அப்பாஸ் (ரழி) அவர்களும், அல்-ஹஸன் மற்றும் கத்தாதா ஆகியோரும், \"அது சுவை மாறாது\" என்று கூறினார்கள். கத்தாதா, அத்-தஹ்ஹாக் மற்றும் அதா அல்-குராஸானி ஆகியோர், \"அது துர்நாற்றம் வீசாது\" என்று கூறினார்கள். அரபியர்கள் தண்ணீரின் மணம் மாறினால் அதை 'ஆசின்' என்று குறிப்பிடுவார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنْهَارٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">لَّبَنٍ</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">يَتَغَيَّرْ</span> <span class=\"quran-arabic-font text-success\">طَعْمُهُ</span><br />\r\n<br />\r\n(சுவை மாறாத பாலாறுகள்,) அதாவது, அந்தப் பால் மிகுந்த வெண்மையாகவும், இனிமையாகவும், செழுமையாகவும் இருக்கும். நபியவர்களுக்குச் சாற்றப்பட்ட ஒரு ஹதீஸில், \"அவர்களது பால் கால்நடைகளின் மடியிலிருந்து சுரந்தவை அல்ல\" எனக் குறிப்பிடப்பட்டுள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنْهَارٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">خَمْرٍ</span> <span class=\"quran-arabic-font text-success\">لَّذَّةٍ</span> <span class=\"quran-arabic-font text-success\">لِّلشَّـرِبِينَ</span><br />\r\n<br />\r\n(குடிப்பவர்களுக்கு இன்பம் அளிக்கும் மது ஆறுகள்,) அதாவது, அந்த மதுவுக்கு இவ்வுலக மதுவைப் போன்ற கசப்பான சுவையோ அல்லது துர்நாற்றமோ இருக்காது. மாறாக, அது தோற்றம், சுவை, மணம் மற்றும் தன்மையில் மிகச் சிறந்ததாக இருக்கும். அல்லாஹ் கூறுவது போல்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">غَوْلٌ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">عَنْهَا</span> <span class=\"quran-arabic-font text-success\">يُنزَفُونَ</span><br />\r\n<br />\r\n(அதில் (அந்த மதுவில்) தலைவலியோ அல்லது தீய விளைவுகளோ இல்லை, அது போதையையும் ஏற்படுத்தாது.) (<a href=\"qurandisp.php?sura=37&ayah=47\" class=\"link\">37:47</a>) மேலும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يُصَدَّعُونَ</span> <span class=\"quran-arabic-font text-success\">عَنْهَا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يُنزِفُونَ</span><br />\r\n<br />\r\n(அதனால் அவர்களுக்குத் தலைவலியும் ஏற்படாது, அவர்கள் போதையால் புத்தி மாறவும் மாட்டார்கள்.) (<a href=\"qurandisp.php?sura=56&ayah=19\" class=\"link\">56:19</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَيْضَآءَ</span> <span class=\"quran-arabic-font text-success\">لَذَّةٍ</span> <span class=\"quran-arabic-font text-success\">لِّلشَّـرِبِينَ</span><br />\r\n<br />\r\n(அது வெண்மையானது, குடிப்பவர்களுக்கு மிகுந்த சுவையானது.) (<a href=\"qurandisp.php?sura=37&ayah=46\" class=\"link\">37:46</a>). நபியவர்களுக்குச் சாற்றப்பட்ட ஒரு ஹதீஸில், \"அவர்களது மது மனிதர்களின் கால்களால் பிழியப்பட்டதல்ல\" என்று வந்துள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنْهَارٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">عَسَلٍ</span> <span class=\"quran-arabic-font text-success\">مُّصَفًّى</span><br />\r\n<br />\r\n(மற்றும் சுத்திகரிக்கப்பட்ட தேன் ஆறுகள்;) அதாவது, அந்தத் தேன் மிகுந்த தூய்மையாகவும், மிகச்சிறந்த நிறம், சுவை மற்றும் மணம் கொண்டதாகவும் இருக்கும். நபியவர்களுக்குச் சாற்றப்பட்ட ஒரு ஹதீஸில், \"அவர்களது தேன் தேனீக்களின் வயிற்றிலிருந்து வெளிவந்ததல்ல\" என்று குறிப்பிடப்பட்டுள்ளது. இமாம் அஹ்மத் அவர்கள், ஹகீம் பின் முஆவியா அவர்கள் தனது தந்தையிடமிருந்து அறிவித்ததாகப் பதிவு செய்துள்ளார்கள்; அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">بَحْرُ</span> <span class=\"quran-arabic-font text-success\">اللَّبَنِ</span> <span class=\"quran-arabic-font text-success\">وَبَحْرُ</span> <span class=\"quran-arabic-font text-success\">الْمَاءِ</span> <span class=\"quran-arabic-font text-success\">وَبَحْرُ</span> <span class=\"quran-arabic-font text-success\">الْعَسَلِ</span> <span class=\"quran-arabic-font text-success\">وَبَحْرُ</span> <span class=\"quran-arabic-font text-success\">الْخَمْرِ،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">تُشَقَّقُ</span> <span class=\"quran-arabic-font text-success\">الْأَنْهَارُ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">بَعْد</span>»<br />\r\n<br />\r\n(நிச்சயமாக சொர்க்கத்தில் ஒரு பால் கடலும், ஒரு நீர் கடலும், ஒரு தேன் கடலும், ஒரு மது கடலும் உள்ளன. பின்னர் அவற்றிலிருந்து ஆறுகள் பிரிந்து ஓடுகின்றன.) அத்-திர்மிதி அவர்கள் இந்த அறிவிப்பை 'சொர்க்கத்தின் வர்ணனை' என்ற அத்தியாயத்தில் பதிவு செய்து, இது \"ஹஸன் ஸஹீஹ்\" என்று குறிப்பிட்டுள்ளார். ஸஹீஹ் புகாரியில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாகப் பின்வருமாறு பதிவாகியுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">سَأَلْتُمُ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">تَعَالى</span> <span class=\"quran-arabic-font text-success\">فَاسْأَلُوهُ</span> <span class=\"quran-arabic-font text-success\">الْفِرْدَوْسَ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">أَوْسَطُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ،</span> <span class=\"quran-arabic-font text-success\">وَأَعْلَى</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ،</span> <span class=\"quran-arabic-font text-success\">وَمِنْهُ</span> <span class=\"quran-arabic-font text-success\">تُفَجَّرُ</span> <span class=\"quran-arabic-font text-success\">أَنْهَارُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ،</span> <span class=\"quran-arabic-font text-success\">وَفَوْقَهُ</span> <span class=\"quran-arabic-font text-success\">عَرْشُ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمن</span>»<br />\r\n<br />\r\n(நீங்கள் அல்லாஹ்விடம் கேட்டால், அவனிடம் 'அல்-ஃபிர்தவ்ஸ்' எனும் சொர்க்கத்தைக் கேளுங்கள். ஏனெனில் அதுதான் சொர்க்கத்தின் மையமான மற்றும் மிக உயர்ந்த பகுதியாகும்; அங்கிருந்தே சொர்க்கத்தின் ஆறுகள் பீறிட்டு ஓடுகின்றன. அதன் மேலே அளவற்ற அருளாளனின் (அல்லாஹ்வின்) அர்ஷ் உள்ளது.) அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">الثَّمَرَاتِ</span><br />\r\n<br />\r\n(...மேலும் அதில் அவர்களுக்கு எல்லா வகையான கனிகளும் உண்டு, ...) இது அவனது மற்றொரு வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَدْعُونَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">فَاكِهَةٍ</span> <span class=\"quran-arabic-font text-success\">ءَامِنِينَ</span><br />\r\n<br />\r\n(அவர்கள் அதில் எல்லா வகையான பழங்களையும் அமைதியுடனும் பாதுகாப்பாகவும் கேட்டுப் பெறுவார்கள்.) (<a href=\"qurandisp.php?sura=44&ayah=55\" class=\"link\">44:55</a>). மேலும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فِيهِمَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">فَاكِهَةٍ</span> <span class=\"quran-arabic-font text-success\">زَوْجَانِ</span><br />\r\n<br />\r\n(அவ்விரண்டிலும் ஒவ்வொரு வகையான பழங்களும் ஜோடிகளாக இருக்கும்.) (<a href=\"qurandisp.php?sura=55&ayah=52\" class=\"link\">55:52</a>). அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَغْفِرَةٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّبِّهِمْ</span><br />\r\n<br />\r\n(...மற்றும் அவர்களுடைய இறைவனிடமிருந்து மன்னிப்பும் உண்டு.) அதாவது, மேலே குறிப்பிடப்பட்ட அருட்கொடைகள் அனைத்திற்கும் மேலாக இதுவும் உண்டு. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَمَنْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">خَـلِدٌ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span><br />\r\n<br />\r\n(இவர்கள், நரக நெருப்பில் நிரந்தரமாகத் தங்கியிருப்பவர்களுக்கு நிகராவார்களா?) அதாவது, சொர்க்கத்தில் நாம் விவரித்த உயர்ந்த நிலையில் இருப்பவர்கள், நரகத்தில் நிரந்தரமாகத் தங்கியிருப்பவர்களுக்குச் சமமாக முடியுமா? அவர்கள் ஒருபோதும் சமமானவர்கள் அல்லர்; அதேபோல் (சொர்க்கத்தின்) உயர்ந்த அந்தஸ்துகளில் இருப்பவர்களும், (நரகத்தின்) ஆழமான படுகுழிகளில் இருப்பவர்களும் சமமாக முடியாது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَسُقُواْ</span> <span class=\"quran-arabic-font text-success\">مَآءً</span> <span class=\"quran-arabic-font text-success\">حَمِيماً</span><br />\r\n<br />\r\n(மேலும் கொதிக்கும் நீர் அவர்களுக்குக் குடிக்கக் கொடுக்கப்படும்) அதாவது, அந்த நீர் தாங்க முடியாத அளவுக்கு மிகக் கடுமையான சூடாக இருக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَقَطَّعَ</span> <span class=\"quran-arabic-font text-success\">أَمْعَآءَهُمْ</span><br />\r\n<br />\r\n(அது அவர்களது குடல்களைத் துண்டு துண்டாக்கிவிடும்) அதாவது, அது அவர்களது உட்புறக் குடல்களையும் சிறுகுடல்களையும் சிதைத்துவிடும். அத்தகைய நிலையிலிருந்து அல்லாஹ்விடம் நாம் பாதுகாப்புத் தேடுகிறோம்.<br />\r\n<br />","text":"சத்தியத்தை வணங்குபவரும் மன இச்சையை வணங்குபவரும் சமமானவர்கள் அல்லர்\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأَفَمَن كَانَ عَلَى بَيِّنَةٍ مِّن رَّبِّهِ\n\r\n\n\r\n(தமது இறைவனிடமிருந்து தெளிவான சான்றின் மீது இருப்பவர்...) இதன் பொருள், அல்லாஹ் தனது வேதத்தில் அருளிய நேர்வழி மற்றும் ஞானத்தின் காரணமாகவும், அல்லாஹ் அவரைப் படைத்த தூய்மையான இயற்கை இயல்பின் காரணமாகவும், அல்லாஹ்வின் கட்டளைகள் மற்றும் அவனது மார்க்கம் குறித்து தெளிவான அறிவிலும் உறுதியிலும் இருப்பவர் என்பதாகும்.\n\r\n\n\r\nكَمَن زُيِّنَ لَهُ سُوءُ عَمَلِهِ وَاتَّبَعُواْ أَهْوَاءَهُمْ\n\r\n\n\r\n((எவனுடைய தீய செயல்கள் அவனுக்கு அழகாக்கப்பட்டு, அவன் தனது மன இச்சைகளைப் பின்பற்றுகிறானோ அவனுக்கு அவர் ஒப்பாக முடியுமா?) அதாவது அவர்கள் இருவரும் ஒருபோதும் சமமாக முடியாது. இது அல்லாஹ்வின் பின்வரும் கூற்றைப் போன்றதாகும்:\n\r\n\n\r\nأَفَمَن يَعْلَمُ أَنَّمَآ أُنزِلَ إِلَيْكَ مِن رَبِّكَ الْحَقُّ كَمَنْ هُوَ أَعْمَى\n\r\n\n\r\n(உமது இறைவனிடமிருந்து உமக்கு அருளப்பட்டது சத்தியம் என்பதை அறிந்தவர், குருடராக இருப்பவரைப் போல் ஆவாரா?) (13:19). மேலும்,\n\r\n\n\r\nلاَ يَسْتَوِى أَصْحَابُ النَّارِ وَأَصْحَابُ الْجَنَّةِ أَصْحَابُ الْجَنَّةِ هُمُ الْفَآئِزُونَ\n\r\n\n\r\n(நரகவாசிகளும் சொர்க்கவாசிகளும் சமமாக மாட்டார்கள். சொர்க்கவாசிகளே வெற்றியாளர்கள்.) (59:20).\n\r\n\n\r\nசொர்க்கத்தின் வர்ணனை மற்றும் அதன் ஆறுகள்\n\r\n\n\r\nபின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nمَّثَلُ الْجَنَّةِ الَّتِى وُعِدَ الْمُتَّقُونَ\n\r\n\n\r\n(இறை அச்சம் (தக்வா) உடையவர்களுக்கு வாக்களிக்கப்பட்ட சொர்க்கத்தின் வர்ணனை...) இக்ரிமா அவர்கள் கூறினார்கள்:\n\r\n\n\r\nمَّثَلُ الْجَنَّةِ\n\r\n\n\r\n(சொர்க்கத்தின் வர்ணனை) \"இதன் பொருள் அதன் விவரிப்பு என்பதாகும்.\"\n\r\n\n\r\nفِيهَآ أَنْهَارٌ مِّن مَّآءٍ غَيْرِ ءَاسِنٍ\n\r\n\n\r\n(அதில் 'ஆசின்' ஆகாத (மணம் மாறாத) நீராறுகள் உண்டு,) இப்னு அப்பாஸ் (ரழி) அவர்களும், அல்-ஹஸன் மற்றும் கத்தாதா ஆகியோரும், \"அது சுவை மாறாது\" என்று கூறினார்கள். கத்தாதா, அத்-தஹ்ஹாக் மற்றும் அதா அல்-குராஸானி ஆகியோர், \"அது துர்நாற்றம் வீசாது\" என்று கூறினார்கள். அரபியர்கள் தண்ணீரின் மணம் மாறினால் அதை 'ஆசின்' என்று குறிப்பிடுவார்கள்.\n\r\n\n\r\nوَأَنْهَارٌ مِّن لَّبَنٍ لَّمْ يَتَغَيَّرْ طَعْمُهُ\n\r\n\n\r\n(சுவை மாறாத பாலாறுகள்,) அதாவது, அந்தப் பால் மிகுந்த வெண்மையாகவும், இனிமையாகவும், செழுமையாகவும் இருக்கும். நபியவர்களுக்குச் சாற்றப்பட்ட ஒரு ஹதீஸில், \"அவர்களது பால் கால்நடைகளின் மடியிலிருந்து சுரந்தவை அல்ல\" எனக் குறிப்பிடப்பட்டுள்ளது.\n\r\n\n\r\nوَأَنْهَارٌ مِّنْ خَمْرٍ لَّذَّةٍ لِّلشَّـرِبِينَ\n\r\n\n\r\n(குடிப்பவர்களுக்கு இன்பம் அளிக்கும் மது ஆறுகள்,) அதாவது, அந்த மதுவுக்கு இவ்வுலக மதுவைப் போன்ற கசப்பான சுவையோ அல்லது துர்நாற்றமோ இருக்காது. மாறாக, அது தோற்றம், சுவை, மணம் மற்றும் தன்மையில் மிகச் சிறந்ததாக இருக்கும். அல்லாஹ் கூறுவது போல்:\n\r\n\n\r\nلاَ فِيهَا غَوْلٌ وَلاَ هُمْ عَنْهَا يُنزَفُونَ\n\r\n\n\r\n(அதில் (அந்த மதுவில்) தலைவலியோ அல்லது தீய விளைவுகளோ இல்லை, அது போதையையும் ஏற்படுத்தாது.) (37:47) மேலும்,\n\r\n\n\r\nلاَّ يُصَدَّعُونَ عَنْهَا وَلاَ يُنزِفُونَ\n\r\n\n\r\n(அதனால் அவர்களுக்குத் தலைவலியும் ஏற்படாது, அவர்கள் போதையால் புத்தி மாறவும் மாட்டார்கள்.) (56:19).\n\r\n\n\r\nبَيْضَآءَ لَذَّةٍ لِّلشَّـرِبِينَ\n\r\n\n\r\n(அது வெண்மையானது, குடிப்பவர்களுக்கு மிகுந்த சுவையானது.) (37:46). நபியவர்களுக்குச் சாற்றப்பட்ட ஒரு ஹதீஸில், \"அவர்களது மது மனிதர்களின் கால்களால் பிழியப்பட்டதல்ல\" என்று வந்துள்ளது.\n\r\n\n\r\nوَأَنْهَارٌ مِّنْ عَسَلٍ مُّصَفًّى\n\r\n\n\r\n(மற்றும் சுத்திகரிக்கப்பட்ட தேன் ஆறுகள்;) அதாவது, அந்தத் தேன் மிகுந்த தூய்மையாகவும், மிகச்சிறந்த நிறம், சுவை மற்றும் மணம் கொண்டதாகவும் இருக்கும். நபியவர்களுக்குச் சாற்றப்பட்ட ஒரு ஹதீஸில், \"அவர்களது தேன் தேனீக்களின் வயிற்றிலிருந்து வெளிவந்ததல்ல\" என்று குறிப்பிடப்பட்டுள்ளது. இமாம் அஹ்மத் அவர்கள், ஹகீம் பின் முஆவியா அவர்கள் தனது தந்தையிடமிருந்து அறிவித்ததாகப் பதிவு செய்துள்ளார்கள்; அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«فِي الْجَنَّةِ بَحْرُ اللَّبَنِ وَبَحْرُ الْمَاءِ وَبَحْرُ الْعَسَلِ وَبَحْرُ الْخَمْرِ، ثُمَّ تُشَقَّقُ الْأَنْهَارُ مِنْهَا بَعْد»\n\r\n\n\r\n(நிச்சயமாக சொர்க்கத்தில் ஒரு பால் கடலும், ஒரு நீர் கடலும், ஒரு தேன் கடலும், ஒரு மது கடலும் உள்ளன. பின்னர் அவற்றிலிருந்து ஆறுகள் பிரிந்து ஓடுகின்றன.) அத்-திர்மிதி அவர்கள் இந்த அறிவிப்பை 'சொர்க்கத்தின் வர்ணனை' என்ற அத்தியாயத்தில் பதிவு செய்து, இது \"ஹஸன் ஸஹீஹ்\" என்று குறிப்பிட்டுள்ளார். ஸஹீஹ் புகாரியில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாகப் பின்வருமாறு பதிவாகியுள்ளது:\n\r\n\n\r\n«إِذَا سَأَلْتُمُ اللهَ تَعَالى فَاسْأَلُوهُ الْفِرْدَوْسَ فَإِنَّهُ أَوْسَطُ الْجَنَّةِ، وَأَعْلَى الْجَنَّةِ، وَمِنْهُ تُفَجَّرُ أَنْهَارُ الْجَنَّةِ، وَفَوْقَهُ عَرْشُ الرَّحْمن»\n\r\n\n\r\n(நீங்கள் அல்லாஹ்விடம் கேட்டால், அவனிடம் 'அல்-ஃபிர்தவ்ஸ்' எனும் சொர்க்கத்தைக் கேளுங்கள். ஏனெனில் அதுதான் சொர்க்கத்தின் மையமான மற்றும் மிக உயர்ந்த பகுதியாகும்; அங்கிருந்தே சொர்க்கத்தின் ஆறுகள் பீறிட்டு ஓடுகின்றன. அதன் மேலே அளவற்ற அருளாளனின் (அல்லாஹ்வின்) அர்ஷ் உள்ளது.) அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَلَهُمْ فِيهَا مِن كُلِّ الثَّمَرَاتِ\n\r\n\n\r\n(...மேலும் அதில் அவர்களுக்கு எல்லா வகையான கனிகளும் உண்டு, ...) இது அவனது மற்றொரு வசனத்தைப் போன்றது:\n\r\n\n\r\nيَدْعُونَ فِيهَا بِكُلِّ فَاكِهَةٍ ءَامِنِينَ\n\r\n\n\r\n(அவர்கள் அதில் எல்லா வகையான பழங்களையும் அமைதியுடனும் பாதுகாப்பாகவும் கேட்டுப் பெறுவார்கள்.) (44:55). மேலும்,\n\r\n\n\r\nفِيهِمَا مِن كُلِّ فَاكِهَةٍ زَوْجَانِ\n\r\n\n\r\n(அவ்விரண்டிலும் ஒவ்வொரு வகையான பழங்களும் ஜோடிகளாக இருக்கும்.) (55:52). அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَمَغْفِرَةٌ مِّن رَّبِّهِمْ\n\r\n\n\r\n(...மற்றும் அவர்களுடைய இறைவனிடமிருந்து மன்னிப்பும் உண்டு.) அதாவது, மேலே குறிப்பிடப்பட்ட அருட்கொடைகள் அனைத்திற்கும் மேலாக இதுவும் உண்டு. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nكَمَنْ هُوَ خَـلِدٌ فِى النَّارِ\n\r\n\n\r\n(இவர்கள், நரக நெருப்பில் நிரந்தரமாகத் தங்கியிருப்பவர்களுக்கு நிகராவார்களா?) அதாவது, சொர்க்கத்தில் நாம் விவரித்த உயர்ந்த நிலையில் இருப்பவர்கள், நரகத்தில் நிரந்தரமாகத் தங்கியிருப்பவர்களுக்குச் சமமாக முடியுமா? அவர்கள் ஒருபோதும் சமமானவர்கள் அல்லர்; அதேபோல் (சொர்க்கத்தின்) உயர்ந்த அந்தஸ்துகளில் இருப்பவர்களும், (நரகத்தின்) ஆழமான படுகுழிகளில் இருப்பவர்களும் சமமாக முடியாது.\n\r\n\n\r\nوَسُقُواْ مَآءً حَمِيماً\n\r\n\n\r\n(மேலும் கொதிக்கும் நீர் அவர்களுக்குக் குடிக்கக் கொடுக்கப்படும்) அதாவது, அந்த நீர் தாங்க முடியாத அளவுக்கு மிகக் கடுமையான சூடாக இருக்கும்.\n\r\n\n\r\nفَقَطَّعَ أَمْعَآءَهُمْ\n\r\n\n\r\n(அது அவர்களது குடல்களைத் துண்டு துண்டாக்கிவிடும்) அதாவது, அது அவர்களது உட்புறக் குடல்களையும் சிறுகுடல்களையும் சிதைத்துவிடும். அத்தகைய நிலையிலிருந்து அல்லாஹ்விடம் நாம் பாதுகாப்புத் தேடுகிறோம்."},"16":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=19\" class=\"link\">47:19</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:19 ஐ பார்க்கவும்"},"17":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=19\" class=\"link\">47:19</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:19 ஐ பார்க்கவும்"},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=19\" class=\"link\">47:19</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:19 ஐ பார்க்கவும்"},"19":{"html":"<strong>நயவஞ்சகர்களின் நிலை குறித்த விளக்கமும், தவ்ஹீதைப் பேணுவதற்கும் பாவமன்னிப்புத் தேடுவதற்கும் விடுக்கப்பட்ட கட்டளையும்</strong><br />\r\n<br />\r\nநயவஞ்சகர்களின் முட்டாள்தனத்தையும் அவர்களின் குறுகிய புரிதலையும் அல்லாஹ் விவரிக்கிறான். அவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு முன்னால் அமர்ந்து, எதையும் புரிந்து கொள்ளாமல் அவர்களின் வார்த்தைகளைக் கேட்டுக் கொண்டிருப்பார்கள். பிறகு அவர்கள் அவ்விடத்தை விட்டு வெளியேறியதும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">لِلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">أُوتُواْ</span> <span class=\"quran-arabic-font text-success\">الْعِلْمَ</span><br />\r\n(ஸஹாபாக்களில்) கல்வி வழங்கப்பட்டவர்களிடம் கூறுவார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَاذَا</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">ءَانِفاً</span><br />\r\n\"சற்று நேரத்திற்கு முன்பு அவர்கள் என்ன கூறினார்கள்?\" அதாவது, இந்தத் தருணத்தில். அவர்கள் (ஸல்) கூறியதை இவர்கள் புரிந்து கொள்ளவில்லை; அதைப் பொருட்படுத்தவும் இல்லை. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">طَبَعَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">قُلُوبِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَاتَّبَعُواْ</span> <span class=\"quran-arabic-font text-success\">أَهْوَآءَهُمْ</span><br />\r\n\"இவர்கள்தான் தங்கள் மன இச்சைகளைப் பின்பற்றியதின் காரணமாக, அல்லாஹ் யாருடைய இதயங்களில் முத்திரையிட்டானோ அத்தகையவர்கள்.\" அதாவது, இவர்களுக்கு முறையான புரிதலோ அல்லது சரியான நோக்கங்களோ இருக்கவில்லை. பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">اهْتَدَوْاْ</span> <span class=\"quran-arabic-font text-success\">زَادَهُمْ</span> <span class=\"quran-arabic-font text-success\">هُدًى</span><br />\r\n\"யார் நேர்வழியை ஏற்றுக்கொண்டார்களோ, அவர்களுக்கு அவன் நேர்வழியை அதிகரிக்கிறான்.\" அதாவது, நேர்வழியைத் தேடுபவர்களுக்கு அல்லாஹ் அதனை எளிதாக்குகிறான்; அவர்களுக்கு வழிகாட்டி, அதில் அவர்களை உறுதிப்படுத்தி, மேலும் மேலான வழிகாட்டுதலை வழங்குகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَءَاتَـهُمْ</span> <span class=\"quran-arabic-font text-success\">تَقُوَاهُمْ</span><br />\r\n\"மேலும் அவர்களுக்கு அவர்களின் தக்வாவை (இறையச்சத்தை) வழங்கினான்.\" அதாவது, அவர்களின் நேர்மையான வழிகாட்டுதலுக்கு அவன் அவர்களுக்குத் தூண்டுதல் அளிக்கிறான். பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَهَلْ</span> <span class=\"quran-arabic-font text-success\">يَنظُرُونَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةَ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَأْتِيَهُمْ</span> <span class=\"quran-arabic-font text-success\">بَغْتَةً</span><br />\r\n\"மறுமை நாள் தங்களுக்குத் திடீரென வருவதைத் தவிர வேறு எதனை அவர்கள் எதிர்பார்க்கிறார்கள்?\" அதாவது, அவர்கள் அதனை உணராத நிலையில் அது வரும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَقَدْ</span> <span class=\"quran-arabic-font text-success\">جَآءَ</span> <span class=\"quran-arabic-font text-success\">أَشْرَاطُهَا</span><br />\r\n\"நிச்சயமாக அதன் அடையாளங்கள் ஏற்கனவே வந்துவிட்டன.\" அதாவது, அது நெருங்கிவிட்டதற்கான அறிகுறிகள். இது அல்லாஹ்வின் பின்வரும் வசனங்களைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">نَذِيرٌ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">النُّذُرِ</span> <span class=\"quran-arabic-font text-success\">الْأُولَى</span> - <span class=\"quran-arabic-font text-success\">أَزِفَتِ</span> <span class=\"quran-arabic-font text-success\">الْآزِفَةُ</span><br />\r\n\"முந்தைய எச்சரிக்கையாளர்களில் இவரும் ஒரு எச்சரிக்கையாளர் ஆவார். நெருங்க வேண்டிய (மறுமை) நாள் நெருங்கிவிட்டது.\" (<a href=\"qurandisp.php?sura=53&ayah=56\" class=\"link\">53:56</a>-57). மேலும் அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">اقْتَرَبَتِ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةُ</span> <span class=\"quran-arabic-font text-success\">وَانشَقَّ</span> <span class=\"quran-arabic-font text-success\">الْقَمَرُ</span><br />\r\n\"மறுமை நாள் நெருங்கிவிட்டது; சந்திரன் பிளந்துவிட்டது.\" (<a href=\"qurandisp.php?sura=54&ayah=1\" class=\"link\">54:1</a>). மேலும் அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَتَى</span> <span class=\"quran-arabic-font text-success\">أَمْرُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">تَسْتَعْجِلُوهُ</span><br />\r\n\"அல்லாஹ்வின் கட்டளை வந்துவிட்டது; எனவே அதற்காக நீங்கள் அவசரப்பட வேண்டாம்.\" (<a href=\"qurandisp.php?sura=16&ayah=1\" class=\"link\">16:1</a>). மேலும் அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">اقْتَرَبَ</span> <span class=\"quran-arabic-font text-success\">لِلنَّاسِ</span> <span class=\"quran-arabic-font text-success\">حِسَـبُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">غَفْلَةٍ</span> <span class=\"quran-arabic-font text-success\">مُّعْرِضُونَ</span><br />\r\n\"மக்களின் விசாரணை நாள் நெருங்கிவிட்டது; ஆனால் அவர்களோ கவனக்குறைவில் (அதனைப்) புறக்கணித்துக் கொண்டிருக்கிறார்கள்.\" (<a href=\"qurandisp.php?sura=21&ayah=1\" class=\"link\">21:1</a>).<br />\r\n<br />\r\nஎனவே, தூதர் (ஸல்) அவர்களின் வருகையே மறுமை நாளின் அடையாளங்களில் ஒன்றாகும். ஏனெனில் அவர்கள் இறுதித் தூதராவார்கள். அவர்களைக் கொண்டு அல்லாஹ் மார்க்கத்தைப் பூரணப்படுத்தினான். முந்தைய எந்த நபியின் மூலமும் நிலைநாட்டப்படாத வகையில், மக்கள் அனைவருக்கும் எதிராகத் தன் ஆதாரத்தை நிலைநாட்டினான். நாம் வேறொரு இடத்தில் விவாதித்தபடி, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மறுமை நாளின் அறிகுறிகளையும் அடையாளங்களையும் மிகத் தெளிவாக விளக்கியுள்ளார்கள். சஹ்ல் பின் ஸஅத் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தங்களின் ஆள்காட்டி விரலையும் நடுவிரலையும் இணைத்துக் காட்டி பின்வருமாறு கூறியதை நான் கண்டேன்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">بُعِثْتُ</span> <span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">وَالسَّاعَةَ</span> <span class=\"quran-arabic-font text-success\">كَهَاتَيْن</span>»<br />\r\n\"நானும் மறுமை நாளும் இந்த இரு விரல்களைப் போன்ற நிலையில் (நெருக்கமாக) அனுப்பப்பட்டுள்ளோம்.\" அல்லாஹ் தொடர்ந்து கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَنَّى</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">جَآءَتْهُمْ</span> <span class=\"quran-arabic-font text-success\">ذِكْرَاهُمْ</span><br />\r\n\"அது (மறுமை நாள்) அவர்களிடம் வந்துவிடும்போது, அவர்கள் பெறும் நினைவூட்டல் அவர்களுக்கு எப்படிப் பயன் தரும்?\" அதாவது, மறுமை நாள் வரும்போது அந்த நினைவூட்டல் நிராகரிப்பாளர்களுக்கு எவ்வாறு பயன் அளிக்கும்? இது அல்லாஹ்வின் பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">يَتَذَكَّرُ</span> <span class=\"quran-arabic-font text-success\">الإِنسَـنُ</span> <span class=\"quran-arabic-font text-success\">وَأَنَّى</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الذِّكْرَى</span><br />\r\n\"அந்நாளில் மனிதன் நினைவு கூர்வான்; ஆனால் அந்த நினைவூட்டல் அவனுக்கு அப்போது என்ன பயனைத் தரும்?\" (<a href=\"qurandisp.php?sura=89&ayah=23\" class=\"link\">89:23</a>). மேலும் அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">ءَامَنَّا</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">وَأَنَّى</span> <span class=\"quran-arabic-font text-success\">لَهُمُ</span> <span class=\"quran-arabic-font text-success\">التَّنَاوُشُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مَّكَانِ</span> <span class=\"quran-arabic-font text-success\">بَعِيدٍ</span><br />\r\n\"(மறுமையில்) அவர்கள் கூறுவார்கள்: 'இப்போது நாங்கள் இதனை நம்புகிறோம்!' ஆனால் இவ்வளவு தொலைவான இடத்திலிருந்து அவர்களுக்கு நம்பிக்கை எவ்வாறு கிட்டும்?\" (<a href=\"qurandisp.php?sura=34&ayah=52\" class=\"link\">34:52</a>).<br />\r\n<br />\r\nஅல்லாஹ் பிறகு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاعْلَمْ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">إِلَـهَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span><br />\r\n\"எனவே, அல்லாஹ்வைத் தவிர வேறு வணக்கத்திற்குரிய இறைவன் இல்லை என்பதை நீர் அறிந்து கொள்வீராக.\" இது அல்லாஹ்வைத் தவிர வேறு உண்மையான இறைவன் இல்லை என்பதற்கான பிரகடனம் ஆகும். இதனை மக்கள் அறிந்துகொள்ள வேண்டும் என்பது ஒரு சாதாரண கட்டளை அல்ல. அதனால்தான் அல்லாஹ் அதனைத் தொடர்ந்து பின்வருமாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاسْتَغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لِذَنبِكَ</span> <span class=\"quran-arabic-font text-success\">وَلِلْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">وَالْمُؤْمِنَـتِ</span><br />\r\n\"உமது பாவத்திற்காகவும், இறைநம்பிக்கை கொண்ட ஆண்களுக்காகவும் பெண்களுக்காகவும் மன்னிப்புத் தேடுவீராக.\" ஸஹீஹ் நூலில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு பிரார்த்திப்பார்கள் எனப் பதிவு செய்யப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اللَّهُمَّ</span> <span class=\"quran-arabic-font text-success\">اغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">خَطِيئَتِي</span> <span class=\"quran-arabic-font text-success\">وَجَهْلِي</span> <span class=\"quran-arabic-font text-success\">وَإِسْرَافِي</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">أَمْرِي</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">أَنْتَ</span> <span class=\"quran-arabic-font text-success\">أَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مِنِّي،</span> <span class=\"quran-arabic-font text-success\">اللَّهُمَّ</span> <span class=\"quran-arabic-font text-success\">اغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">هَزْلِي</span> <span class=\"quran-arabic-font text-success\">وَجِدِّي،</span> <span class=\"quran-arabic-font text-success\">وَخَطَئِي</span> <span class=\"quran-arabic-font text-success\">وَعَمْدِي،</span> <span class=\"quran-arabic-font text-success\">وَكُلُّ</span> <span class=\"quran-arabic-font text-success\">ذلِكَ</span> <span class=\"quran-arabic-font text-success\">عِنْدِي</span>»<br />\r\n\"யா அல்லாஹ்! என் பாவத்தையும், என் அறியாமையையும், என் காரியங்களில் நான் செய்த வரம்பு மீறல்களையும், என்னை விட நீ எதை நன்கு அறிந்து வைத்துள்ளாயோ அதையும் எனக்கு மன்னிப்பாயாக. யா அல்லாஹ்! என் விளையாட்டுத்தனத்தையும், என் தீவிரமான செயலையும், நான் அறியாமல் செய்த பிழையையும், நான் வேண்டுமென்றே செய்தவற்றையும் எனக்கு மன்னிப்பாயாக - இவை அனைத்தும் என்னிடம் உள்ளன.\"<br />\r\n<br />\r\nஅவர்கள் (ஸல்) தொழுகையின் இறுதியில் இவ்வாறு கூறுவார்கள் என்பதும் ஸஹீஹ் நூலில் இடம்பெற்றுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اللَّهُمَّ</span> <span class=\"quran-arabic-font text-success\">اغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">قَدَّمْتُ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">أَخَّرْتُ،</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">أَسْرَرْتُ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">أَعْلَنْتُ،</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">أَسْرَفْتُ،</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">أَنْتَ</span> <span class=\"quran-arabic-font text-success\">أَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مِنِّي،</span> <span class=\"quran-arabic-font text-success\">أَنْتَ</span> <span class=\"quran-arabic-font text-success\">إِلهِي</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">إِلهَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">أَنْت</span>»<br />\r\n\"யா அல்லாஹ்! நான் முன்பு செய்தவை, பின்னால் செய்யப்படுபவை, நான் இரகசியமாகச் செய்தவை, பகிரங்கமாகச் செய்தவை, நான் செய்த வரம்பு மீறல்கள் மற்றும் என்னை விட நீ எதை நன்கு அறிந்துள்ளாயோ அத்தகைய பாவங்களை எனக்கு மன்னிப்பாயாக. நீயே என் இறைவன். உன்னைத் தவிர வணக்கத்திற்குரிய இறைவன் வேறு யாருமில்லை.\"<br />\r\n<br />\r\nமேலும் ஸஹீஹ் நூலில் அவர்கள் (ஸல்) இவ்வாறு கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَاأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">تُوبُوا</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّكُمْ،</span> <span class=\"quran-arabic-font text-success\">فَإِنِّي</span> <span class=\"quran-arabic-font text-success\">أَسْتَغْفِرُ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">وَأَتُوبُ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْيَوْمِ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">سَبْعِينَ</span> <span class=\"quran-arabic-font text-success\">مَرَّة</span>»<br />\r\n\"மக்களே! உங்கள் இறைவனிடம் தவ்பா (பாவமன்னிப்புத் தேடி மீளுதல்) செய்யுங்கள். நிச்சயமாக நான் ஒரு நாளில் எழுபதுக்கும் மேற்பட்ட முறை அல்லாஹ்விடம் பாவமன்னிப்புத் தேடி அவனிடம் மீளுகிறேன்.\"<br />\r\n<br />\r\nஅல்லாஹ் பிறகு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">مُتَقَلَّبَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَمَثْوَاكُمْ</span><br />\r\n\"அல்லாஹ் உங்கள் நடமாட்டத்தையும் உங்கள் தங்குமிடத்தையும் நன்கு அறிவான்.\" அதாவது, பகலில் நீங்கள் என்ன செய்கிறீர்கள் என்பதையும் இரவில் நீங்கள் எங்குத் தங்குகிறீர்கள் என்பதையும் அவன் அறிவான். இது அவனது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يَتَوَفَّـكُم</span> <span class=\"quran-arabic-font text-success\">بِالَّيْلِ</span> <span class=\"quran-arabic-font text-success\">وَيَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">جَرَحْتُم</span> <span class=\"quran-arabic-font text-success\">بِالنَّهَارِ</span><br />\r\n\"அவனே இரவில் உங்களைக் கைப்பற்றுகிறான் (தூங்கச் செய்கிறான்); பகலில் நீங்கள் செய்வதையெல்லாம் அவன் அறிவான்.\" (<a href=\"qurandisp.php?sura=6&ayah=60\" class=\"link\">6:60</a>).<br />\r\n<br />\r\nமேலும் அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دَآبَّةٍ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">رِزْقُهَا</span> <span class=\"quran-arabic-font text-success\">وَيَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">مُسْتَقَرَّهَا</span> <span class=\"quran-arabic-font text-success\">وَمُسْتَوْدَعَهَا</span> <span class=\"quran-arabic-font text-success\">كُلٌّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">كِتَابٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span><br />\r\n\"பூமியில் ஊர்ந்து செல்லும் எந்த உயிரினமானாலும், அதன் வாழ்வாதாரம் அல்லாஹ்வின் மீதே பொறுப்பாக உள்ளது. மேலும் அதன் வசிப்பிடத்தையும் அது ஒப்படைக்கப்படும் இடத்தையும் (பிறப்புக்கு முன்பும் மரணத்திற்குப் பின்பும்) அவன் அறிவான். இவை அனைத்தும் ஒரு தெளிவான பதிவேட்டில் உள்ளன.\" (<a href=\"qurandisp.php?sura=11&ayah=6\" class=\"link\">11:6</a>)<br />\r\n<br />","text":"நயவஞ்சகர்களின் நிலை குறித்த விளக்கமும், தவ்ஹீதைப் பேணுவதற்கும் பாவமன்னிப்புத் தேடுவதற்கும் விடுக்கப்பட்ட கட்டளையும்\n\r\n\n\r\nநயவஞ்சகர்களின் முட்டாள்தனத்தையும் அவர்களின் குறுகிய புரிதலையும் அல்லாஹ் விவரிக்கிறான். அவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு முன்னால் அமர்ந்து, எதையும் புரிந்து கொள்ளாமல் அவர்களின் வார்த்தைகளைக் கேட்டுக் கொண்டிருப்பார்கள். பிறகு அவர்கள் அவ்விடத்தை விட்டு வெளியேறியதும்,\n\r\n\n\r\nقَالُواْ لِلَّذِينَ أُوتُواْ الْعِلْمَ\n\r\n(ஸஹாபாக்களில்) கல்வி வழங்கப்பட்டவர்களிடம் கூறுவார்கள்:\n\r\n\n\r\nمَاذَا قَالَ ءَانِفاً\n\r\n\"சற்று நேரத்திற்கு முன்பு அவர்கள் என்ன கூறினார்கள்?\" அதாவது, இந்தத் தருணத்தில். அவர்கள் (ஸல்) கூறியதை இவர்கள் புரிந்து கொள்ளவில்லை; அதைப் பொருட்படுத்தவும் இல்லை. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأُوْلَـئِكَ الَّذِينَ طَبَعَ اللَّهُ عَلَى قُلُوبِهِمْ وَاتَّبَعُواْ أَهْوَآءَهُمْ\n\r\n\"இவர்கள்தான் தங்கள் மன இச்சைகளைப் பின்பற்றியதின் காரணமாக, அல்லாஹ் யாருடைய இதயங்களில் முத்திரையிட்டானோ அத்தகையவர்கள்.\" அதாவது, இவர்களுக்கு முறையான புரிதலோ அல்லது சரியான நோக்கங்களோ இருக்கவில்லை. பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَالَّذِينَ اهْتَدَوْاْ زَادَهُمْ هُدًى\n\r\n\"யார் நேர்வழியை ஏற்றுக்கொண்டார்களோ, அவர்களுக்கு அவன் நேர்வழியை அதிகரிக்கிறான்.\" அதாவது, நேர்வழியைத் தேடுபவர்களுக்கு அல்லாஹ் அதனை எளிதாக்குகிறான்; அவர்களுக்கு வழிகாட்டி, அதில் அவர்களை உறுதிப்படுத்தி, மேலும் மேலான வழிகாட்டுதலை வழங்குகிறான்.\n\r\n\n\r\nوَءَاتَـهُمْ تَقُوَاهُمْ\n\r\n\"மேலும் அவர்களுக்கு அவர்களின் தக்வாவை (இறையச்சத்தை) வழங்கினான்.\" அதாவது, அவர்களின் நேர்மையான வழிகாட்டுதலுக்கு அவன் அவர்களுக்குத் தூண்டுதல் அளிக்கிறான். பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَهَلْ يَنظُرُونَ إِلاَّ السَّاعَةَ أَن تَأْتِيَهُمْ بَغْتَةً\n\r\n\"மறுமை நாள் தங்களுக்குத் திடீரென வருவதைத் தவிர வேறு எதனை அவர்கள் எதிர்பார்க்கிறார்கள்?\" அதாவது, அவர்கள் அதனை உணராத நிலையில் அது வரும்.\n\r\n\n\r\nفَقَدْ جَآءَ أَشْرَاطُهَا\n\r\n\"நிச்சயமாக அதன் அடையாளங்கள் ஏற்கனவே வந்துவிட்டன.\" அதாவது, அது நெருங்கிவிட்டதற்கான அறிகுறிகள். இது அல்லாஹ்வின் பின்வரும் வசனங்களைப் போன்றதாகும்:\n\r\n\n\r\nهَـذَا نَذِيرٌ مِّنَ النُّذُرِ الْأُولَى - أَزِفَتِ الْآزِفَةُ\n\r\n\"முந்தைய எச்சரிக்கையாளர்களில் இவரும் ஒரு எச்சரிக்கையாளர் ஆவார். நெருங்க வேண்டிய (மறுமை) நாள் நெருங்கிவிட்டது.\" (53:56-57). மேலும் அவன் கூறுகிறான்:\n\r\n\n\r\nاقْتَرَبَتِ السَّاعَةُ وَانشَقَّ الْقَمَرُ\n\r\n\"மறுமை நாள் நெருங்கிவிட்டது; சந்திரன் பிளந்துவிட்டது.\" (54:1). மேலும் அவன் கூறுகிறான்:\n\r\n\n\r\nأَتَى أَمْرُ اللَّهِ فَلاَ تَسْتَعْجِلُوهُ\n\r\n\"அல்லாஹ்வின் கட்டளை வந்துவிட்டது; எனவே அதற்காக நீங்கள் அவசரப்பட வேண்டாம்.\" (16:1). மேலும் அவன் கூறுகிறான்:\n\r\n\n\r\nاقْتَرَبَ لِلنَّاسِ حِسَـبُهُمْ وَهُمْ فِى غَفْلَةٍ مُّعْرِضُونَ\n\r\n\"மக்களின் விசாரணை நாள் நெருங்கிவிட்டது; ஆனால் அவர்களோ கவனக்குறைவில் (அதனைப்) புறக்கணித்துக் கொண்டிருக்கிறார்கள்.\" (21:1).\n\r\n\n\r\nஎனவே, தூதர் (ஸல்) அவர்களின் வருகையே மறுமை நாளின் அடையாளங்களில் ஒன்றாகும். ஏனெனில் அவர்கள் இறுதித் தூதராவார்கள். அவர்களைக் கொண்டு அல்லாஹ் மார்க்கத்தைப் பூரணப்படுத்தினான். முந்தைய எந்த நபியின் மூலமும் நிலைநாட்டப்படாத வகையில், மக்கள் அனைவருக்கும் எதிராகத் தன் ஆதாரத்தை நிலைநாட்டினான். நாம் வேறொரு இடத்தில் விவாதித்தபடி, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மறுமை நாளின் அறிகுறிகளையும் அடையாளங்களையும் மிகத் தெளிவாக விளக்கியுள்ளார்கள். சஹ்ல் பின் ஸஅத் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தங்களின் ஆள்காட்டி விரலையும் நடுவிரலையும் இணைத்துக் காட்டி பின்வருமாறு கூறியதை நான் கண்டேன்:\n\r\n\n\r\n«بُعِثْتُ أَنَا وَالسَّاعَةَ كَهَاتَيْن»\n\r\n\"நானும் மறுமை நாளும் இந்த இரு விரல்களைப் போன்ற நிலையில் (நெருக்கமாக) அனுப்பப்பட்டுள்ளோம்.\" அல்லாஹ் தொடர்ந்து கூறுகிறான்:\n\r\n\n\r\nفَأَنَّى لَهُمْ إِذَا جَآءَتْهُمْ ذِكْرَاهُمْ\n\r\n\"அது (மறுமை நாள்) அவர்களிடம் வந்துவிடும்போது, அவர்கள் பெறும் நினைவூட்டல் அவர்களுக்கு எப்படிப் பயன் தரும்?\" அதாவது, மறுமை நாள் வரும்போது அந்த நினைவூட்டல் நிராகரிப்பாளர்களுக்கு எவ்வாறு பயன் அளிக்கும்? இது அல்லாஹ்வின் பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\nيَوْمَئِذٍ يَتَذَكَّرُ الإِنسَـنُ وَأَنَّى لَهُ الذِّكْرَى\n\r\n\"அந்நாளில் மனிதன் நினைவு கூர்வான்; ஆனால் அந்த நினைவூட்டல் அவனுக்கு அப்போது என்ன பயனைத் தரும்?\" (89:23). மேலும் அவன் கூறுகிறான்:\n\r\n\n\r\nوَقَالُواْ ءَامَنَّا بِهِ وَأَنَّى لَهُمُ التَّنَاوُشُ مِن مَّكَانِ بَعِيدٍ\n\r\n\"(மறுமையில்) அவர்கள் கூறுவார்கள்: 'இப்போது நாங்கள் இதனை நம்புகிறோம்!' ஆனால் இவ்வளவு தொலைவான இடத்திலிருந்து அவர்களுக்கு நம்பிக்கை எவ்வாறு கிட்டும்?\" (34:52).\n\r\n\n\r\nஅல்லாஹ் பிறகு கூறுகிறான்:\n\r\n\n\r\nفَاعْلَمْ أَنَّهُ لَا إِلَـهَ إِلَّا اللَّهُ\n\r\n\"எனவே, அல்லாஹ்வைத் தவிர வேறு வணக்கத்திற்குரிய இறைவன் இல்லை என்பதை நீர் அறிந்து கொள்வீராக.\" இது அல்லாஹ்வைத் தவிர வேறு உண்மையான இறைவன் இல்லை என்பதற்கான பிரகடனம் ஆகும். இதனை மக்கள் அறிந்துகொள்ள வேண்டும் என்பது ஒரு சாதாரண கட்டளை அல்ல. அதனால்தான் அல்லாஹ் அதனைத் தொடர்ந்து பின்வருமாறு கூறுகிறான்:\n\r\n\n\r\nوَاسْتَغْفِرْ لِذَنبِكَ وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَـتِ\n\r\n\"உமது பாவத்திற்காகவும், இறைநம்பிக்கை கொண்ட ஆண்களுக்காகவும் பெண்களுக்காகவும் மன்னிப்புத் தேடுவீராக.\" ஸஹீஹ் நூலில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு பிரார்த்திப்பார்கள் எனப் பதிவு செய்யப்பட்டுள்ளது:\n\r\n\n\r\n«اللَّهُمَّ اغْفِرْ لِي خَطِيئَتِي وَجَهْلِي وَإِسْرَافِي فِي أَمْرِي وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، اللَّهُمَّ اغْفِرْ لِي هَزْلِي وَجِدِّي، وَخَطَئِي وَعَمْدِي، وَكُلُّ ذلِكَ عِنْدِي»\n\r\n\"யா அல்லாஹ்! என் பாவத்தையும், என் அறியாமையையும், என் காரியங்களில் நான் செய்த வரம்பு மீறல்களையும், என்னை விட நீ எதை நன்கு அறிந்து வைத்துள்ளாயோ அதையும் எனக்கு மன்னிப்பாயாக. யா அல்லாஹ்! என் விளையாட்டுத்தனத்தையும், என் தீவிரமான செயலையும், நான் அறியாமல் செய்த பிழையையும், நான் வேண்டுமென்றே செய்தவற்றையும் எனக்கு மன்னிப்பாயாக - இவை அனைத்தும் என்னிடம் உள்ளன.\"\n\r\n\n\r\nஅவர்கள் (ஸல்) தொழுகையின் இறுதியில் இவ்வாறு கூறுவார்கள் என்பதும் ஸஹீஹ் நூலில் இடம்பெற்றுள்ளது:\n\r\n\n\r\n«اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، وَمَا أَسْرَفْتُ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، أَنْتَ إِلهِي لَا إِلهَ إِلَّا أَنْت»\n\r\n\"யா அல்லாஹ்! நான் முன்பு செய்தவை, பின்னால் செய்யப்படுபவை, நான் இரகசியமாகச் செய்தவை, பகிரங்கமாகச் செய்தவை, நான் செய்த வரம்பு மீறல்கள் மற்றும் என்னை விட நீ எதை நன்கு அறிந்துள்ளாயோ அத்தகைய பாவங்களை எனக்கு மன்னிப்பாயாக. நீயே என் இறைவன். உன்னைத் தவிர வணக்கத்திற்குரிய இறைவன் வேறு யாருமில்லை.\"\n\r\n\n\r\nமேலும் ஸஹீஹ் நூலில் அவர்கள் (ஸல்) இவ்வாறு கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:\n\r\n\n\r\n«يَاأَيُّهَا النَّاسُ تُوبُوا إِلَى رَبِّكُمْ، فَإِنِّي أَسْتَغْفِرُ اللهَ وَأَتُوبُ إِلَيْهِ فِي الْيَوْمِ أَكْثَرَ مِنْ سَبْعِينَ مَرَّة»\n\r\n\"மக்களே! உங்கள் இறைவனிடம் தவ்பா (பாவமன்னிப்புத் தேடி மீளுதல்) செய்யுங்கள். நிச்சயமாக நான் ஒரு நாளில் எழுபதுக்கும் மேற்பட்ட முறை அல்லாஹ்விடம் பாவமன்னிப்புத் தேடி அவனிடம் மீளுகிறேன்.\"\n\r\n\n\r\nஅல்லாஹ் பிறகு கூறுகிறான்:\n\r\n\n\r\nوَاللَّهُ يَعْلَمُ مُتَقَلَّبَكُمْ وَمَثْوَاكُمْ\n\r\n\"அல்லாஹ் உங்கள் நடமாட்டத்தையும் உங்கள் தங்குமிடத்தையும் நன்கு அறிவான்.\" அதாவது, பகலில் நீங்கள் என்ன செய்கிறீர்கள் என்பதையும் இரவில் நீங்கள் எங்குத் தங்குகிறீர்கள் என்பதையும் அவன் அறிவான். இது அவனது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\nوَهُوَ الَّذِى يَتَوَفَّـكُم بِالَّيْلِ وَيَعْلَمُ مَا جَرَحْتُم بِالنَّهَارِ\n\r\n\"அவனே இரவில் உங்களைக் கைப்பற்றுகிறான் (தூங்கச் செய்கிறான்); பகலில் நீங்கள் செய்வதையெல்லாம் அவன் அறிவான்.\" (6:60).\n\r\n\n\r\nமேலும் அவன் கூறுகிறான்:\n\r\n\n\r\nوَمَا مِن دَآبَّةٍ فِي الْأَرْضِ إِلاَّ عَلَى اللَّهِ رِزْقُهَا وَيَعْلَمُ مُسْتَقَرَّهَا وَمُسْتَوْدَعَهَا كُلٌّ فِى كِتَابٍ مُّبِينٍ\n\r\n\"பூமியில் ஊர்ந்து செல்லும் எந்த உயிரினமானாலும், அதன் வாழ்வாதாரம் அல்லாஹ்வின் மீதே பொறுப்பாக உள்ளது. மேலும் அதன் வசிப்பிடத்தையும் அது ஒப்படைக்கப்படும் இடத்தையும் (பிறப்புக்கு முன்பும் மரணத்திற்குப் பின்பும்) அவன் அறிவான். இவை அனைத்தும் ஒரு தெளிவான பதிவேட்டில் உள்ளன.\" (11:6)"},"20":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=23\" class=\"link\">47:23</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:23 ஐ பார்க்கவும்"},"21":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=23\" class=\"link\">47:23</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:23 ஐ பார்க்கவும்"},"22":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=23\" class=\"link\">47:23</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:23 ஐ பார்க்கவும்"},"23":{"html":"<strong>ஜிஹாத் பற்றிய கட்டளை வஹீ (இறைச்செய்தி) அருளப்பட்டபோது உண்மையான நம்பிக்கையாளர்கள் மற்றும் உள்ளத்தில் நோய் உள்ளவர்களின் நிலை</strong><br />\r\n<br />\r\nஜிஹாத் சட்டமாக்கப்பட வேண்டும் என்று நம்பிக்கையாளர்கள் (முஃமின்கள்) ஆவலோடு எதிர்பார்த்துக் கொண்டிருந்ததாக அல்லாஹ் குறிப்பிடுகிறான். ஆனால் அல்லாஹ் அதை விதியாக்கியபோது, மக்களில் பலர் பின்வாங்கினார்கள். இதை அல்லாஹ் இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَرَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">قِيلَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">كُفُّواْ</span> <span class=\"quran-arabic-font text-success\">أَيْدِيَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَقِيمُواْ</span> <span class=\"quran-arabic-font text-success\">الصَّلَوةَ</span> <span class=\"quran-arabic-font text-success\">وَءَاتُواْ</span> <span class=\"quran-arabic-font text-success\">الزَّكَوةَ</span> <span class=\"quran-arabic-font text-success\">فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">كُتِبَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمُ</span> <span class=\"quran-arabic-font text-success\">الْقِتَالُ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">فَرِيقٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْهُمْ</span> <span class=\"quran-arabic-font text-success\">يَخْشَوْنَ</span> <span class=\"quran-arabic-font text-success\">النَّاسَ</span> <span class=\"quran-arabic-font text-success\">كَخَشْيَةِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">أَشَدَّ</span> <span class=\"quran-arabic-font text-success\">خَشْيَةً</span> <span class=\"quran-arabic-font text-success\">وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">لِمَ</span> <span class=\"quran-arabic-font text-success\">كَتَبْتَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">الْقِتَالَ</span> <span class=\"quran-arabic-font text-success\">لَوْلا</span> <span class=\"quran-arabic-font text-success\">أَخَّرْتَنَا</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">أَجَلٍ</span> <span class=\"quran-arabic-font text-success\">قَرِيبٍ</span> <span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">مَتَاعُ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">قَلِيلٌ</span> <span class=\"quran-arabic-font text-success\">وَالْآخِرَةُ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">لِّمَنِ</span> <span class=\"quran-arabic-font text-success\">اتَّقَى</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تُظْلَمُونَ</span> <span class=\"quran-arabic-font text-success\">فَتِيلاً</span><br />\r\n<br />\r\n(\"(போரிடுவதைத் தவிர்ந்து) உங்கள் கைகளைக் கட்டுப்படுத்திக் கொள்ளுங்கள், தொழுகையை நிலைநிறுத்துங்கள், ஸகாத் கொடுத்து வாருங்கள்\" என்று எவர்களுக்குக் கூறப்பட்டதோ அவர்களை (நபியே!) நீர் பார்க்கவில்லையா? பின்னர் அவர்கள் மீது போர் விதியாக்கப்பட்டபோது, அவர்களில் ஒரு பிரிவினர் அல்லாஹ்வுக்குப் பயப்படுவதைப் போன்றோ அல்லது அதைவிட அதிகமாகவோ மக்களுக்குப் பயப்படுகின்றனர். மேலும் அவர்கள், \"எங்கள் இறைவனே! எங்கள் மீது ஏன் போரை விதியாக்கினாய்? எங்களுக்கு இன்னும் சிறிது காலம் அவகாசம் அளித்திருக்கக் கூடாதா?\" என்று கூறினர். (நபியே!) நீர் கூறும்: \"இவ்வுலகத்தின் இன்பம் அற்பமானது. தக்வா (இறையச்சம்) உடையவருக்கு மறுமையே மிகச் சிறந்தது. நீங்கள் பேரீச்சம்பழக் கொட்டையிலுள்ள மெல்லிய நூல் அளவு கூட அநியாயம் செய்யப்பட மாட்டீர்கள்.\") (<a href=\"qurandisp.php?sura=4&ayah=77\" class=\"link\">4:77</a>). இதைப் போலவே அல்லாஹ் இங்கும் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَقُولُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">لَوْلاَ</span> <span class=\"quran-arabic-font text-success\">نُزِّلَتْ</span> <span class=\"quran-arabic-font text-success\">سُورَةٌ</span><br />\r\n<br />\r\n(நம்பிக்கையாளர்கள், \"ஒரு சூரா ஏன் அருளப்படவில்லை?\" என்று கூறுகிறார்கள்.) அதாவது, போரிடுவதற்கான கட்டளையைக் கொண்ட ஒரு சூரா. பின்னர் அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِذَآ</span> <span class=\"quran-arabic-font text-success\">أُنزِلَتْ</span> <span class=\"quran-arabic-font text-success\">سُورَةٌ</span> <span class=\"quran-arabic-font text-success\">مُّحْكَمَةٌ</span> <span class=\"quran-arabic-font text-success\">وَذُكِرَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">الْقِتَالُ</span> <span class=\"quran-arabic-font text-success\">رَأَيْتَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">قُلُوبِهِمْ</span> <span class=\"quran-arabic-font text-success\">مَّرَضٌ</span> <span class=\"quran-arabic-font text-success\">يَنظُرُونَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكَ</span> <span class=\"quran-arabic-font text-success\">نَظَرَ</span> <span class=\"quran-arabic-font text-success\">الْمَغْشِىِّ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمَوْتِ</span><br />\r\n<br />\r\n(ஆனால், போரைப் பற்றிக் குறிப்பிடும் தெளிவான ஒரு சூரா அருளப்பட்டால், எவர்களுடைய உள்ளங்களில் நோய் (நயவஞ்சகம்) இருக்கிறதோ அவர்கள், மரண பயத்தால் மயக்கமுற்றவன் பார்ப்பது போல் உம்மைப் பார்ப்பதை நீர் காண்பீர்.) அதாவது, எதிரிகளைச் சந்திப்பதில் உள்ள பயம், திகில் மற்றும் கோழைத்தனம் காரணமாக அவர்கள் அவ்வாறு பார்க்கிறார்கள். பின்னர் அல்லாஹ் அவர்களை ஊக்குவிக்கும் விதமாக இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَوْلَى</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">طَاعَةٌ</span> <span class=\"quran-arabic-font text-success\">وَقَوْلٌ</span> <span class=\"quran-arabic-font text-success\">مَّعْرُوفٌ</span><br />\r\n<br />\r\n(ஆனால் அவர்களுக்குக் கீழ்ப்படிதலும், நன்மையான சொல்லுமே சிறந்ததாக இருந்திருக்கும்.) அதாவது, அந்தச் சூழ்நிலையில் அவர்கள் செவியேற்று கீழ்ப்படிந்திருந்தால் அதுவே அவர்களுக்கு நலமாக இருந்திருக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">عَزَمَ</span> <span class=\"quran-arabic-font text-success\">الْأَمْرُ</span><br />\r\n<br />\r\n(போர் குறித்த விஷயம் உறுதி செய்யப்பட்டால்,) அதாவது, நிலைமை தீவிரமாகி, போருக்கான நேரம் உண்மையாகவே வந்துவிடும்போது,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلَوْ</span> <span class=\"quran-arabic-font text-success\">صَدَقُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span><br />\r\n<br />\r\n(அவர்கள் அல்லாஹ்விடம் உண்மையாக இருந்திருந்தால்,) அதாவது, தங்கள் எண்ணங்களை அவனுக்காகத் தூய்மையாக்கிக் கொண்டு உண்மையாக நடந்திருந்தால்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَكَانَ</span> <span class=\"quran-arabic-font text-success\">خَيْراً</span> <span class=\"quran-arabic-font text-success\">لَّهُمْ</span><br />\r\n<br />\r\n(அது அவர்களுக்கு மிகச் சிறந்ததாக இருந்திருக்கும்.) பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَهَلْ</span> <span class=\"quran-arabic-font text-success\">عَسَيْتُمْ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">تَوَلَّيْتُمْ</span><br />\r\n<br />\r\n(நீங்கள் ஒருவேளை (ஜிஹாதை விட்டும்) புறக்கணித்துத் திரும்பிவிட்டால்,) அதாவது, ஜிஹாதிலிருந்து நீங்கள் பின்வாங்கிக் கொண்டால்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تُفْسِدُواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَتُقَطِّعُواْ</span> <span class=\"quran-arabic-font text-success\">أَرْحَامَكُمْ</span><br />\r\n<br />\r\n(பூமியில் குழப்பத்தை உண்டாக்கவும், உங்கள் இரத்த உறவுகளைத் துண்டிக்கவும் முற்படுவீர்களோ?) அதாவது, அறியாமைக் காலத்தின் பழைய பழக்கவழக்கங்களான இரத்தம் சிந்துவதற்கும், இரத்த உறவுகளைத் துண்டிப்பதற்கும் நீங்கள் மீண்டும் திரும்புவீர்களோ? பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">لَعَنَهُمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">فَأَصَمَّهُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَعْمَى</span> <span class=\"quran-arabic-font text-success\">أَبْصَارَهُمْ</span><br />\r\n<br />\r\n(இத்தகையோரைத்தான் அல்லாஹ் சபிக்கிறான்; அவர்களைச் செவிடாக்கி, அவர்களின் பார்வைகளையும் குருடாக்கிவிட்டான்.) இது பூமியில் குழப்பம் விளைவிப்பதற்கான பொதுவான தடையையும், இரத்த உறவுகளைத் துண்டிப்பதற்கான ஒரு குறிப்பிட்ட தடையையும் உள்ளடக்கியுள்ளது. உண்மையில், பூமியில் நன்மையை நிலைநாட்டுமாறும், உறவினர்களிடம் பேச்சாலும், செயலாலும், செல்வத்தைச் செலவிடுவதாலும் கனிவாக நடந்து உறவைப் பேணுமாறும் அல்லாஹ் மக்களுக்குக் கட்டளையிட்டுள்ளான். இது தொடர்பாக அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடமிருந்து ஏராளமான ஸஹீஹான (ஆதாரப்பூர்வமான) ஹதீஸ்கள் பல்வேறு அறிவிப்பாளர் தொடர்கள் வழியாக வந்துள்ளன.<br />\r\n<br />\r\nஅபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n«<span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">الْخَلْقَ</span> <span class=\"quran-arabic-font text-success\">فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">فَرَغَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">قَامَتِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِمُ</span> <span class=\"quran-arabic-font text-success\">فَأَخَذَتْ</span> <span class=\"quran-arabic-font text-success\">بِحَقْوِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمنِ</span> <span class=\"quran-arabic-font text-success\">عَزَّ</span> <span class=\"quran-arabic-font text-success\">وَجَلَّ</span> <span class=\"quran-arabic-font text-success\">فَقَالَ</span>: <span class=\"quran-arabic-font text-success\">مَهْ،</span> <span class=\"quran-arabic-font text-success\">فَقَالَتْ</span>: <span class=\"quran-arabic-font text-success\">هذَا</span> <span class=\"quran-arabic-font text-success\">مَقَامُ</span> <span class=\"quran-arabic-font text-success\">الْعَائِذِ</span> <span class=\"quran-arabic-font text-success\">بِكَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْقَطِيعَةِ،</span> <span class=\"quran-arabic-font text-success\">فَقَالَ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span>: <span class=\"quran-arabic-font text-success\">أَلَا</span> <span class=\"quran-arabic-font text-success\">تَرْضَيْنَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">أَصِلَ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">وَصَلَكِ</span> <span class=\"quran-arabic-font text-success\">وَأَقْطَعَ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">قَطَعَكِ؟</span> <span class=\"quran-arabic-font text-success\">قَالَتْ</span>: <span class=\"quran-arabic-font text-success\">بَلَى،</span> <span class=\"quran-arabic-font text-success\">قَالَ</span>: <span class=\"quran-arabic-font text-success\">فَذَاكِ</span> <span class=\"quran-arabic-font text-success\">لَك</span>»<br />\r\n(அல்லாஹ் படைப்புகளைப் படைத்து முடித்தபோது, கருப்பையானது (உறவின் சின்னம்) எழுந்து நின்று அளவற்ற அருளாளனின் திருவாடையைப் பற்றிக்கொண்டது. அவன், \"நிறுத்து!\" என்று கூறினான். அதற்கு அது, \"உறவுகளைத் துண்டிப்பதிலிருந்து உன்னிடம் தஞ்சம் கோருபவனின் நிலையாகும் இது\" என்று கூறியது. அல்லாஹ், \"உன்னைச் சேர்த்து நடப்பவரை நானும் சேர்த்துக்கொள்வேன், உன்னைத் துண்டிப்பவரை நானும் துண்டிப்பேன் என்பது உனக்குத் திருப்தியளிக்கவில்லையா?\" என்று கேட்டான். அதற்கு அது, \"ஆம் இறைவா, திருப்தியே!\" என்று கூறியது. அவன், \"அது உனக்கு வழங்கப்பட்டுவிட்டது!\" என்று கூறினான்.) பின்னர் அபூ ஹுரைரா (ரழி) அவர்கள், \"நீங்கள் விரும்பினால் இந்த வசனத்தை ஓதிக்கொள்ளுங்கள்\" என்று கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَهَلْ</span> <span class=\"quran-arabic-font text-success\">عَسَيْتُمْ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">تَوَلَّيْتُمْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تُفْسِدُواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَتُقَطِّعُواْ</span> <span class=\"quran-arabic-font text-success\">أَرْحَامَكُمْ</span><br />\r\n<br />\r\n(நீங்கள் ஒருவேளை புறக்கணித்துத் திரும்பிவிட்டால் பூமியில் குழப்பத்தை உண்டாக்கவும், உங்கள் இரத்த உறவுகளைத் துண்டிக்கவும் முற்படுவீர்களோ?) (புகாரி). மற்றுமொரு அறிவிப்பில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اقْرَءُوا</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">شِئْتُمْ</span><br />\r\n<span class=\"quran-arabic-font text-success\">فَهَلْ</span> <span class=\"quran-arabic-font text-success\">عَسَيْتُمْ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">تَوَلَّيْتُمْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تُفْسِدُواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَتُقَطِّعُواْ</span> <span class=\"quran-arabic-font text-success\">أَرْحَامَكُمْ</span> »<br />\r\n<br />\r\n(நீங்கள் விரும்பினால் ஓதுங்கள்: நீங்கள் ஒருவேளை புறக்கணித்துத் திரும்பிவிட்டால் பூமியில் குழப்பத்தை உண்டாக்கவும், உங்கள் இரத்த உறவுகளைத் துண்டிக்கவும் முற்படுவீர்களோ?) (முஸ்லிம்).<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் அபூ பக்ரா (ரழி) வழியாகப் பதிவு செய்துள்ள ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n«<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">ذَنْبٍ</span> <span class=\"quran-arabic-font text-success\">أَحْرَى</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يُعَجِّلَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">عُقُوبَتَهُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا،</span> <span class=\"quran-arabic-font text-success\">مَعَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَدَّخِرُ</span> <span class=\"quran-arabic-font text-success\">لِصَاحِبِهِ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْاخِرَةِ،</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْبَغْيِ</span> <span class=\"quran-arabic-font text-success\">وَقَطِيعَةِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِم</span>»<br />\r\n(அநீதி இழைப்பதையும், இரத்த உறவுகளைத் துண்டிப்பதையும் விட, மறுமையில் அதற்கான தண்டனையை அல்லாஹ் சேமித்து வைத்திருப்பதோடு, இம்மையிலும் தண்டனையை விரைவுபடுத்துவதற்கு தகுதியான வேறெந்தப் பாவமும் இல்லை.) (அபூ தாவூத், திர்மிதி, இப்னு மாஜா. திர்மிதி: இது ஸஹீஹான ஹதீஸ்).<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் ஸவ்பான் (ரழி) வழியாகப் பதிவு செய்துள்ள ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n«<span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">سَرَّهُ</span> <span class=\"quran-arabic-font text-success\">النَّسَأُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَجَلِ</span> <span class=\"quran-arabic-font text-success\">وَالزِّيَادَةُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الرِّزْقِ،</span> <span class=\"quran-arabic-font text-success\">فَلْيَصِلْ</span> <span class=\"quran-arabic-font text-success\">رَحِمَه</span>»<br />\r\n(யார் தனது ஆயுள் நீட்டிக்கப்படுவதையும், வாழ்வாதாரம் அதிகரிக்கப்படுவதையும் விரும்புகிறாரோ, அவர் தனது இரத்த உறவுகளைப் பேணி வாழட்டும்.)<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் அம்ர் (ரழி) வழியாகப் பதிவு செய்துள்ள ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الرَّحِمَ</span> <span class=\"quran-arabic-font text-success\">مُعَلَّقَةٌ</span> <span class=\"quran-arabic-font text-success\">بِالْعَرْشِ،</span> <span class=\"quran-arabic-font text-success\">وَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">الْوَاصِلُ</span> <span class=\"quran-arabic-font text-success\">بِالْمُكَافِىءِ،</span> <span class=\"quran-arabic-font text-success\">وَلكِنِ</span> <span class=\"quran-arabic-font text-success\">الْوَاصِلُ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">قُطِعَتْ</span> <span class=\"quran-arabic-font text-success\">رَحِمُهُ</span> <span class=\"quran-arabic-font text-success\">وَصَلَهَا</span>»<br />\r\n(நிச்சயமாக கருப்பையானது (இரத்த உறவு) அர்ஷுடன் தொங்கவிடப்பட்டுள்ளது. உறவைப் பேணுபவர் என்பவர் சமமாகப் பிரதிபலன் பார்ப்பவர் அல்ல. மாறாக, உறவு துண்டிக்கப்படும்போது அதைச் சேர்த்து வைப்பவரே உண்மையான உறவைப் பேணுபவர் ஆவார்.) (புகாரி).<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் அம்ர் (ரழி) வழியாகப் பதிவு செய்துள்ள மற்றுமொரு ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n«<span class=\"quran-arabic-font text-success\">تُوضَعُ</span> <span class=\"quran-arabic-font text-success\">الرَّحِمُ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> (<span class=\"quran-arabic-font text-success\">حُجْنَةٌ</span> <span class=\"quran-arabic-font text-success\">كَحُجْنَةِ</span>) <span class=\"quran-arabic-font text-success\">الْمِغْزَلِ</span> <span class=\"quran-arabic-font text-success\">تَكَلَّمُ</span> <span class=\"quran-arabic-font text-success\">بِلِسَانٍ</span> <span class=\"quran-arabic-font text-success\">طَلِقٍ</span> <span class=\"quran-arabic-font text-success\">ذَلِقٍ،</span> <span class=\"quran-arabic-font text-success\">فَتَقْطَعُ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">قَطَعَهَا</span> <span class=\"quran-arabic-font text-success\">وَتَصِلُ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">وَصَلَهَا</span>»<br />\r\n(மறுமை நாளில் கருப்பையானது ஒரு நூற்புச் சக்கரத்தின் வளைந்த கொக்கியைப் போன்று வைக்கப்படும். அது மிகத் தெளிவாகப் பேசும் நாவன்மையுடன், தன்னைத் துண்டித்தவனைத் துண்டிக்குமாறும், தன்னைச் சேர்த்துக்கொண்டவனைச் சேர்த்துக்கொள்ளுமாறும் வேண்டிக்கொள்ளும்.)<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் அம்ர் (ரழி) வழியாகப் பதிவு செய்துள்ள ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n«<span class=\"quran-arabic-font text-success\">الرَّاحِمُونَ</span> <span class=\"quran-arabic-font text-success\">يَرْحَمُهُمُ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمنُ،</span> <span class=\"quran-arabic-font text-success\">ارْحَمُوا</span> <span class=\"quran-arabic-font text-success\">أَهْلَ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">يَرْحَمْكُمْ</span> <span class=\"quran-arabic-font text-success\">أَهْلُ</span> <span class=\"quran-arabic-font text-success\">السَّمَاءِ،</span> <span class=\"quran-arabic-font text-success\">وَالرَّحِمُ</span> <span class=\"quran-arabic-font text-success\">شُجْنَةٌ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمنِ،</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">وَصَلَهَا</span> <span class=\"quran-arabic-font text-success\">وَصَلَتْهُ</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">قَطَعَهَا</span> <span class=\"quran-arabic-font text-success\">بَتَّتْه</span>»<br />\r\n(இரக்கம் காட்டுபவர்கள் மீது அளவற்ற அருளாளன் இரக்கம் காட்டுகிறான். பூமியில் உள்ளவர்கள் மீது இரக்கம் காட்டுங்கள், வானத்தில் இருப்பவன் உங்கள் மீது இரக்கம் காட்டுவான். 'அர்-ரஹீம்' (கருப்பை/உறவு) என்பது 'அர்-ரஹ்மான்' என்ற பெயரிலிருந்து வந்த ஒரு கிளையாகும். யார் அதைச் சேர்த்துக்கொள்கிறாரோ, அல்லாஹ்வும் அவரைச் சேர்த்துக்கொள்வான். யார் அதைத் துண்டிக்கிறாரோ, அல்லாஹ்வும் அவரைத் துண்டித்துவிடுவான்.) (அபூ தாவூத், திர்மிதி. திர்மிதி: ஹஸன் ஸஹீஹ்). இது தொடர்பாக இன்னும் ஏராளமான ஹதீஸ்கள் உள்ளன.<br />\r\n<br />","text":"ஜிஹாத் பற்றிய கட்டளை வஹீ (இறைச்செய்தி) அருளப்பட்டபோது உண்மையான நம்பிக்கையாளர்கள் மற்றும் உள்ளத்தில் நோய் உள்ளவர்களின் நிலை\n\r\n\n\r\nஜிஹாத் சட்டமாக்கப்பட வேண்டும் என்று நம்பிக்கையாளர்கள் (முஃமின்கள்) ஆவலோடு எதிர்பார்த்துக் கொண்டிருந்ததாக அல்லாஹ் குறிப்பிடுகிறான். ஆனால் அல்லாஹ் அதை விதியாக்கியபோது, மக்களில் பலர் பின்வாங்கினார்கள். இதை அல்லாஹ் இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nأَلَمْ تَرَ إِلَى الَّذِينَ قِيلَ لَهُمْ كُفُّواْ أَيْدِيَكُمْ وَأَقِيمُواْ الصَّلَوةَ وَءَاتُواْ الزَّكَوةَ فَلَمَّا كُتِبَ عَلَيْهِمُ الْقِتَالُ إِذَا فَرِيقٌ مِّنْهُمْ يَخْشَوْنَ النَّاسَ كَخَشْيَةِ اللَّهِ أَوْ أَشَدَّ خَشْيَةً وَقَالُواْ رَبَّنَا لِمَ كَتَبْتَ عَلَيْنَا الْقِتَالَ لَوْلا أَخَّرْتَنَا إِلَى أَجَلٍ قَرِيبٍ قُلْ مَتَاعُ الدُّنْيَا قَلِيلٌ وَالْآخِرَةُ خَيْرٌ لِّمَنِ اتَّقَى وَلاَ تُظْلَمُونَ فَتِيلاً\n\r\n\n\r\n(\"(போரிடுவதைத் தவிர்ந்து) உங்கள் கைகளைக் கட்டுப்படுத்திக் கொள்ளுங்கள், தொழுகையை நிலைநிறுத்துங்கள், ஸகாத் கொடுத்து வாருங்கள்\" என்று எவர்களுக்குக் கூறப்பட்டதோ அவர்களை (நபியே!) நீர் பார்க்கவில்லையா? பின்னர் அவர்கள் மீது போர் விதியாக்கப்பட்டபோது, அவர்களில் ஒரு பிரிவினர் அல்லாஹ்வுக்குப் பயப்படுவதைப் போன்றோ அல்லது அதைவிட அதிகமாகவோ மக்களுக்குப் பயப்படுகின்றனர். மேலும் அவர்கள், \"எங்கள் இறைவனே! எங்கள் மீது ஏன் போரை விதியாக்கினாய்? எங்களுக்கு இன்னும் சிறிது காலம் அவகாசம் அளித்திருக்கக் கூடாதா?\" என்று கூறினர். (நபியே!) நீர் கூறும்: \"இவ்வுலகத்தின் இன்பம் அற்பமானது. தக்வா (இறையச்சம்) உடையவருக்கு மறுமையே மிகச் சிறந்தது. நீங்கள் பேரீச்சம்பழக் கொட்டையிலுள்ள மெல்லிய நூல் அளவு கூட அநியாயம் செய்யப்பட மாட்டீர்கள்.\") (4:77). இதைப் போலவே அல்லாஹ் இங்கும் கூறுகிறான்:\n\r\n\n\r\nوَيَقُولُ الَّذِينَ ءَامَنُواْ لَوْلاَ نُزِّلَتْ سُورَةٌ\n\r\n\n\r\n(நம்பிக்கையாளர்கள், \"ஒரு சூரா ஏன் அருளப்படவில்லை?\" என்று கூறுகிறார்கள்.) அதாவது, போரிடுவதற்கான கட்டளையைக் கொண்ட ஒரு சூரா. பின்னர் அவன் கூறுகிறான்:\n\r\n\n\r\nفَإِذَآ أُنزِلَتْ سُورَةٌ مُّحْكَمَةٌ وَذُكِرَ فِيهَا الْقِتَالُ رَأَيْتَ الَّذِينَ فِى قُلُوبِهِمْ مَّرَضٌ يَنظُرُونَ إِلَيْكَ نَظَرَ الْمَغْشِىِّ عَلَيْهِ مِنَ الْمَوْتِ\n\r\n\n\r\n(ஆனால், போரைப் பற்றிக் குறிப்பிடும் தெளிவான ஒரு சூரா அருளப்பட்டால், எவர்களுடைய உள்ளங்களில் நோய் (நயவஞ்சகம்) இருக்கிறதோ அவர்கள், மரண பயத்தால் மயக்கமுற்றவன் பார்ப்பது போல் உம்மைப் பார்ப்பதை நீர் காண்பீர்.) அதாவது, எதிரிகளைச் சந்திப்பதில் உள்ள பயம், திகில் மற்றும் கோழைத்தனம் காரணமாக அவர்கள் அவ்வாறு பார்க்கிறார்கள். பின்னர் அல்லாஹ் அவர்களை ஊக்குவிக்கும் விதமாக இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nفَأَوْلَى لَهُمْ طَاعَةٌ وَقَوْلٌ مَّعْرُوفٌ\n\r\n\n\r\n(ஆனால் அவர்களுக்குக் கீழ்ப்படிதலும், நன்மையான சொல்லுமே சிறந்ததாக இருந்திருக்கும்.) அதாவது, அந்தச் சூழ்நிலையில் அவர்கள் செவியேற்று கீழ்ப்படிந்திருந்தால் அதுவே அவர்களுக்கு நலமாக இருந்திருக்கும்.\n\r\n\n\r\nفَإِذَا عَزَمَ الْأَمْرُ\n\r\n\n\r\n(போர் குறித்த விஷயம் உறுதி செய்யப்பட்டால்,) அதாவது, நிலைமை தீவிரமாகி, போருக்கான நேரம் உண்மையாகவே வந்துவிடும்போது,\n\r\n\n\r\nفَلَوْ صَدَقُواْ اللَّهَ\n\r\n\n\r\n(அவர்கள் அல்லாஹ்விடம் உண்மையாக இருந்திருந்தால்,) அதாவது, தங்கள் எண்ணங்களை அவனுக்காகத் தூய்மையாக்கிக் கொண்டு உண்மையாக நடந்திருந்தால்,\n\r\n\n\r\nلَكَانَ خَيْراً لَّهُمْ\n\r\n\n\r\n(அது அவர்களுக்கு மிகச் சிறந்ததாக இருந்திருக்கும்.) பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَهَلْ عَسَيْتُمْ إِن تَوَلَّيْتُمْ\n\r\n\n\r\n(நீங்கள் ஒருவேளை (ஜிஹாதை விட்டும்) புறக்கணித்துத் திரும்பிவிட்டால்,) அதாவது, ஜிஹாதிலிருந்து நீங்கள் பின்வாங்கிக் கொண்டால்,\n\r\n\n\r\nأَن تُفْسِدُواْ فِى الْأَرْضِ وَتُقَطِّعُواْ أَرْحَامَكُمْ\n\r\n\n\r\n(பூமியில் குழப்பத்தை உண்டாக்கவும், உங்கள் இரத்த உறவுகளைத் துண்டிக்கவும் முற்படுவீர்களோ?) அதாவது, அறியாமைக் காலத்தின் பழைய பழக்கவழக்கங்களான இரத்தம் சிந்துவதற்கும், இரத்த உறவுகளைத் துண்டிப்பதற்கும் நீங்கள் மீண்டும் திரும்புவீர்களோ? பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأَوْلَـئِكَ الَّذِينَ لَعَنَهُمُ اللَّهُ فَأَصَمَّهُمْ وَأَعْمَى أَبْصَارَهُمْ\n\r\n\n\r\n(இத்தகையோரைத்தான் அல்லாஹ் சபிக்கிறான்; அவர்களைச் செவிடாக்கி, அவர்களின் பார்வைகளையும் குருடாக்கிவிட்டான்.) இது பூமியில் குழப்பம் விளைவிப்பதற்கான பொதுவான தடையையும், இரத்த உறவுகளைத் துண்டிப்பதற்கான ஒரு குறிப்பிட்ட தடையையும் உள்ளடக்கியுள்ளது. உண்மையில், பூமியில் நன்மையை நிலைநாட்டுமாறும், உறவினர்களிடம் பேச்சாலும், செயலாலும், செல்வத்தைச் செலவிடுவதாலும் கனிவாக நடந்து உறவைப் பேணுமாறும் அல்லாஹ் மக்களுக்குக் கட்டளையிட்டுள்ளான். இது தொடர்பாக அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடமிருந்து ஏராளமான ஸஹீஹான (ஆதாரப்பூர்வமான) ஹதீஸ்கள் பல்வேறு அறிவிப்பாளர் தொடர்கள் வழியாக வந்துள்ளன.\n\r\n\n\r\nஅபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n«خَلَقَ اللهُ تَعَالَى الْخَلْقَ فَلَمَّا فَرَغَ مِنْهُ قَامَتِ الرَّحِمُ فَأَخَذَتْ بِحَقْوِ الرَّحْمنِ عَزَّ وَجَلَّ فَقَالَ: مَهْ، فَقَالَتْ: هذَا مَقَامُ الْعَائِذِ بِكَ مِنَ الْقَطِيعَةِ، فَقَالَ تَعَالَى: أَلَا تَرْضَيْنَ أَنْ أَصِلَ مَنْ وَصَلَكِ وَأَقْطَعَ مَنْ قَطَعَكِ؟ قَالَتْ: بَلَى، قَالَ: فَذَاكِ لَك»\n\r\n(அல்லாஹ் படைப்புகளைப் படைத்து முடித்தபோது, கருப்பையானது (உறவின் சின்னம்) எழுந்து நின்று அளவற்ற அருளாளனின் திருவாடையைப் பற்றிக்கொண்டது. அவன், \"நிறுத்து!\" என்று கூறினான். அதற்கு அது, \"உறவுகளைத் துண்டிப்பதிலிருந்து உன்னிடம் தஞ்சம் கோருபவனின் நிலையாகும் இது\" என்று கூறியது. அல்லாஹ், \"உன்னைச் சேர்த்து நடப்பவரை நானும் சேர்த்துக்கொள்வேன், உன்னைத் துண்டிப்பவரை நானும் துண்டிப்பேன் என்பது உனக்குத் திருப்தியளிக்கவில்லையா?\" என்று கேட்டான். அதற்கு அது, \"ஆம் இறைவா, திருப்தியே!\" என்று கூறியது. அவன், \"அது உனக்கு வழங்கப்பட்டுவிட்டது!\" என்று கூறினான்.) பின்னர் அபூ ஹுரைரா (ரழி) அவர்கள், \"நீங்கள் விரும்பினால் இந்த வசனத்தை ஓதிக்கொள்ளுங்கள்\" என்று கூறினார்கள்:\n\r\n\n\r\nفَهَلْ عَسَيْتُمْ إِن تَوَلَّيْتُمْ أَن تُفْسِدُواْ فِى الْأَرْضِ وَتُقَطِّعُواْ أَرْحَامَكُمْ\n\r\n\n\r\n(நீங்கள் ஒருவேளை புறக்கணித்துத் திரும்பிவிட்டால் பூமியில் குழப்பத்தை உண்டாக்கவும், உங்கள் இரத்த உறவுகளைத் துண்டிக்கவும் முற்படுவீர்களோ?) (புகாரி). மற்றுமொரு அறிவிப்பில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«اقْرَءُوا إِنْ شِئْتُمْ\n\r\nفَهَلْ عَسَيْتُمْ إِن تَوَلَّيْتُمْ أَن تُفْسِدُواْ فِى الْأَرْضِ وَتُقَطِّعُواْ أَرْحَامَكُمْ »\n\r\n\n\r\n(நீங்கள் விரும்பினால் ஓதுங்கள்: நீங்கள் ஒருவேளை புறக்கணித்துத் திரும்பிவிட்டால் பூமியில் குழப்பத்தை உண்டாக்கவும், உங்கள் இரத்த உறவுகளைத் துண்டிக்கவும் முற்படுவீர்களோ?) (முஸ்லிம்).\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் அபூ பக்ரா (ரழி) வழியாகப் பதிவு செய்துள்ள ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n«مَا مِنْ ذَنْبٍ أَحْرَى أَنْ يُعَجِّلَ اللهُ تَعَالَى عُقُوبَتَهُ فِي الدُّنْيَا، مَعَ مَا يَدَّخِرُ لِصَاحِبِهِ فِي الْاخِرَةِ، مِنَ الْبَغْيِ وَقَطِيعَةِ الرَّحِم»\n\r\n(அநீதி இழைப்பதையும், இரத்த உறவுகளைத் துண்டிப்பதையும் விட, மறுமையில் அதற்கான தண்டனையை அல்லாஹ் சேமித்து வைத்திருப்பதோடு, இம்மையிலும் தண்டனையை விரைவுபடுத்துவதற்கு தகுதியான வேறெந்தப் பாவமும் இல்லை.) (அபூ தாவூத், திர்மிதி, இப்னு மாஜா. திர்மிதி: இது ஸஹீஹான ஹதீஸ்).\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் ஸவ்பான் (ரழி) வழியாகப் பதிவு செய்துள்ள ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n«مَنْ سَرَّهُ النَّسَأُ فِي الْأَجَلِ وَالزِّيَادَةُ فِي الرِّزْقِ، فَلْيَصِلْ رَحِمَه»\n\r\n(யார் தனது ஆயுள் நீட்டிக்கப்படுவதையும், வாழ்வாதாரம் அதிகரிக்கப்படுவதையும் விரும்புகிறாரோ, அவர் தனது இரத்த உறவுகளைப் பேணி வாழட்டும்.)\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் அம்ர் (ரழி) வழியாகப் பதிவு செய்துள்ள ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n«إِنَّ الرَّحِمَ مُعَلَّقَةٌ بِالْعَرْشِ، وَلَيْسَ الْوَاصِلُ بِالْمُكَافِىءِ، وَلكِنِ الْوَاصِلُ الَّذِي إِذَا قُطِعَتْ رَحِمُهُ وَصَلَهَا»\n\r\n(நிச்சயமாக கருப்பையானது (இரத்த உறவு) அர்ஷுடன் தொங்கவிடப்பட்டுள்ளது. உறவைப் பேணுபவர் என்பவர் சமமாகப் பிரதிபலன் பார்ப்பவர் அல்ல. மாறாக, உறவு துண்டிக்கப்படும்போது அதைச் சேர்த்து வைப்பவரே உண்மையான உறவைப் பேணுபவர் ஆவார்.) (புகாரி).\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் அம்ர் (ரழி) வழியாகப் பதிவு செய்துள்ள மற்றுமொரு ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n«تُوضَعُ الرَّحِمُ يَوْمَ الْقِيَامَةِ لَهَا (حُجْنَةٌ كَحُجْنَةِ) الْمِغْزَلِ تَكَلَّمُ بِلِسَانٍ طَلِقٍ ذَلِقٍ، فَتَقْطَعُ مَنْ قَطَعَهَا وَتَصِلُ مَنْ وَصَلَهَا»\n\r\n(மறுமை நாளில் கருப்பையானது ஒரு நூற்புச் சக்கரத்தின் வளைந்த கொக்கியைப் போன்று வைக்கப்படும். அது மிகத் தெளிவாகப் பேசும் நாவன்மையுடன், தன்னைத் துண்டித்தவனைத் துண்டிக்குமாறும், தன்னைச் சேர்த்துக்கொண்டவனைச் சேர்த்துக்கொள்ளுமாறும் வேண்டிக்கொள்ளும்.)\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் அம்ர் (ரழி) வழியாகப் பதிவு செய்துள்ள ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n«الرَّاحِمُونَ يَرْحَمُهُمُ الرَّحْمنُ، ارْحَمُوا أَهْلَ الْأَرْضِ يَرْحَمْكُمْ أَهْلُ السَّمَاءِ، وَالرَّحِمُ شُجْنَةٌ مِنَ الرَّحْمنِ، مَنْ وَصَلَهَا وَصَلَتْهُ وَمَنْ قَطَعَهَا بَتَّتْه»\n\r\n(இரக்கம் காட்டுபவர்கள் மீது அளவற்ற அருளாளன் இரக்கம் காட்டுகிறான். பூமியில் உள்ளவர்கள் மீது இரக்கம் காட்டுங்கள், வானத்தில் இருப்பவன் உங்கள் மீது இரக்கம் காட்டுவான். 'அர்-ரஹீம்' (கருப்பை/உறவு) என்பது 'அர்-ரஹ்மான்' என்ற பெயரிலிருந்து வந்த ஒரு கிளையாகும். யார் அதைச் சேர்த்துக்கொள்கிறாரோ, அல்லாஹ்வும் அவரைச் சேர்த்துக்கொள்வான். யார் அதைத் துண்டிக்கிறாரோ, அல்லாஹ்வும் அவரைத் துண்டித்துவிடுவான்.) (அபூ தாவூத், திர்மிதி. திர்மிதி: ஹஸன் ஸஹீஹ்). இது தொடர்பாக இன்னும் ஏராளமான ஹதீஸ்கள் உள்ளன."},"24":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=28\" class=\"link\">47:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:28 ஐ பார்க்கவும்"},"25":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=28\" class=\"link\">47:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:28 ஐ பார்க்கவும்"},"26":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=28\" class=\"link\">47:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:28 ஐ பார்க்கவும்"},"27":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=28\" class=\"link\">47:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:28 ஐ பார்க்கவும்"},"28":{"html":"<strong>குர்ஆனைப் பற்றி சிந்திப்பதற்கான கட்டளை</strong><br />\r\n<br />\r\nமக்களை குர்ஆனைப் பற்றிச் சிந்தித்து ஆராயுமாறு கட்டளையிட்டும், அதை அவர்கள் புறக்கணிப்பதைத் தடுத்தும் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَلاَ</span> <span class=\"quran-arabic-font text-success\">يَتَدَبَّرُونَ</span> <span class=\"quran-arabic-font text-success\">الْقُرْءَانَ</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">قُلُوبٍ</span> <span class=\"quran-arabic-font text-success\">أَقْفَالُهَآ</span><br />\r\n<br />\r\n(அவர்கள் குர்ஆனைச் சிந்தித்துப் பார்க்க வேண்டாமா? அல்லது அவர்களுடைய உள்ளங்களில் பூட்டுகள் இருக்கின்றனவா?) இதன் பொருளாவது, சில உள்ளங்களில் நிச்சயமாகப் பூட்டுகள் உள்ளன; அதன் காரணத்தால் குர்ஆனின் எந்தப் பொருளும் அவற்றைச் சென்றடையாதவாறு அவை இறுக்கமாக மூடப்பட்டுள்ளன. இப்னு ஜரீர் (ரஹ்) அவர்கள், ஹிஷாம் பின் உர்வா வழியாக அவரது தந்தை (ரஹ்) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஒருமுறை இந்த வசனத்தை ஓதினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَلاَ</span> <span class=\"quran-arabic-font text-success\">يَتَدَبَّرُونَ</span> <span class=\"quran-arabic-font text-success\">الْقُرْءَانَ</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">قُلُوبٍ</span> <span class=\"quran-arabic-font text-success\">أَقْفَالُهَآ</span><br />\r\n<br />\r\n(அவர்கள் குர்ஆனைச் சிந்தித்துப் பார்க்க வேண்டாமா? அல்லது அவர்களுடைய உள்ளங்களில் பூட்டுகள் இருக்கின்றனவா?) அப்போது யெமன் நாட்டைச் சேர்ந்த ஒரு இளைஞர், \"நிச்சயமாக, அவற்றின் மீது பூட்டுகள் உள்ளன - அல்லாஹ் அவற்றை முழுமையாகவோ அல்லது சிறிதளவோ திறக்கும் வரை\" என்று கூறினார். அதன் பிறகு, உமர் (ரழி) அவர்கள் அந்த இளைஞரை எப்போதும் விரும்பி வந்தார்கள்; அவர்கள் ஆட்சிப் பொறுப்பேற்கும் வரை அந்த எண்ணத்தைத் தங்களுக்குள்ளேயே வைத்திருந்தார்கள். (ஆட்சிக்கு வந்ததும்) அவரைத் தனது ஆலோசகராகப் பயன்படுத்திக் கொண்டார்கள்.<br />\r\n<br />\r\n<strong>மார்க்கத்திலிருந்து வெளியேறுவதைக் கண்டித்தல்</strong><br />\r\n<br />\r\nபிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ارْتَدُّواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَدْبَـرِهِمْ</span><br />\r\n<br />\r\n(நிச்சயமாக, எவர்கள் (நேர்வழி வந்த பின்) பின்வாங்கிச் சென்றார்களோ) அதாவது, அவர்கள் ஈமானை (விசுவாசத்தை) விட்டு வெளியேறி மீண்டும் இறைமறுப்பிற்குத் திரும்பிவிட்டார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَبَيَّنَ</span> <span class=\"quran-arabic-font text-success\">لَهُمُ</span> <span class=\"quran-arabic-font text-success\">الْهُدَى</span> <span class=\"quran-arabic-font text-success\">الشَّيْطَـنُ</span> <span class=\"quran-arabic-font text-success\">سَوَّلَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span><br />\r\n<br />\r\n(...நேர்வழி அவர்களுக்குத் தெளிவான பிறகு - ஷைத்தான் அவர்களுக்கு (அதை) அழகாகக் காட்டினான்.) அதாவது, ஷைத்தான் அந்தச் செயலை அவர்களுக்கு அழகானதாகச் சித்தரித்தான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَمْلَى</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span><br />\r\n<br />\r\n(மேலும் அவர்களுக்கு வீணான ஆசைகளை ஊட்டினான்.) அதாவது, அவன் அவர்களைத் தூண்டி ஏமாற்றினான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">بِأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">لِلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَرِهُواْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">نَزَّلَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">سَنُطِيعُكُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">بَعْضِ</span> <span class=\"quran-arabic-font text-success\">الْأَمْرِ</span><br />\r\n<br />\r\n(அதற்குக் காரணம், அல்லாஹ் இறக்கியதை வெறுப்பவர்களிடம் அவர்கள், \"நாங்கள் சில விஷயங்களில் உங்களுக்குக் கீழ்ப்படிவோம்\" என்று கூறியதேயாகும்.) இதன் பொருளாவது, அவர்கள் அவர்களுடன் இரகசியமாகச் சதி செய்து, தீய ஆலோசனைகளை வழங்கினார்கள் - இது உள்ளத்தில் மறைத்திருப்பதற்கு மாறாகப் பேசுபவர்களான நயவஞ்சகர்களின் (முனாஃபிக்குகளின்) பொதுவான வழக்கமாகும். இதன் காரணமாக அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">إِسْرَارَهُمْ</span><br />\r\n<br />\r\n(அல்லாஹ் அவர்களுடைய இரகசியங்களை அறிகிறான்.) அவர்கள் எதை மறைத்தாலும், ஒளித்து வைத்தாலும் அல்லாஹ் அதை நன்கு அறிந்திருக்கிறான். இது அவன் கூறுவதைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">يَكْتُبُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يُبَيِّتُونَ</span><br />\r\n<br />\r\n(...மேலும் அவர்கள் இரவில் தீட்டும் சதித்திட்டங்களை அல்லாஹ் பதிவு செய்கிறான்.) (<a href=\"qurandisp.php?sura=4&ayah=81\" class=\"link\">4:81</a>) பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَكَيْفَ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">تَوَفَّتْهُمُ</span> <span class=\"quran-arabic-font text-success\">الْمَلَـئِكَةُ</span> <span class=\"quran-arabic-font text-success\">يَضْرِبُونَ</span> <span class=\"quran-arabic-font text-success\">وُجُوهَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَدْبَـرَهُمْ</span><br />\r\n<br />\r\n(வானவர்கள் அவர்களுடைய முகங்களிலும் முதுகுகளிலும் அடித்து, அவர்களுடைய உயிர்களைக் கைப்பற்றும் போது (அவர்களது நிலை) எப்படியிருக்கும்?) அதாவது, வானவர்கள் உயிரைக் கைப்பற்ற வரும்போது, ஆன்மாக்கள் உடலுடன் ஒட்டிக்கொள்ள, வானவர்கள் அவற்றை வன்முறையாகவும், கடுமையாகவும் அடித்து வெளியேற்றும் போது அவர்களது நிலை என்னவாகும்? இது அல்லாஹ்வின் இந்தக் கூற்றைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">تَرَى</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">يَتَوَفَّى</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">الْمَلَـئِكَةُ</span> <span class=\"quran-arabic-font text-success\">يَضْرِبُونَ</span> <span class=\"quran-arabic-font text-success\">وُجُوهَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَدْبَـرَهُمْ</span><br />\r\n<br />\r\n(நிராகரிப்பாளர்களின் முகங்களிலும் முதுகுகளிலும் அடித்து, வானவர்கள் அவர்களுடைய உயிர்களைக் கைப்பற்றுவதை நீர் காண்பீராயின் (அவர்களின் நிலை எவ்வளவு கொடூரமாக இருக்கும்)!) (<a href=\"qurandisp.php?sura=8&ayah=50\" class=\"link\">8:50</a>) மேலும் அவனது மற்றுமொரு வசனம்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">تَرَى</span> <span class=\"quran-arabic-font text-success\">إِذِ</span> <span class=\"quran-arabic-font text-success\">الظَّـلِمُونَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">غَمَرَاتِ</span> <span class=\"quran-arabic-font text-success\">الْمَوْتِ</span> <span class=\"quran-arabic-font text-success\">وَالْمَلَـئِكَةُ</span> <span class=\"quran-arabic-font text-success\">بَاسِطُواْ</span> <span class=\"quran-arabic-font text-success\">أَيْدِيهِمْ</span><br />\r\n<br />\r\n(அநீதியாளர்கள் மரண வேதனையில் இருக்கும்போது, வானவர்கள் தங்களுடைய கைகளை நீட்டியவாறு (அவர்களை அடிப்பதைக்) காண்பீராயின்!) (<a href=\"qurandisp.php?sura=6&ayah=93\" class=\"link\">6:93</a>). அதாவது, அவர்களை அடிப்பதற்காக.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَخْرِجُواْ</span> <span class=\"quran-arabic-font text-success\">أَنفُسَكُمُ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">تُجْزَوْنَ</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">الْهُونِ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">الْحَقِّ</span> <span class=\"quran-arabic-font text-success\">وَكُنتُمْ</span> <span class=\"quran-arabic-font text-success\">عَنْ</span> <span class=\"quran-arabic-font text-success\">ءَايَـتِهِ</span> <span class=\"quran-arabic-font text-success\">تَسْتَكْبِرُونَ</span><br />\r\n<br />\r\n((வானவர்கள் கூறுவார்கள்:) \"உங்கள் ஆன்மாக்களை வெளியேற்றுங்கள்! நீங்கள் அல்லாஹ்வின் மீது உண்மையல்லாதவற்றைக் கூறி வந்ததாலும், அவனுடைய வசனங்களைப் பெருமையடித்துப் புறக்கணித்ததாலும், இன்று இழிவான வேதனையே உங்களுக்குக் கூலியாகக் கொடுக்கப்படும்.\") (<a href=\"qurandisp.php?sura=6&ayah=93\" class=\"link\">6:93</a>) மேற்கூறியவற்றின் காரணமாக அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">بِأَنَّهُمُ</span> <span class=\"quran-arabic-font text-success\">اتَّبَعُواْ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَسْخَطَ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">وَكَرِهُواْ</span> <span class=\"quran-arabic-font text-success\">رِضْوَانَهُ</span> <span class=\"quran-arabic-font text-success\">فَأَحْبَطَ</span> <span class=\"quran-arabic-font text-success\">أَعْمَـلَهُمْ</span><br />\r\n<br />\r\n(அதற்குக் காரணம், அவர்கள் அல்லாஹ்வுக்குக் கோபமூட்டுவதையே பின்பற்றி, அவனது உவப்பினை (திருப்தியை) வெறுத்தார்கள்; எனவே அல்லாஹ் அவர்களுடைய நற்செயல்களைப் பயனற்றதாக்கிவிட்டான்.)<br />\r\n<br />\r\n<br />\r\n<br />","text":"குர்ஆனைப் பற்றி சிந்திப்பதற்கான கட்டளை\n\r\n\n\r\nமக்களை குர்ஆனைப் பற்றிச் சிந்தித்து ஆராயுமாறு கட்டளையிட்டும், அதை அவர்கள் புறக்கணிப்பதைத் தடுத்தும் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأَفَلاَ يَتَدَبَّرُونَ الْقُرْءَانَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَآ\n\r\n\n\r\n(அவர்கள் குர்ஆனைச் சிந்தித்துப் பார்க்க வேண்டாமா? அல்லது அவர்களுடைய உள்ளங்களில் பூட்டுகள் இருக்கின்றனவா?) இதன் பொருளாவது, சில உள்ளங்களில் நிச்சயமாகப் பூட்டுகள் உள்ளன; அதன் காரணத்தால் குர்ஆனின் எந்தப் பொருளும் அவற்றைச் சென்றடையாதவாறு அவை இறுக்கமாக மூடப்பட்டுள்ளன. இப்னு ஜரீர் (ரஹ்) அவர்கள், ஹிஷாம் பின் உர்வா வழியாக அவரது தந்தை (ரஹ்) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஒருமுறை இந்த வசனத்தை ஓதினார்கள்:\n\r\n\n\r\nأَفَلاَ يَتَدَبَّرُونَ الْقُرْءَانَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَآ\n\r\n\n\r\n(அவர்கள் குர்ஆனைச் சிந்தித்துப் பார்க்க வேண்டாமா? அல்லது அவர்களுடைய உள்ளங்களில் பூட்டுகள் இருக்கின்றனவா?) அப்போது யெமன் நாட்டைச் சேர்ந்த ஒரு இளைஞர், \"நிச்சயமாக, அவற்றின் மீது பூட்டுகள் உள்ளன - அல்லாஹ் அவற்றை முழுமையாகவோ அல்லது சிறிதளவோ திறக்கும் வரை\" என்று கூறினார். அதன் பிறகு, உமர் (ரழி) அவர்கள் அந்த இளைஞரை எப்போதும் விரும்பி வந்தார்கள்; அவர்கள் ஆட்சிப் பொறுப்பேற்கும் வரை அந்த எண்ணத்தைத் தங்களுக்குள்ளேயே வைத்திருந்தார்கள். (ஆட்சிக்கு வந்ததும்) அவரைத் தனது ஆலோசகராகப் பயன்படுத்திக் கொண்டார்கள்.\n\r\n\n\r\nமார்க்கத்திலிருந்து வெளியேறுவதைக் கண்டித்தல்\n\r\n\n\r\nபிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nإِنَّ الَّذِينَ ارْتَدُّواْ عَلَى أَدْبَـرِهِمْ\n\r\n\n\r\n(நிச்சயமாக, எவர்கள் (நேர்வழி வந்த பின்) பின்வாங்கிச் சென்றார்களோ) அதாவது, அவர்கள் ஈமானை (விசுவாசத்தை) விட்டு வெளியேறி மீண்டும் இறைமறுப்பிற்குத் திரும்பிவிட்டார்கள்.\n\r\n\n\r\nمِّن بَعْدِ مَا تَبَيَّنَ لَهُمُ الْهُدَى الشَّيْطَـنُ سَوَّلَ لَهُمْ\n\r\n\n\r\n(...நேர்வழி அவர்களுக்குத் தெளிவான பிறகு - ஷைத்தான் அவர்களுக்கு (அதை) அழகாகக் காட்டினான்.) அதாவது, ஷைத்தான் அந்தச் செயலை அவர்களுக்கு அழகானதாகச் சித்தரித்தான்.\n\r\n\n\r\nوَأَمْلَى لَهُمْ\n\r\n\n\r\n(மேலும் அவர்களுக்கு வீணான ஆசைகளை ஊட்டினான்.) அதாவது, அவன் அவர்களைத் தூண்டி ஏமாற்றினான்.\n\r\n\n\r\nذَلِكَ بِأَنَّهُمْ قَالُواْ لِلَّذِينَ كَرِهُواْ مَا نَزَّلَ اللَّهُ سَنُطِيعُكُمْ فِى بَعْضِ الْأَمْرِ\n\r\n\n\r\n(அதற்குக் காரணம், அல்லாஹ் இறக்கியதை வெறுப்பவர்களிடம் அவர்கள், \"நாங்கள் சில விஷயங்களில் உங்களுக்குக் கீழ்ப்படிவோம்\" என்று கூறியதேயாகும்.) இதன் பொருளாவது, அவர்கள் அவர்களுடன் இரகசியமாகச் சதி செய்து, தீய ஆலோசனைகளை வழங்கினார்கள் - இது உள்ளத்தில் மறைத்திருப்பதற்கு மாறாகப் பேசுபவர்களான நயவஞ்சகர்களின் (முனாஃபிக்குகளின்) பொதுவான வழக்கமாகும். இதன் காரணமாக அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَاللَّهُ يَعْلَمُ إِسْرَارَهُمْ\n\r\n\n\r\n(அல்லாஹ் அவர்களுடைய இரகசியங்களை அறிகிறான்.) அவர்கள் எதை மறைத்தாலும், ஒளித்து வைத்தாலும் அல்லாஹ் அதை நன்கு அறிந்திருக்கிறான். இது அவன் கூறுவதைப் போன்றதாகும்:\n\r\n\n\r\nوَاللَّهُ يَكْتُبُ مَا يُبَيِّتُونَ\n\r\n\n\r\n(...மேலும் அவர்கள் இரவில் தீட்டும் சதித்திட்டங்களை அல்லாஹ் பதிவு செய்கிறான்.) (4:81) பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَكَيْفَ إِذَا تَوَفَّتْهُمُ الْمَلَـئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَـرَهُمْ\n\r\n\n\r\n(வானவர்கள் அவர்களுடைய முகங்களிலும் முதுகுகளிலும் அடித்து, அவர்களுடைய உயிர்களைக் கைப்பற்றும் போது (அவர்களது நிலை) எப்படியிருக்கும்?) அதாவது, வானவர்கள் உயிரைக் கைப்பற்ற வரும்போது, ஆன்மாக்கள் உடலுடன் ஒட்டிக்கொள்ள, வானவர்கள் அவற்றை வன்முறையாகவும், கடுமையாகவும் அடித்து வெளியேற்றும் போது அவர்களது நிலை என்னவாகும்? இது அல்லாஹ்வின் இந்தக் கூற்றைப் போன்றதாகும்:\n\r\n\n\r\nوَلَوْ تَرَى إِذْ يَتَوَفَّى الَّذِينَ كَفَرُواْ الْمَلَـئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَـرَهُمْ\n\r\n\n\r\n(நிராகரிப்பாளர்களின் முகங்களிலும் முதுகுகளிலும் அடித்து, வானவர்கள் அவர்களுடைய உயிர்களைக் கைப்பற்றுவதை நீர் காண்பீராயின் (அவர்களின் நிலை எவ்வளவு கொடூரமாக இருக்கும்)!) (8:50) மேலும் அவனது மற்றுமொரு வசனம்:\n\r\n\n\r\nوَلَوْ تَرَى إِذِ الظَّـلِمُونَ فِى غَمَرَاتِ الْمَوْتِ وَالْمَلَـئِكَةُ بَاسِطُواْ أَيْدِيهِمْ\n\r\n\n\r\n(அநீதியாளர்கள் மரண வேதனையில் இருக்கும்போது, வானவர்கள் தங்களுடைய கைகளை நீட்டியவாறு (அவர்களை அடிப்பதைக்) காண்பீராயின்!) (6:93). அதாவது, அவர்களை அடிப்பதற்காக.\n\r\n\n\r\nأَخْرِجُواْ أَنفُسَكُمُ الْيَوْمَ تُجْزَوْنَ عَذَابَ الْهُونِ بِمَا كُنتُمْ تَقُولُونَ عَلَى اللَّهِ غَيْرَ الْحَقِّ وَكُنتُمْ عَنْ ءَايَـتِهِ تَسْتَكْبِرُونَ\n\r\n\n\r\n((வானவர்கள் கூறுவார்கள்:) \"உங்கள் ஆன்மாக்களை வெளியேற்றுங்கள்! நீங்கள் அல்லாஹ்வின் மீது உண்மையல்லாதவற்றைக் கூறி வந்ததாலும், அவனுடைய வசனங்களைப் பெருமையடித்துப் புறக்கணித்ததாலும், இன்று இழிவான வேதனையே உங்களுக்குக் கூலியாகக் கொடுக்கப்படும்.\") (6:93) மேற்கூறியவற்றின் காரணமாக அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nذَلِكَ بِأَنَّهُمُ اتَّبَعُواْ مَآ أَسْخَطَ اللَّهَ وَكَرِهُواْ رِضْوَانَهُ فَأَحْبَطَ أَعْمَـلَهُمْ\n\r\n\n\r\n(அதற்குக் காரணம், அவர்கள் அல்லாஹ்வுக்குக் கோபமூட்டுவதையே பின்பற்றி, அவனது உவப்பினை (திருப்தியை) வெறுத்தார்கள்; எனவே அல்லாஹ் அவர்களுடைய நற்செயல்களைப் பயனற்றதாக்கிவிட்டான்.)"},"29":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=31\" class=\"link\">47:31</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:31 ஐ பார்க்கவும்"},"30":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=31\" class=\"link\">47:31</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:31 ஐ பார்க்கவும்"},"31":{"html":"<strong>நயவஞ்சகர்களின் மறைக்கப்பட்ட ரகசியங்களை வெளிப்படுத்துதல்; அல்லாஹ் கூறுகிறான்...</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَمْ</span> <span class=\"quran-arabic-font text-success\">حَسِبَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">قُلُوبِهِم</span> <span class=\"quran-arabic-font text-success\">مَّرَضٌ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">لَّن</span> <span class=\"quran-arabic-font text-success\">يُخْرِجَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">أَضْغَانَهُمْ﴿</span><br />\r\n<br />\r\n(தங்கள் உள்ளங்களில் நோய் உள்ளவர்கள், அல்லாஹ் அவர்களின் வஞ்சகங்களை (வெறுப்புகளை) ஒருபோதும் வெளிப்படுத்த மாட்டான் என்று எண்ணுகிறார்களா?) அதாவது, நயவஞ்சகர்கள் தங்களுடைய உண்மை நிலையை அல்லாஹ் தனது முஃமினான அடியார்களுக்கு வெளிப்படுத்த மாட்டான் என்று நினைக்கிறார்களா? ஆம், நிச்சயமாக அவன் அவர்களின் விவகாரங்களை வெளிப்படுத்தி, தெளிவுபடுத்துவான்; அதன் மூலம் நுண்ணறிவு உடையவர்கள் அதைப் புரிந்து கொள்ள முடியும். இது தொடர்பாகவே, அல்லாஹ் சூரா பராஆ (அல்லது அத்-தவ்பா)வை இறக்கினான். அதில் அவன் நயவஞ்சகர்களின் இழிவானச் செயல்களைத் தெளிவுபடுத்தியதுடன், அவர்களின் நயவஞ்சகத்தைச் சுட்டிக்காட்டும் நடைமுறைகளையும் விளக்கினான். இதன் காரணமாகவே, இந்த சூரா (சூரா பராஆ) 'அல்-ஃபாதிஹா' (அம்பலப்படுத்துவது) என்றும் அழைக்கப்படுகிறது. 'அத்ஃகான்' என்பது 'திக்ன்' என்பதன் பன்மையாகும். இதன் பொருள், இஸ்லாத்தின் மீதும் அதை ஆதரிக்கும் மக்கள் மீதும் உள்ளங்கள் கொண்டிருக்கும் பொறாமை மற்றும் வெறுப்பாகும். பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَوْ</span> <span class=\"quran-arabic-font text-success\">نَشَاءُ</span> <span class=\"quran-arabic-font text-success\">لَأَرَيْنَاكَهُمْ</span> <span class=\"quran-arabic-font text-success\">فَلَعَرَفْتَهُم</span> <span class=\"quran-arabic-font text-success\">بِسِيمَاهُمْ﴿</span><br />\r\n<br />\r\n(நாம் நாடியிருந்தால், அவர்களை உமக்கு அடையாளம் காட்டியிருப்போம்; அப்போது நீர் அவர்களின் அடையாளங்களைக் கொண்டே அவர்களைத் தெளிவாக அறிந்து கொண்டிருப்பீர்.) அல்லாஹ் தனது தூதர் (ஸல்) அவர்களிடம் கூறுகிறான்: \"முஹம்மதே (ஸல்)! நாம் நாடியிருந்தால், நயவஞ்சகர்களான குறிப்பிட்ட நபர்களை உமக்கு நாம் அடையாளம் காட்டியிருப்போம், அப்போது நீர் அவர்களைத் தெளிவாக அறிந்து கொண்டிருப்பீர்.\" இருப்பினும், அல்லாஹ் எல்லா நயவஞ்சகர்கள் விஷயத்திலும் அவ்வாறு செய்யவில்லை. அவன் தனது படைப்பினங்களின் குறைகளை மறைக்கிறான்; அவர்களின் விவகாரங்கள் வெளிப்படையான நிலையின் அடிப்படையில் அமைய விடுகிறான்; மேலும் உள்ளத்தின் ரகசியங்களை அவற்றை நன்கு அறிந்தவனிடமே (அல்லாஹ்விடமே) விட்டுவிடுகிறான். பிறகு அல்லாஹ் மேலும் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَتَعْرِفَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">لَحْنِ</span> <span class=\"quran-arabic-font text-success\">الْقَوْلِ﴿</span><br />\r\n<br />\r\n(ஆயினும், பேச்சின் தொனியைக் கொண்டே நீர் அவர்களை நிச்சயமாக அறிந்து கொள்வீர்!) அதாவது, 'அவர்களின் உள்நோக்கத்தை வெளிப்படுத்தும் அவர்களின் பேச்சைக் கொண்டே நீர் அவர்களை அறிந்து கொள்வீர்.' ஒருவர் பேசும் விதமும் அதன் சூழலும் அவரது நிலைப்பாட்டை வெளிப்படுத்திவிடும். இதையே அமீருல் முஃமினீன் உஸ்மான் பின் அஃப்பான் (ரழி) அவர்கள் இவ்வாறு கூறினார்கள்: \"எவரேனும் ஒரு ரகசியத்தை மறைக்க முயன்றால், அல்லாஹ் அதை அவரது முகத் தோற்றத்தின் மூலமாகவோ அல்லது அவரது நாவிலிருந்து வெளிப்படும் தவறுதலான வார்த்தைகளின் மூலமாகவோ வெளிப்படுத்தாமல் விடுவதில்லை.\" மேலும் நபித்தோழர்கள் கூறினார்கள்: \"அலீ பின் அபீதாலிப் (ரழி) அவர்கள் மீது நயவஞ்சகர்கள் கொண்டிருந்த பகையைக் கொண்டே நாங்கள் அவர்களை இனங்கண்டு கொள்வோம்.\" <span class=\"quran-arabic-font text-success\">﴾وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">أَعْمَالَكُمْ﴿</span> (மேலும், அல்லாஹ் உங்கள் செயல்களை நன்கறிவான்.) அதாவது, அல்லாஹ் உங்களின் செயல்களை உங்களுக்கு விவரிப்பான்; அவற்றுக்குரிய கூலியை உங்களுக்கு முழுமையாக வழங்குவான்; உங்கள் செயல்களில் எதுவும் அவனுக்கு மறைந்துவிடுவதில்லை. பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَنَبْلُوَنَّكُمْ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் உங்களைச் சோதிப்போம்) அதாவது, 'கட்டளைகள் மற்றும் விலக்கல்கள் மூலம் நாம் உங்களை நிச்சயமாகச் சோதிப்போம்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾حَتَّى</span> <span class=\"quran-arabic-font text-success\">نَعْلَمَ</span> <span class=\"quran-arabic-font text-success\">الْمُجَاهِدِينَ</span> <span class=\"quran-arabic-font text-success\">مِنكُمْ</span> <span class=\"quran-arabic-font text-success\">وَالصَّابِرِينَ</span> <span class=\"quran-arabic-font text-success\">وَنَبْلُوَ</span> <span class=\"quran-arabic-font text-success\">أَخْبَارَكُمْ﴿</span><br />\r\n<br />\r\n(உங்களில் அறப்போரிடுபவர்களையும் பொறுமையாளர்களையும் நாம் அறியும் வரை (உங்களைச் சோதிப்போம்); மேலும் உங்கள் செய்திகளையும் நாம் சோதிப்போம்.) அனைத்து நிகழ்வுகளும் நடப்பதற்கு முன்னரே அவற்றை அல்லாஹ் அறிந்திருக்கிறான் என்பதில் எவ்வித சந்தேகமும் இல்லை. இந்த வசனத்தில், 'நாம் அறியும் வரை' என்பது, 'அவை நிகழ்வதை நாம் காணும் வரை' என்று பொருள்படும். இதனால்தான் இப்னு அப்பாஸ் (ரழி) அவர்கள் இது போன்ற வசனங்கள் குறித்துக் கூறும்போது, \"'நாம் அறிவதற்காக' என்பதற்கு, 'நாம் காண்பதற்காக' என்று பொருள்\" எனக் குறிப்பிட்டார்கள்.<br />\r\n<br />","text":"நயவஞ்சகர்களின் மறைக்கப்பட்ட ரகசியங்களை வெளிப்படுத்துதல்; அல்லாஹ் கூறுகிறான்...\n\r\n\n\r\n﴾أَمْ حَسِبَ الَّذِينَ فِي قُلُوبِهِم مَّرَضٌ أَن لَّن يُخْرِجَ اللَّهُ أَضْغَانَهُمْ﴿\n\r\n\n\r\n(தங்கள் உள்ளங்களில் நோய் உள்ளவர்கள், அல்லாஹ் அவர்களின் வஞ்சகங்களை (வெறுப்புகளை) ஒருபோதும் வெளிப்படுத்த மாட்டான் என்று எண்ணுகிறார்களா?) அதாவது, நயவஞ்சகர்கள் தங்களுடைய உண்மை நிலையை அல்லாஹ் தனது முஃமினான அடியார்களுக்கு வெளிப்படுத்த மாட்டான் என்று நினைக்கிறார்களா? ஆம், நிச்சயமாக அவன் அவர்களின் விவகாரங்களை வெளிப்படுத்தி, தெளிவுபடுத்துவான்; அதன் மூலம் நுண்ணறிவு உடையவர்கள் அதைப் புரிந்து கொள்ள முடியும். இது தொடர்பாகவே, அல்லாஹ் சூரா பராஆ (அல்லது அத்-தவ்பா)வை இறக்கினான். அதில் அவன் நயவஞ்சகர்களின் இழிவானச் செயல்களைத் தெளிவுபடுத்தியதுடன், அவர்களின் நயவஞ்சகத்தைச் சுட்டிக்காட்டும் நடைமுறைகளையும் விளக்கினான். இதன் காரணமாகவே, இந்த சூரா (சூரா பராஆ) 'அல்-ஃபாதிஹா' (அம்பலப்படுத்துவது) என்றும் அழைக்கப்படுகிறது. 'அத்ஃகான்' என்பது 'திக்ன்' என்பதன் பன்மையாகும். இதன் பொருள், இஸ்லாத்தின் மீதும் அதை ஆதரிக்கும் மக்கள் மீதும் உள்ளங்கள் கொண்டிருக்கும் பொறாமை மற்றும் வெறுப்பாகும். பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾وَلَوْ نَشَاءُ لَأَرَيْنَاكَهُمْ فَلَعَرَفْتَهُم بِسِيمَاهُمْ﴿\n\r\n\n\r\n(நாம் நாடியிருந்தால், அவர்களை உமக்கு அடையாளம் காட்டியிருப்போம்; அப்போது நீர் அவர்களின் அடையாளங்களைக் கொண்டே அவர்களைத் தெளிவாக அறிந்து கொண்டிருப்பீர்.) அல்லாஹ் தனது தூதர் (ஸல்) அவர்களிடம் கூறுகிறான்: \"முஹம்மதே (ஸல்)! நாம் நாடியிருந்தால், நயவஞ்சகர்களான குறிப்பிட்ட நபர்களை உமக்கு நாம் அடையாளம் காட்டியிருப்போம், அப்போது நீர் அவர்களைத் தெளிவாக அறிந்து கொண்டிருப்பீர்.\" இருப்பினும், அல்லாஹ் எல்லா நயவஞ்சகர்கள் விஷயத்திலும் அவ்வாறு செய்யவில்லை. அவன் தனது படைப்பினங்களின் குறைகளை மறைக்கிறான்; அவர்களின் விவகாரங்கள் வெளிப்படையான நிலையின் அடிப்படையில் அமைய விடுகிறான்; மேலும் உள்ளத்தின் ரகசியங்களை அவற்றை நன்கு அறிந்தவனிடமே (அல்லாஹ்விடமே) விட்டுவிடுகிறான். பிறகு அல்லாஹ் மேலும் கூறுகிறான்:\n\r\n\n\r\n﴾وَلَتَعْرِفَنَّهُمْ فِي لَحْنِ الْقَوْلِ﴿\n\r\n\n\r\n(ஆயினும், பேச்சின் தொனியைக் கொண்டே நீர் அவர்களை நிச்சயமாக அறிந்து கொள்வீர்!) அதாவது, 'அவர்களின் உள்நோக்கத்தை வெளிப்படுத்தும் அவர்களின் பேச்சைக் கொண்டே நீர் அவர்களை அறிந்து கொள்வீர்.' ஒருவர் பேசும் விதமும் அதன் சூழலும் அவரது நிலைப்பாட்டை வெளிப்படுத்திவிடும். இதையே அமீருல் முஃமினீன் உஸ்மான் பின் அஃப்பான் (ரழி) அவர்கள் இவ்வாறு கூறினார்கள்: \"எவரேனும் ஒரு ரகசியத்தை மறைக்க முயன்றால், அல்லாஹ் அதை அவரது முகத் தோற்றத்தின் மூலமாகவோ அல்லது அவரது நாவிலிருந்து வெளிப்படும் தவறுதலான வார்த்தைகளின் மூலமாகவோ வெளிப்படுத்தாமல் விடுவதில்லை.\" மேலும் நபித்தோழர்கள் கூறினார்கள்: \"அலீ பின் அபீதாலிப் (ரழி) அவர்கள் மீது நயவஞ்சகர்கள் கொண்டிருந்த பகையைக் கொண்டே நாங்கள் அவர்களை இனங்கண்டு கொள்வோம்.\" ﴾وَاللَّهُ يَعْلَمُ أَعْمَالَكُمْ﴿ (மேலும், அல்லாஹ் உங்கள் செயல்களை நன்கறிவான்.) அதாவது, அல்லாஹ் உங்களின் செயல்களை உங்களுக்கு விவரிப்பான்; அவற்றுக்குரிய கூலியை உங்களுக்கு முழுமையாக வழங்குவான்; உங்கள் செயல்களில் எதுவும் அவனுக்கு மறைந்துவிடுவதில்லை. பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾وَلَنَبْلُوَنَّكُمْ﴿\n\r\n\n\r\n(நிச்சயமாக நாம் உங்களைச் சோதிப்போம்) அதாவது, 'கட்டளைகள் மற்றும் விலக்கல்கள் மூலம் நாம் உங்களை நிச்சயமாகச் சோதிப்போம்.'\n\r\n\n\r\n﴾حَتَّى نَعْلَمَ الْمُجَاهِدِينَ مِنكُمْ وَالصَّابِرِينَ وَنَبْلُوَ أَخْبَارَكُمْ﴿\n\r\n\n\r\n(உங்களில் அறப்போரிடுபவர்களையும் பொறுமையாளர்களையும் நாம் அறியும் வரை (உங்களைச் சோதிப்போம்); மேலும் உங்கள் செய்திகளையும் நாம் சோதிப்போம்.) அனைத்து நிகழ்வுகளும் நடப்பதற்கு முன்னரே அவற்றை அல்லாஹ் அறிந்திருக்கிறான் என்பதில் எவ்வித சந்தேகமும் இல்லை. இந்த வசனத்தில், 'நாம் அறியும் வரை' என்பது, 'அவை நிகழ்வதை நாம் காணும் வரை' என்று பொருள்படும். இதனால்தான் இப்னு அப்பாஸ் (ரழி) அவர்கள் இது போன்ற வசனங்கள் குறித்துக் கூறும்போது, \"'நாம் அறிவதற்காக' என்பதற்கு, 'நாம் காண்பதற்காக' என்று பொருள்\" எனக் குறிப்பிட்டார்கள்."},"32":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=35\" class=\"link\">47:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:35 ஐ பார்க்கவும்"},"33":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=35\" class=\"link\">47:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:35 ஐ பார்க்கவும்"},"34":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=35\" class=\"link\">47:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:35 ஐ பார்க்கவும்"},"35":{"html":"<strong>நிராகரிப்பாளர்களின் செயல்கள் அழிந்து போதல் மற்றும் அல்லாஹ்வுக்கும் அவனது தூதருக்கும் கட்டுப்படுவதற்கான கட்டளை</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">وَصَدُّواْ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَشَآقُّواْ</span> <span class=\"quran-arabic-font text-success\">الرَّسُولَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَبَيَّنَ</span> <span class=\"quran-arabic-font text-success\">لَهُمُ</span> <span class=\"quran-arabic-font text-success\">الْهُدَى</span> <span class=\"quran-arabic-font text-success\">لَن</span> <span class=\"quran-arabic-font text-success\">يَضُرُّواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">شَيْئاً</span> <span class=\"quran-arabic-font text-success\">وَسَيُحْبِطُ</span> <span class=\"quran-arabic-font text-success\">أَعْمَـلَهُمْ</span><br />\r\n<br />\r\n(நிச்சயமாக எவர்கள் நிராகரித்து, அல்லாஹ்வின் பாதையை விட்டும் (மக்களைத்) தடுத்து, தங்களுக்கு நேர்வழி தெளிவான பின்னரும் இத்தூதரை எதிர்த்தார்களோ, அவர்கள் அல்லாஹ்வுக்குச் சிறிதும் தீங்கு இழைக்க முடியாது; மேலும் அவன் இவர்களது செயல்களை அழித்துவிடுவான்.)<br />\r\n<br />\r\nஅல்லாஹ் நிராகரிப்பவர்கள், அல்லாஹ்வின் பாதையை விட்டு (மக்களைத்) தடுப்பவர்கள், தூதரை எதிர்த்து அவருக்குத் தொல்லை கொடுப்பவர்கள் மற்றும் நேர்வழி தெளிவான பின்னரும் மார்க்கத்தை விட்டு வெளியேறியவர்களைப் பற்றிச் சொல்கிறான். இத்தகையவர்கள் அல்லாஹ்வுக்குச் சிறிதும் தீங்கு இழைக்க முடியாது என்றும், மாறாகத் தங்களுக்குத் தாங்களே தீங்கிழைத்துக் கொண்டு மறுமை நாளில் நஷ்டமடைவார்கள் என்றும் அல்லாஹ் குறிப்பிடுகிறான். அவன் அவர்களின் செயல்களை அழித்துவிடுவான். அவர்கள் மார்க்கத்தை விட்டு வெளியேறுவதற்கு முன்னால் செய்த எந்த நற்செயலுக்கும், ஒரு கொசுவின் எடையளவு (மிகச் சிறியது) கூட அல்லாஹ் கூலி வழங்க மாட்டான்; மாறாக அவற்றை முற்றிலும் செல்லாததாக்கி அழித்துவிடுவான். நற்செயல்கள் தீய செயல்களை அழிப்பதைப் போலவே, அவர்களின் இந்த மதமாற்றம் அவர்களது நற்செயல்களை முழுமையாக அழித்துவிடுகிறது. இமாம் அஹ்மத் இப்னு நஸ்ர் அல்-மர்வாஸி (ரஹ்) 'கிதாப் அஸ்-ஸலாஹ்' (தொழுகைப் புத்தகம்) எனும் நூலில் அபூ அல்-ஆலியா (ரஹ்) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வுக்கு இணை வைப்பவர்களுக்கு எந்த நற்செயலும் பலனளிக்காதது போலவே, 'லா இலாஹ இல்லல்லாஹ்' என்று சொல்பவர்களுக்கு எந்தப் பாவமும் தீங்கு செய்யாது என்று நபித்தோழர்கள் (ஸஹாபாக்கள் - ரழி) கருதி வந்தனர். அப்போது அல்லாஹ் பின்வரும் வசனத்தை இறக்கினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَطِيعُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">وَأَطِيعُواْ</span> <span class=\"quran-arabic-font text-success\">الرَّسُولَ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تُبْطِلُواْ</span> <span class=\"quran-arabic-font text-success\">أَعْمَـلَكُمْ</span><br />\r\n<br />\r\n(அல்லாஹ்வுக்குக் கீழ்ப்படியுங்கள், தூதருக்கும் கீழ்ப்படியுங்கள், உங்கள் செயல்களைப் பாழாக்கி விடாதீர்கள்.) சில பாவங்கள் தங்கள் செயல்களை அழித்து விடுமோ என்று அவர்கள் அஞ்சத் தொடங்குவதற்கு இது காரணமாக அமைந்தது.\" இப்னு உமர் (ரழி) அவர்கள் கூறியதாவது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் தோழர்களாகிய நாங்கள், அல்லாஹ் பின்வரும் வசனத்தை இறக்கும் வரை அனைத்து நற்செயல்களும் (நிச்சயம்) ஏற்றுக்கொள்ளப்படும் என்றே கருதி வந்தோம்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَطِيعُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">وَأَطِيعُواْ</span> <span class=\"quran-arabic-font text-success\">الرَّسُولَ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تُبْطِلُواْ</span> <span class=\"quran-arabic-font text-success\">أَعْمَـلَكُمْ</span><br />\r\n<br />\r\n(அல்லாஹ்வுக்குக் கீழ்ப்படியுங்கள், தூதருக்கும் கீழ்ப்படியுங்கள், உங்கள் செயல்களைப் பாழாக்கி விடாதீர்கள்.) எனவே, 'எமது செயல்களை அழித்துவிடக் கூடியது எது?' என்று எங்களுக்குள் ஒருவருக்கொருவர் கேட்டுக் கொண்டோம். 'பெரிய பாவங்கள், நரக நெருப்பைத் தேடித்தரும் மாபெரும் குற்றங்கள் மற்றும் மானக்கேடான செயல்களே அவை' என்று நாங்கள் கூறிக்கொண்டோம். அப்போது அல்லாஹ் பின்வரும் வசனத்தை இறக்கினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَغْفِرُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُشْرَكَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">وَيَغْفِرُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">دُونَ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لِمَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் தனக்கு இணை கற்பிக்கப்படுவதை மன்னிக்க மாட்டான்; அதைத் தவிர மற்றவற்றைத் தான் நாடியவர்களுக்கு மன்னிப்பான்.) (<a href=\"qurandisp.php?sura=4&ayah=48\" class=\"link\">4:48</a>). இந்த வசனம் இறங்கிய பிறகு நாங்கள் அவ்வாறு (உறுதியாகக்) கூறுவதை நிறுத்திக் கொண்டோம். அதன் பிறகு, பெரும் பாவங்கள் மற்றும் மானக்கேடான செயல்களில் ஈடுபட்டவர்களைக் குறித்து அஞ்சினோம்; அதே சமயம் அவ்வாறு செய்யாதவர்கள் விஷயத்தில் (அல்லாஹ்வின் அருளைப் பெற) நம்பிக்கை வைத்தோம்.\"<br />\r\n<br />\r\nபிறகு அல்லாஹ் தன் முஃமினான (நம்பிக்கை கொண்ட) அடியார்களுக்குத் தனக்கும் தன் தூதருக்கும் கீழ்ப்படியுமாறு கட்டளையிடுகிறான். இது அவர்களுக்கு இம்மையிலும் மறுமையிலும் மகிழ்ச்சியைத் தரும். மேலும் மார்க்கத்தை விட்டு வெளியேறுவதையும் (மதமாற்றத்தையும்) அவன் தடை செய்கிறான்; ஏனெனில் அது அவர்களின் செயல்களை அழித்துவிடும். அதனால் அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تُبْطِلُواْ</span> <span class=\"quran-arabic-font text-success\">أَعْمَـلَكُمْ</span><br />\r\n<br />\r\n(உங்கள் செயல்களைப் பாழாக்கி விடாதீர்கள்.) அதாவது மார்க்கத்தை விட்டு வெளியேறுவதன் மூலம் (அவற்றை அழித்து விடாதீர்கள்). அதன்பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">وَصَدُّواْ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">مَاتُواْ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">كُفَّارٌ</span> <span class=\"quran-arabic-font text-success\">فَلَن</span> <span class=\"quran-arabic-font text-success\">يَغْفِرَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span><br />\r\n<br />\r\n(நிச்சயமாக எவர்கள் நிராகரித்து, அல்லாஹ்வின் பாதையை விட்டும் தடுத்து, பிறகு காஃபிர்களாகவே மரணிக்கிறார்களோ, அவர்களை அல்லாஹ் ஒருபோதும் மன்னிக்க மாட்டான்.)<br />\r\n<br />\r\nஇது அவனது இந்த வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَغْفِرُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُشْرَكَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">وَيَغْفِرُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">دُونَ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لِمَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் தனக்கு இணை கற்பிக்கப்படுவதை மன்னிக்க மாட்டான்; அதைத் தவிர மற்றவற்றைத் தான் நாடியவர்களுக்கு மன்னிப்பான்.) (<a href=\"qurandisp.php?sura=4&ayah=48\" class=\"link\">4:48</a>). பிறகு அல்லாஹ் முஃமினான அடியார்களை நோக்கிக் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">تَهِنُواْ</span><br />\r\n<br />\r\n(எனவே நீங்கள் மனம் தளராதீர்கள்.) அதாவது எதிரிகளுக்கு முன்னால் பலவீனமடைந்து விடாதீர்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتَدْعُواْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">السَّلْمِ</span><br />\r\n<br />\r\n(மேலும் சமாதானத்தை வேண்டாதீர்கள்.) அதாவது நீங்கள் அதிக எண்ணிக்கையிலும் போர் ஆயத்தங்களிலும் வலுவாக இருக்கும் நிலையில், நிராகரிப்பாளர்களிடம் பணிந்து போவதையோ அல்லது போரை நிறுத்தச் சொல்லி சமாதானம் கோருவதையோ அல்லாஹ் தடுத்துள்ளான். எனவேதான் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">تَهِنُواْ</span> <span class=\"quran-arabic-font text-success\">وَتَدْعُواْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">السَّلْمِ</span> <span class=\"quran-arabic-font text-success\">وَأَنتُمُ</span> <span class=\"quran-arabic-font text-success\">الْأَعْلَوْنَ</span><br />\r\n<br />\r\n(எனவே நீங்கள் மேலோங்கி இருக்கும் நிலையில், மனம் தளர்ந்து சமாதானத்தை வேண்டாதீர்கள்.) அதாவது உங்கள் எதிரியை விட நீங்கள் மேலான நிலையில் இருக்கும் போது இவ்வாறு செய்யாதீர்கள்.<br />\r\n<br />\r\nமறுபுறம், முஸ்லிம்களை விட நிராகரிப்பாளர்கள் அதிக வலிமையுடனும் எண்ணிக்கையிலும் அதிகமாகவும் இருந்தால், அது முஸ்லிம்களுக்கு நன்மை பயக்கும் என்று இமாம் (தலைவர்) கருதினால், அவர் சமாதான உடன்படிக்கை செய்து கொள்ளலாம். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மக்காவிற்குள் நுழைய விடாமல் நிராகரிப்பாளர்கள் தடுத்தபோது, பத்து ஆண்டுகளுக்குப் போரை நிறுத்துவதற்கான உடன்படிக்கையை அவர்கள் முன்மொழிந்தார்கள்; அதற்கு நபி (ஸல்) அவர்களும் சம்மதித்தார்கள். இது அதைப் போன்றதுதான். பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">مَعَكُمْ</span><br />\r\n<br />\r\n(அல்லாஹ் உங்களுடன் இருக்கிறான்.) இது எதிரிகளுக்கு எதிரான வெற்றியையும் வாகை சூடுதல் பற்றிய நற்செய்தியையும் உள்ளடக்கியுள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَن</span> <span class=\"quran-arabic-font text-success\">يَتِرَكُمْ</span> <span class=\"quran-arabic-font text-success\">أَعْمَـلَكُمْ</span><br />\r\n<br />\r\n(அவன் உங்கள் செயல்களை (அதன் கூலியை) ஒருபோதும் குறைக்க மாட்டான்.) அதாவது அல்லாஹ் உங்கள் செயல்களை ஒருபோதும் செல்லாததாக்க மாட்டான், அவற்றை வீணாக்க மாட்டான் அல்லது அதன் பலனை உங்களுக்குத் தராமல் இருக்க மாட்டான். மாறாக, எவ்விதக் குறைவுமின்றி உங்கள் கூலிகளை அவன் முழுமையாக உங்களுக்கு வழங்குவான்.\" அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />","text":"நிராகரிப்பாளர்களின் செயல்கள் அழிந்து போதல் மற்றும் அல்லாஹ்வுக்கும் அவனது தூதருக்கும் கட்டுப்படுவதற்கான கட்டளை\n\r\n\n\r\nإِنَّ الَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ اللَّهِ وَشَآقُّواْ الرَّسُولَ مِن بَعْدِ مَا تَبَيَّنَ لَهُمُ الْهُدَى لَن يَضُرُّواْ اللَّهَ شَيْئاً وَسَيُحْبِطُ أَعْمَـلَهُمْ\n\r\n\n\r\n(நிச்சயமாக எவர்கள் நிராகரித்து, அல்லாஹ்வின் பாதையை விட்டும் (மக்களைத்) தடுத்து, தங்களுக்கு நேர்வழி தெளிவான பின்னரும் இத்தூதரை எதிர்த்தார்களோ, அவர்கள் அல்லாஹ்வுக்குச் சிறிதும் தீங்கு இழைக்க முடியாது; மேலும் அவன் இவர்களது செயல்களை அழித்துவிடுவான்.)\n\r\n\n\r\nஅல்லாஹ் நிராகரிப்பவர்கள், அல்லாஹ்வின் பாதையை விட்டு (மக்களைத்) தடுப்பவர்கள், தூதரை எதிர்த்து அவருக்குத் தொல்லை கொடுப்பவர்கள் மற்றும் நேர்வழி தெளிவான பின்னரும் மார்க்கத்தை விட்டு வெளியேறியவர்களைப் பற்றிச் சொல்கிறான். இத்தகையவர்கள் அல்லாஹ்வுக்குச் சிறிதும் தீங்கு இழைக்க முடியாது என்றும், மாறாகத் தங்களுக்குத் தாங்களே தீங்கிழைத்துக் கொண்டு மறுமை நாளில் நஷ்டமடைவார்கள் என்றும் அல்லாஹ் குறிப்பிடுகிறான். அவன் அவர்களின் செயல்களை அழித்துவிடுவான். அவர்கள் மார்க்கத்தை விட்டு வெளியேறுவதற்கு முன்னால் செய்த எந்த நற்செயலுக்கும், ஒரு கொசுவின் எடையளவு (மிகச் சிறியது) கூட அல்லாஹ் கூலி வழங்க மாட்டான்; மாறாக அவற்றை முற்றிலும் செல்லாததாக்கி அழித்துவிடுவான். நற்செயல்கள் தீய செயல்களை அழிப்பதைப் போலவே, அவர்களின் இந்த மதமாற்றம் அவர்களது நற்செயல்களை முழுமையாக அழித்துவிடுகிறது. இமாம் அஹ்மத் இப்னு நஸ்ர் அல்-மர்வாஸி (ரஹ்) 'கிதாப் அஸ்-ஸலாஹ்' (தொழுகைப் புத்தகம்) எனும் நூலில் அபூ அல்-ஆலியா (ரஹ்) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வுக்கு இணை வைப்பவர்களுக்கு எந்த நற்செயலும் பலனளிக்காதது போலவே, 'லா இலாஹ இல்லல்லாஹ்' என்று சொல்பவர்களுக்கு எந்தப் பாவமும் தீங்கு செய்யாது என்று நபித்தோழர்கள் (ஸஹாபாக்கள் - ரழி) கருதி வந்தனர். அப்போது அல்லாஹ் பின்வரும் வசனத்தை இறக்கினான்:\n\r\n\n\r\nأَطِيعُواْ اللَّهَ وَأَطِيعُواْ الرَّسُولَ وَلاَ تُبْطِلُواْ أَعْمَـلَكُمْ\n\r\n\n\r\n(அல்லாஹ்வுக்குக் கீழ்ப்படியுங்கள், தூதருக்கும் கீழ்ப்படியுங்கள், உங்கள் செயல்களைப் பாழாக்கி விடாதீர்கள்.) சில பாவங்கள் தங்கள் செயல்களை அழித்து விடுமோ என்று அவர்கள் அஞ்சத் தொடங்குவதற்கு இது காரணமாக அமைந்தது.\" இப்னு உமர் (ரழி) அவர்கள் கூறியதாவது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் தோழர்களாகிய நாங்கள், அல்லாஹ் பின்வரும் வசனத்தை இறக்கும் வரை அனைத்து நற்செயல்களும் (நிச்சயம்) ஏற்றுக்கொள்ளப்படும் என்றே கருதி வந்தோம்:\n\r\n\n\r\nأَطِيعُواْ اللَّهَ وَأَطِيعُواْ الرَّسُولَ وَلاَ تُبْطِلُواْ أَعْمَـلَكُمْ\n\r\n\n\r\n(அல்லாஹ்வுக்குக் கீழ்ப்படியுங்கள், தூதருக்கும் கீழ்ப்படியுங்கள், உங்கள் செயல்களைப் பாழாக்கி விடாதீர்கள்.) எனவே, 'எமது செயல்களை அழித்துவிடக் கூடியது எது?' என்று எங்களுக்குள் ஒருவருக்கொருவர் கேட்டுக் கொண்டோம். 'பெரிய பாவங்கள், நரக நெருப்பைத் தேடித்தரும் மாபெரும் குற்றங்கள் மற்றும் மானக்கேடான செயல்களே அவை' என்று நாங்கள் கூறிக்கொண்டோம். அப்போது அல்லாஹ் பின்வரும் வசனத்தை இறக்கினான்:\n\r\n\n\r\nإِنَّ اللَّهَ لاَ يَغْفِرُ أَن يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَن يَشَآءُ\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் தனக்கு இணை கற்பிக்கப்படுவதை மன்னிக்க மாட்டான்; அதைத் தவிர மற்றவற்றைத் தான் நாடியவர்களுக்கு மன்னிப்பான்.) (4:48). இந்த வசனம் இறங்கிய பிறகு நாங்கள் அவ்வாறு (உறுதியாகக்) கூறுவதை நிறுத்திக் கொண்டோம். அதன் பிறகு, பெரும் பாவங்கள் மற்றும் மானக்கேடான செயல்களில் ஈடுபட்டவர்களைக் குறித்து அஞ்சினோம்; அதே சமயம் அவ்வாறு செய்யாதவர்கள் விஷயத்தில் (அல்லாஹ்வின் அருளைப் பெற) நம்பிக்கை வைத்தோம்.\"\n\r\n\n\r\nபிறகு அல்லாஹ் தன் முஃமினான (நம்பிக்கை கொண்ட) அடியார்களுக்குத் தனக்கும் தன் தூதருக்கும் கீழ்ப்படியுமாறு கட்டளையிடுகிறான். இது அவர்களுக்கு இம்மையிலும் மறுமையிலும் மகிழ்ச்சியைத் தரும். மேலும் மார்க்கத்தை விட்டு வெளியேறுவதையும் (மதமாற்றத்தையும்) அவன் தடை செய்கிறான்; ஏனெனில் அது அவர்களின் செயல்களை அழித்துவிடும். அதனால் அவன் கூறுகிறான்:\n\r\n\n\r\nوَلاَ تُبْطِلُواْ أَعْمَـلَكُمْ\n\r\n\n\r\n(உங்கள் செயல்களைப் பாழாக்கி விடாதீர்கள்.) அதாவது மார்க்கத்தை விட்டு வெளியேறுவதன் மூலம் (அவற்றை அழித்து விடாதீர்கள்). அதன்பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nإِنَّ الَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ اللَّهِ ثُمَّ مَاتُواْ وَهُمْ كُفَّارٌ فَلَن يَغْفِرَ اللَّهُ لَهُمْ\n\r\n\n\r\n(நிச்சயமாக எவர்கள் நிராகரித்து, அல்லாஹ்வின் பாதையை விட்டும் தடுத்து, பிறகு காஃபிர்களாகவே மரணிக்கிறார்களோ, அவர்களை அல்லாஹ் ஒருபோதும் மன்னிக்க மாட்டான்.)\n\r\n\n\r\nஇது அவனது இந்த வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\nإِنَّ اللَّهَ لاَ يَغْفِرُ أَن يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَن يَشَآءُ\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் தனக்கு இணை கற்பிக்கப்படுவதை மன்னிக்க மாட்டான்; அதைத் தவிர மற்றவற்றைத் தான் நாடியவர்களுக்கு மன்னிப்பான்.) (4:48). பிறகு அல்லாஹ் முஃமினான அடியார்களை நோக்கிக் கூறுகிறான்:\n\r\n\n\r\nفَلاَ تَهِنُواْ\n\r\n\n\r\n(எனவே நீங்கள் மனம் தளராதீர்கள்.) அதாவது எதிரிகளுக்கு முன்னால் பலவீனமடைந்து விடாதீர்கள்.\n\r\n\n\r\nوَتَدْعُواْ إِلَى السَّلْمِ\n\r\n\n\r\n(மேலும் சமாதானத்தை வேண்டாதீர்கள்.) அதாவது நீங்கள் அதிக எண்ணிக்கையிலும் போர் ஆயத்தங்களிலும் வலுவாக இருக்கும் நிலையில், நிராகரிப்பாளர்களிடம் பணிந்து போவதையோ அல்லது போரை நிறுத்தச் சொல்லி சமாதானம் கோருவதையோ அல்லாஹ் தடுத்துள்ளான். எனவேதான் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَلاَ تَهِنُواْ وَتَدْعُواْ إِلَى السَّلْمِ وَأَنتُمُ الْأَعْلَوْنَ\n\r\n\n\r\n(எனவே நீங்கள் மேலோங்கி இருக்கும் நிலையில், மனம் தளர்ந்து சமாதானத்தை வேண்டாதீர்கள்.) அதாவது உங்கள் எதிரியை விட நீங்கள் மேலான நிலையில் இருக்கும் போது இவ்வாறு செய்யாதீர்கள்.\n\r\n\n\r\nமறுபுறம், முஸ்லிம்களை விட நிராகரிப்பாளர்கள் அதிக வலிமையுடனும் எண்ணிக்கையிலும் அதிகமாகவும் இருந்தால், அது முஸ்லிம்களுக்கு நன்மை பயக்கும் என்று இமாம் (தலைவர்) கருதினால், அவர் சமாதான உடன்படிக்கை செய்து கொள்ளலாம். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மக்காவிற்குள் நுழைய விடாமல் நிராகரிப்பாளர்கள் தடுத்தபோது, பத்து ஆண்டுகளுக்குப் போரை நிறுத்துவதற்கான உடன்படிக்கையை அவர்கள் முன்மொழிந்தார்கள்; அதற்கு நபி (ஸல்) அவர்களும் சம்மதித்தார்கள். இது அதைப் போன்றதுதான். பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَاللَّهُ مَعَكُمْ\n\r\n\n\r\n(அல்லாஹ் உங்களுடன் இருக்கிறான்.) இது எதிரிகளுக்கு எதிரான வெற்றியையும் வாகை சூடுதல் பற்றிய நற்செய்தியையும் உள்ளடக்கியுள்ளது.\n\r\n\n\r\nوَلَن يَتِرَكُمْ أَعْمَـلَكُمْ\n\r\n\n\r\n(அவன் உங்கள் செயல்களை (அதன் கூலியை) ஒருபோதும் குறைக்க மாட்டான்.) அதாவது அல்லாஹ் உங்கள் செயல்களை ஒருபோதும் செல்லாததாக்க மாட்டான், அவற்றை வீணாக்க மாட்டான் அல்லது அதன் பலனை உங்களுக்குத் தராமல் இருக்க மாட்டான். மாறாக, எவ்விதக் குறைவுமின்றி உங்கள் கூலிகளை அவன் முழுமையாக உங்களுக்கு வழங்குவான்.\" அல்லாஹ்வே மிக அறிந்தவன்."},"36":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=38\" class=\"link\">47:38</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:38 ஐ பார்க்கவும்"},"37":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=47&ayah=38\" class=\"link\">47:38</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 47:38 ஐ பார்க்கவும்"},"38":{"html":"<strong>இவ்வுலக வாழ்க்கையின் அற்பத்தன்மையை விளக்குவதும் (அல்லாஹ்வின் பாதையில்) செலவு செய்யத் தூண்டுவதும்</strong><br />\r\n<br />\r\nஇவ்வுலக வாழ்க்கையின் அற்பத்தன்மையையும் மதிப்பற்ற தன்மையையும் விவரிக்கும் விதமாக அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةُ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">لَعِبٌ</span> <span class=\"quran-arabic-font text-success\">وَلَهْوٌ﴿</span><br />\r\n<br />\r\n(இவ்வுலக வாழ்க்கை விளையாட்டும் வேடிக்கையுமே தவிர வேறில்லை.) இதன் பொருள், அல்லாஹ்வின் திருப்திக்காகச் செய்யப்படும் காரியங்களைத் தவிர, இவ்வுலக வாழ்வின் முடிவு இத்தகையதாகவே இருக்கும் என்பதாகும். இதன் காரணமாகவே அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَإِن</span> <span class=\"quran-arabic-font text-success\">تُؤْمِنُواْ</span> <span class=\"quran-arabic-font text-success\">وَتَتَّقُواْ</span> <span class=\"quran-arabic-font text-success\">يُؤْتِكُمْ</span> <span class=\"quran-arabic-font text-success\">أُجُورَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَسْـَلْكُمْ</span> <span class=\"quran-arabic-font text-success\">أَمْوَلَكُمْ﴿</span><br />\r\n<br />\r\n(நீங்கள் ஈமான் கொண்டு, தக்வா (பயபக்தி) உடையவர்களாக இருந்தால், அவன் உங்களுக்கு உங்கள் நற்கூலிகளை வழங்குவான். மேலும், அவன் உங்களிடம் உங்கள் செல்வங்களை (முழுமையாகத் தியாகம் செய்யுமாறு) கேட்கமாட்டான்.) அதாவது, அவனுக்கு உங்களின் தேவை ஏதுமில்லை, அவன் உங்களிடம் எதையும் (அவனுக்காக) கேட்கவில்லை. உங்கள் ஏழைச் சகோதரர்களுக்கு நீங்கள் உதவ வேண்டும் என்பதற்காகவே உங்கள் செல்வத்திலிருந்து தர்மம் செய்யுமாறு அவன் கட்டளையிட்டான். அதன் நன்மையும் நற்கூலியும் உங்களுக்கே வந்து சேரும். பின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾إِن</span> <span class=\"quran-arabic-font text-success\">يَسْـَلْكُمُوهَا</span> <span class=\"quran-arabic-font text-success\">فَيُحْفِكُمْ</span> <span class=\"quran-arabic-font text-success\">تَبْخَلُواْ﴿</span><br />\r\n<br />\r\n(அவன் உங்கள் செல்வங்கள் அனைத்தையும் கேட்டு உங்களை வற்புறுத்தினால், நீங்கள் கஞ்சத்தனம் செய்வீர்கள்.) அதாவது, அவன் உங்களுக்கு அதிக நெருக்கடி கொடுத்தால், நீங்கள் கஞ்சர்களாகிவிடுவீர்கள். <span class=\"quran-arabic-font text-success\">﴾وَيُخْرِجْ</span> <span class=\"quran-arabic-font text-success\">أَضْغَـنَكُمْ﴿</span><br />\r\n<br />\r\n(மேலும் அவன் உங்கள் (உள்ளத்திலுள்ள) குரோதங்களை வெளிப்படுத்துவான்.) கத்தாதா (ரஹ்) அவர்கள் கூறினார்கள்: \"மக்களிடமிருந்து செல்வத்தைப் பிரித்தெடுப்பது குரோதங்களை வெளிப்படுத்தும் என்பதை அல்லாஹ் அறிவான்.\" நிச்சயமாக கத்தாதா (ரஹ்) அவர்கள் உண்மையையே கூறினார்கள். ஏனெனில், செல்வம் என்பது மக்களுக்கு மிகவும் பிரியமானதாகும்; அதைவிட தங்களுக்குப் பிரியமான ஒன்றிற்காகவே தவிர மக்கள் அதைச் செலவிட மாட்டார்கள். பின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾هَآ</span> <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">هَـؤُلاَءِ</span> <span class=\"quran-arabic-font text-success\">تُدْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">لِتُنفِقُواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">فَمِنكُم</span> <span class=\"quran-arabic-font text-success\">مَّن﴿</span><br />\r\n<br />\r\n(அறிந்து கொள்ளுங்கள்! அல்லாஹ்வின் பாதையில் செலவு செய்யுமாறு நீங்கள் அழைக்கப்படுகிறீர்கள்; ஆனால் உங்களில் கஞ்சத்தனம் செய்பவர்களும் இருக்கிறார்கள்.) அதாவது, அவர்கள் செலவிட மறுக்கிறார்கள். அல்லாஹ் தொடர்ந்து கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾يَبْخَلُ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَبْخَلْ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّمَا</span> <span class=\"quran-arabic-font text-success\">يَبْخَلُ</span> <span class=\"quran-arabic-font text-success\">عَن﴿</span><br />\r\n<br />\r\n(மேலும் எவர் கஞ்சத்தனம் செய்கிறாரோ, அவர் தனக்கே கஞ்சத்தனம் செய்து கொள்கிறார்.) அதாவது, அவர் தனது நற்கூலியைத் தானே குறைத்துக் கொள்கிறார்; அதன் தீய விளைவு அவரையே சாரும். <span class=\"quran-arabic-font text-success\">﴾نَّفْسِهِ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் அல்-ஃகனீ (தேவையற்றவன்) ஆவான்.) அல்லாஹ் எதற்கும் தேவையற்றவன்; ஆனால் மற்ற அனைத்தும் எப்போதும் அவனிடமே தேவையுடையவையாக உள்ளன. எனவேதான் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾الْغَنِىُّ</span> <span class=\"quran-arabic-font text-success\">وَأَنتُمُ</span> <span class=\"quran-arabic-font text-success\">الْفُقَرَآءُ﴿</span><br />\r\n<br />\r\n(அவன் தேவையற்றவன், நீங்களோ தேவையுடையவர்கள்.) அதாவது, குறிப்பாக அவனிடம் தேவையற்றவன். அல்லாஹ்வை 'அல்-ஃகனீ' (தேவையற்றவன்) என்று விவரிப்பது அவனது தவிர்க்க முடியாத பண்பாகும்; மறுபுறம், படைப்பினங்களை 'ஃபக்ர்' (தேவையுடையவை) என்று விவரிப்பது அவற்றின் தவிர்க்க முடியாத சுபாவமாகும். பின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَإِن</span> <span class=\"quran-arabic-font text-success\">تَتَوَلَّوْاْ﴿</span><br />\r\n<br />\r\n(நீங்கள் புறக்கணித்தால்,) இதன் பொருள், அவனுக்குக் கீழ்ப்படிவதிலிருந்தும் அவனது சட்டங்களைப் பின்பற்றுவதிலிருந்தும் நீங்கள் விலகிச் சென்றால் என்பதாகும். <span class=\"quran-arabic-font text-success\">﴾يَسْتَبْدِلْ</span> <span class=\"quran-arabic-font text-success\">قَوْماً</span> <span class=\"quran-arabic-font text-success\">غَيْرَكُمْ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَكُونُواْ</span> <span class=\"quran-arabic-font text-success\">أَمْثَـلَكُم﴿</span><br />\r\n<br />\r\n(அவன் உங்களுக்குப் பதிலாக வேறு ஒரு சமூகத்தைக் கொண்டு வருவான்; பின்னர் அவர்கள் உங்களைப் போன்று இருக்க மாட்டார்கள்.) அதாவது, மாறாக அவர்கள் அவனுக்குச் செவிசாய்த்து, அவனது கட்டளைகளுக்குக் கீழ்ப்படிந்து நடப்பவர்களாக இருப்பார்கள்.<br />\r\n<br />\r\nஇப்னு ஜரீர் (ரஹ்) அவர்கள் அபூ ஹுரைரா (ரலி) அவர்கள் மூலமாக அறிவிக்கிறார்கள்:<br />\r\nநபி (ஸல்) அவர்கள் இந்த வசனத்தை ஓதியபோது, தோழர்கள், \"அல்லாஹ்வின் தூதரே! எங்களை விட்டுவிட்டு, எங்களுக்குப் பகரமாக அல்லாஹ் கொண்டு வரக்கூடிய, எங்களைப் போன்று இருக்காத அந்த மக்கள் யார்?\" என்று கேட்டார்கள். அப்போது நபி (ஸல்) அவர்கள் சல்மான் அல்ஃபார்ஸீ (ரலி) அவர்களின் தொடையின் மீது தட்டினார்கள். பின்னர், \"இவரும் இவருடைய மக்களும்தாம் (அவர்கள்). என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது ஆணையாக! ஈமான் (எனும் இறைநம்பிக்கை) துரய்யா (நட்சத்திரத்தில்) தொங்கிக் கொண்டிருந்தாலும், பாரசீகத்தைச் சேர்ந்த சிலர் அதை அடைந்து கொள்வார்கள்\" என்று கூறினார்கள். இமாம் முஸ்லிம் (ரஹ்) அவர்களும், இமாம் திர்மிதி (ரஹ்) அவர்களும் இதனைப் பதிவு செய்துள்ளனர்.<br />\r\n<br />\r\nஇத்துடன் சூரா அல்-கிதாலின் தஃப்ஸீர் நிறைவுற்றது. எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது.<br />\r\n<br />","text":"இவ்வுலக வாழ்க்கையின் அற்பத்தன்மையை விளக்குவதும் (அல்லாஹ்வின் பாதையில்) செலவு செய்யத் தூண்டுவதும்\n\r\n\n\r\nஇவ்வுலக வாழ்க்கையின் அற்பத்தன்மையையும் மதிப்பற்ற தன்மையையும் விவரிக்கும் விதமாக அல்லாஹ் கூறுகிறான்: ﴾إِنَّمَا الْحَيَوةُ الدُّنْيَا لَعِبٌ وَلَهْوٌ﴿\n\r\n\n\r\n(இவ்வுலக வாழ்க்கை விளையாட்டும் வேடிக்கையுமே தவிர வேறில்லை.) இதன் பொருள், அல்லாஹ்வின் திருப்திக்காகச் செய்யப்படும் காரியங்களைத் தவிர, இவ்வுலக வாழ்வின் முடிவு இத்தகையதாகவே இருக்கும் என்பதாகும். இதன் காரணமாகவே அல்லாஹ் கூறுகிறான்: ﴾وَإِن تُؤْمِنُواْ وَتَتَّقُواْ يُؤْتِكُمْ أُجُورَكُمْ وَلاَ يَسْـَلْكُمْ أَمْوَلَكُمْ﴿\n\r\n\n\r\n(நீங்கள் ஈமான் கொண்டு, தக்வா (பயபக்தி) உடையவர்களாக இருந்தால், அவன் உங்களுக்கு உங்கள் நற்கூலிகளை வழங்குவான். மேலும், அவன் உங்களிடம் உங்கள் செல்வங்களை (முழுமையாகத் தியாகம் செய்யுமாறு) கேட்கமாட்டான்.) அதாவது, அவனுக்கு உங்களின் தேவை ஏதுமில்லை, அவன் உங்களிடம் எதையும் (அவனுக்காக) கேட்கவில்லை. உங்கள் ஏழைச் சகோதரர்களுக்கு நீங்கள் உதவ வேண்டும் என்பதற்காகவே உங்கள் செல்வத்திலிருந்து தர்மம் செய்யுமாறு அவன் கட்டளையிட்டான். அதன் நன்மையும் நற்கூலியும் உங்களுக்கே வந்து சேரும். பின்னர் அல்லாஹ் கூறுகிறான்: ﴾إِن يَسْـَلْكُمُوهَا فَيُحْفِكُمْ تَبْخَلُواْ﴿\n\r\n\n\r\n(அவன் உங்கள் செல்வங்கள் அனைத்தையும் கேட்டு உங்களை வற்புறுத்தினால், நீங்கள் கஞ்சத்தனம் செய்வீர்கள்.) அதாவது, அவன் உங்களுக்கு அதிக நெருக்கடி கொடுத்தால், நீங்கள் கஞ்சர்களாகிவிடுவீர்கள். ﴾وَيُخْرِجْ أَضْغَـنَكُمْ﴿\n\r\n\n\r\n(மேலும் அவன் உங்கள் (உள்ளத்திலுள்ள) குரோதங்களை வெளிப்படுத்துவான்.) கத்தாதா (ரஹ்) அவர்கள் கூறினார்கள்: \"மக்களிடமிருந்து செல்வத்தைப் பிரித்தெடுப்பது குரோதங்களை வெளிப்படுத்தும் என்பதை அல்லாஹ் அறிவான்.\" நிச்சயமாக கத்தாதா (ரஹ்) அவர்கள் உண்மையையே கூறினார்கள். ஏனெனில், செல்வம் என்பது மக்களுக்கு மிகவும் பிரியமானதாகும்; அதைவிட தங்களுக்குப் பிரியமான ஒன்றிற்காகவே தவிர மக்கள் அதைச் செலவிட மாட்டார்கள். பின்னர் அல்லாஹ் கூறுகிறான்: ﴾هَآ أَنتُمْ هَـؤُلاَءِ تُدْعَوْنَ لِتُنفِقُواْ فِى سَبِيلِ اللَّهِ فَمِنكُم مَّن﴿\n\r\n\n\r\n(அறிந்து கொள்ளுங்கள்! அல்லாஹ்வின் பாதையில் செலவு செய்யுமாறு நீங்கள் அழைக்கப்படுகிறீர்கள்; ஆனால் உங்களில் கஞ்சத்தனம் செய்பவர்களும் இருக்கிறார்கள்.) அதாவது, அவர்கள் செலவிட மறுக்கிறார்கள். அல்லாஹ் தொடர்ந்து கூறுகிறான்: ﴾يَبْخَلُ وَمَن يَبْخَلْ فَإِنَّمَا يَبْخَلُ عَن﴿\n\r\n\n\r\n(மேலும் எவர் கஞ்சத்தனம் செய்கிறாரோ, அவர் தனக்கே கஞ்சத்தனம் செய்து கொள்கிறார்.) அதாவது, அவர் தனது நற்கூலியைத் தானே குறைத்துக் கொள்கிறார்; அதன் தீய விளைவு அவரையே சாரும். ﴾نَّفْسِهِ وَاللَّهُ﴿\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் அல்-ஃகனீ (தேவையற்றவன்) ஆவான்.) அல்லாஹ் எதற்கும் தேவையற்றவன்; ஆனால் மற்ற அனைத்தும் எப்போதும் அவனிடமே தேவையுடையவையாக உள்ளன. எனவேதான் அல்லாஹ் கூறுகிறான்: ﴾الْغَنِىُّ وَأَنتُمُ الْفُقَرَآءُ﴿\n\r\n\n\r\n(அவன் தேவையற்றவன், நீங்களோ தேவையுடையவர்கள்.) அதாவது, குறிப்பாக அவனிடம் தேவையற்றவன். அல்லாஹ்வை 'அல்-ஃகனீ' (தேவையற்றவன்) என்று விவரிப்பது அவனது தவிர்க்க முடியாத பண்பாகும்; மறுபுறம், படைப்பினங்களை 'ஃபக்ர்' (தேவையுடையவை) என்று விவரிப்பது அவற்றின் தவிர்க்க முடியாத சுபாவமாகும். பின்னர் அல்லாஹ் கூறுகிறான்: ﴾وَإِن تَتَوَلَّوْاْ﴿\n\r\n\n\r\n(நீங்கள் புறக்கணித்தால்,) இதன் பொருள், அவனுக்குக் கீழ்ப்படிவதிலிருந்தும் அவனது சட்டங்களைப் பின்பற்றுவதிலிருந்தும் நீங்கள் விலகிச் சென்றால் என்பதாகும். ﴾يَسْتَبْدِلْ قَوْماً غَيْرَكُمْ ثُمَّ لاَ يَكُونُواْ أَمْثَـلَكُم﴿\n\r\n\n\r\n(அவன் உங்களுக்குப் பதிலாக வேறு ஒரு சமூகத்தைக் கொண்டு வருவான்; பின்னர் அவர்கள் உங்களைப் போன்று இருக்க மாட்டார்கள்.) அதாவது, மாறாக அவர்கள் அவனுக்குச் செவிசாய்த்து, அவனது கட்டளைகளுக்குக் கீழ்ப்படிந்து நடப்பவர்களாக இருப்பார்கள்.\n\r\n\n\r\nஇப்னு ஜரீர் (ரஹ்) அவர்கள் அபூ ஹுரைரா (ரலி) அவர்கள் மூலமாக அறிவிக்கிறார்கள்:\n\r\nநபி (ஸல்) அவர்கள் இந்த வசனத்தை ஓதியபோது, தோழர்கள், \"அல்லாஹ்வின் தூதரே! எங்களை விட்டுவிட்டு, எங்களுக்குப் பகரமாக அல்லாஹ் கொண்டு வரக்கூடிய, எங்களைப் போன்று இருக்காத அந்த மக்கள் யார்?\" என்று கேட்டார்கள். அப்போது நபி (ஸல்) அவர்கள் சல்மான் அல்ஃபார்ஸீ (ரலி) அவர்களின் தொடையின் மீது தட்டினார்கள். பின்னர், \"இவரும் இவருடைய மக்களும்தாம் (அவர்கள்). என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது ஆணையாக! ஈமான் (எனும் இறைநம்பிக்கை) துரய்யா (நட்சத்திரத்தில்) தொங்கிக் கொண்டிருந்தாலும், பாரசீகத்தைச் சேர்ந்த சிலர் அதை அடைந்து கொள்வார்கள்\" என்று கூறினார்கள். இமாம் முஸ்லிம் (ரஹ்) அவர்களும், இமாம் திர்மிதி (ரஹ்) அவர்களும் இதனைப் பதிவு செய்துள்ளனர்.\n\r\n\n\r\nஇத்துடன் சூரா அல்-கிதாலின் தஃப்ஸீர் நிறைவுற்றது. எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது."}}};})(self);
